/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190307-3","meetingId":"r01-c-budget","date":"2019年3月7日","dateIso":"2019-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３１年度品川区一般会計予算","agenda":"平成３１年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"おはようあります。私は、１６７ページ、コミュニティＦＭ番組制作費、そして１６９ページ、犯罪被害者支援、この２点で伺ってまいります。コミュニティＦＭについてなのですが、今年度に開局が予定されております。開設準備の最新の情報を教えてください。というのは、何か１つで十分というものではなくて、いろいろな要素、手段が必要だと思っています。その中でも大変有効である。この辺を教えてください。","respondent":"柏原企画調整課長、木村報道・プロモーション担当課長","answer":"ＦＭ開局についてのご質問です。私からは、開局に係るスケジュール、現況についてご説明いたします。例えばバイクに機材を積んで区内を回って、イベント会場から生中継というような形も想定しておるところです。それから、通常のＦＭラジオ、それからインターネットでの配信も予定しておるところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"犯罪被害者支援のほうを伺います。タイトルが、「小５の息子を殺害された遺族に『数百万円』の経済的負担…なぜ？では、なぜこの家族、被害に遭われたほうが苦しんでいるかというと、葬儀費用や弁護士費用で２００万円ほど苦労されているという番組だったのです。品川区における犯罪被害者の支援という点で、現状の主な点と最近の事例等、ご相談内容等があれば、まずそれを教えてください。","respondent":"中元広報広聴課長","answer":"その際には、やはり犯罪被害者支援の窓口が警視庁にもありますので、そちらから連絡がございまして、区での受け入れについて連絡会議を開き、また先に、戸籍住民課の窓口にお届けに来庁された際にも受付において、プライバシーに配慮した適切な対応をさせていただいたり。","voiceIndex":7,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"大半、８割方は、それに関係する条例が制定されておりますが、東京都は空欄なのです。条例に限らず、いろいろな普及促進事業として展開していく必要性を感じますし、とにかく、今、何があったから対応するのではなくて、転ばぬ先のつえではないですが、やはり早目早目に先を想定した取組みの必要性を感じたものですから、現時点での展開と先行きへの抱負を教えていただければと思います。","respondent":"中元広報広聴課長","answer":"品川・大崎・大井・荏原警察署の方々においでいただき、区役所の第２庁舎３階ロビー等に特設相談窓口を開設して、またその際、犯罪被害者等の支援に関するチラシやパンフレットの配布やパネル展示などで、区民の方々への啓発活動に努めてあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"１８７ページ、自動通話録音機購入、１９１ページ、総合区民会館運営費、１６７ページ、ホームページ等経費、２０１ページ、戸籍事務費についてお伺いいたします。最初に自動通話録音機についてです。平成２９年度は５００台、そして平成３０年度は当初予算５００台から補正予算も組んでいただき、会派としても要望させていただきましたが、追加され１,０００台となっております。","respondent":"菅生活安全担当課長","answer":"当初、東京都の助成制度が平成３０年中で終了する予定でしたので、区の単独予算で組ませていただいていましたけれども、その後、東京都がさらに今後２年間、この助成制度を継続するということが決まる見込みですので、それが決定しましたら。","voiceIndex":12,"id":"exchange-004"},{"speaker":"新妻委員","kind":"提案","question":"品川区でも被害が増えているということが確認されました。ここで、目黒区の対策を紹介したいと思います。委員長に許可を得まして、タブレット上に資料を示しておりますので、ご覧いただきたいと思います。区民の皆様の大切な財産、そしてまた事件に巻き込まれないようにしていくために、これは有効なものかと思いますが、区のお考えをお伺いいたします。","respondent":"菅生活安全担当課長","answer":"限られた予算ですので、やはり１台でも多く自動通話録音機の普及促進をまず図ってまいりたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"総合区民会館運営費について伺います。私は、平成２９年決算特別委員会のときに、区民集会所の使用料金の支払いを現金ではなく振り込みにしてほしいということを要望させていただきました。これを何とか振り込み等にしてもらいたいというご要望をいただいております。このモニターを新しいモニターにかえる時期が今後いつぐらいになるのか、そういうお考えがあるのかどうか、お伺いします。","respondent":"伊崎地域活動課長、立川文化観光課長","answer":"今回につきましては、検討期間が限られていたこともあり、調整に至らずというところがございました。引き続き検討は進めて、利便性の向上に努めていきたいと考えております。きゅりあんの支払い方法につきまして、現状、現金持参ということでやっております。ただ、文化振興事業団としましても課題として認識しておりますので、現在、検討を進めているです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"新妻委員","kind":"提案","question":"私も、非常にいいもので、使いやすいと思っているのですが、まず１点、情報が集約され、便利になりましたけれども、作成の経緯をお伺いいたします。もう一つが、若いひとり暮らしの区民の方とお話をしたときに、品川区に対して何を求めるかを伺ったら、「病気をしたときに買い物などの支援が欲しい。何か、そういう若い方に特化したホームページを作成していただきたいと思いますが、いかがでしょうか。","respondent":"大串福祉計画課長、木村報道・プロモーション担当課長","answer":"介護・在宅医療・障害福祉情報のサイトの発展経緯といったところです。こちらにつきましては、一般の区民の方に対しまして、療養生活に役立つ在宅医療の情報といったものを掲示しようということで、昨年１２月に開設したものです。若い方に特化したホームページというご提案です。今の介護・在宅医療・障害福祉のページ内にあるもの、それからご提案いただいたことも含めまして、前向きに考えてまいりたいと思っています。","voiceIndex":19,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に、オリジナル出生届についてお伺いいたします。会派として要望してまいりましたオリジナル婚姻届が平成２９年１１月に配布されまして、今回出生届が作成され、３月３日から既に配布が進んでおります。そして、既に配布が始まってしまいましたけれども、もし作成されるのであれば、ファイルだけでも後から欲しいという方にはぜひ差し上げていただきたいと思いますが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"それで、新年度予算でオリジナル婚姻届の予算は組んでおりましたが、オリジナル出生届のクリアファイルの予算は組んでいないのが現状ではありますが、それについても区民の皆様の要望等を酌み取りながら温かいデザインのものを考えていければと。","voiceIndex":22,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職員給与費全般と、１７５ページの職員研修費に関連して、区政の基本姿勢を伺います。改善をこの間ずっと求めていましたが、どこまで改善されたのか、していないのか、質問したいと思います。しかし、日本は１８本の労働時間関連条約を１本も批准していない。質問です。品川区役所の長時間労働は是正されたのでしょうか。年休取得は改善されているのかどうか、具体的に数字で示してください。","respondent":"黒田人事課長","answer":"年休の取得状況ですが、平成３０年１月から１２月の平均の年休取得日数が１３.９日でございまして、昨年、平成２９年１月から１２月の平均の年休取得日数が１３.３日ですので、これもわずかではありますが、やや取得率が増えたという意味では。","voiceIndex":25,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"提案","question":"長時間労働とは、ＩＬＯでは、残業を含めて週４８時間労働と定義しています。週の労働時間を４０時間とすれば、残業は週８時間。この間、総務委員会に提案された条例の中で上限を定めるといって、この上限が１カ月４５時間以下、年間３６０時間以下、これと比べてもはるかに多い担当課がたくさんあるわけですけれども、こういうところの改善をするために何が必要であると課長はお考えなのか教えてください。","respondent":"黒田人事課長","answer":"先ほど申し上げたとおり、全庁的に平均しますと月で約１３時間弱ですので、職場の特性に応じて、どうしても超勤が多くなってしまう職場と、施設のようなところでありますと、シフト勤務等で開館している時間に職員を配置しなければならないというところで。","voiceIndex":27,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２０１７年度の年休取得は若干変わりましたが、課長、お願いだから平均で言わないでください。組合からは、「職場の実態に見合った正規職員の配置を求めています」と長時間労働の是正を求められています。職場からは要求がいっぱい出ていると思うのですけれども、質問しますが、仕事量が増えていることをまず認めるのかどうか。そして、仕事量にふさわしい職員体制となっているのかどうか、改めて伺います。","respondent":"黒田人事課長","answer":"その中では、アウトソーシングという、いわゆる外注というものも活用しながら、やるべき仕事を担ってまいりたいと考えています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、労働条件の悪化が生まれていますし、非正規労働や不安定雇用がどんどん増大しています。自治体には、区内企業の働き方を改善させていく大きな役割がありますので、ぜひ必要な人員をきちんと配置していただきたいと思います。職員定数の見直しの話がありましたが、増減の考え方、増の場合・減の場合の基本的な考え方を教えてください。","respondent":"黒田人事課長","answer":"数値ではそうなりますが、例えば窓口で区民対応をしている職場でありますと、例えば平均すれば１件当たり何分という時間は出ると思いますが、相談の内容によっては長くかかったりというところもありますので。","voiceIndex":31,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"職場のいろいろな状況を勘案した中で、長時間労働が是正されていると考えるのか、何が不足していると考えるのか、また年休の取得状況もそうです。基本的に自由に使えるはずの年休が、さっき１３.３日ですか、保育園などは７.８日でしたよね。こういった状況で、本当に健康に働いていただける条件が整っていないと思いますが、何が不足しているとお考えでしょうか。","respondent":"黒田人事課長","answer":"定数条例の中でいくと、増要素があるところにつきましては、当然、増していくという中で、また今回の業務改善という取組みの中でも、いろいろ仕事のやり方も工夫していくというところも１つあると思いますので、そういった意味では。","voiceIndex":33,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職場からは、人手がないと悲鳴が上がっています。やり方の工夫では改善し切れない部分、ぜひ職員増を適切に行っていただきたいと強く求めます。次に行きますが、職員研修において、憲法、そして地方自治を、どのように公務員として身につけさせているのか教えてください。","respondent":"黒田人事課長","answer":"職員研修ですが、区では人材育成の基本方針を定めまして、その中で、いわゆる育成層でありますとか監督層、管理層というふうに、それぞれの職員の経験年次・職層に応じた研修計画を立てているところですが、憲法につきましては、特に新任研修の際に、地方公務員制度の中で。","voiceIndex":35,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私も品川区に入区したときに、公務員は全体の奉仕者であるという教育を受けました。具体的に言うと、２３区で最低の福祉、ここにあらわれているのではないかと思っています。職員の方は研修を受けていますが、区長をはじめ部長など、政策をつくる方々に、やはりこの姿勢が欠けていると私は思いますが、この点、ぜひ改善を求めますが、いかがでしょうか。","respondent":"黒田人事課長","answer":"これからも引き続き、適切な研修の実施に取り組んでまいりたいと考えております。","voiceIndex":37,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"私からは、１８５ページの歩行喫煙防止推進経費、１９７ページの高齢者スポーツの普及からの質問です。最初に、１８５ページの中ほどより下にある歩行喫煙防止推進経費、８,１１２万４,０００円からの質問ですけれども、路上で喫煙行為をするのは、受動喫煙による健康被害や事故等の危険性をももたらすため、歩行喫煙禁止になっている自治体がほとんどであろうと思っています。","respondent":"菅生活安全担当課長","answer":"そういった意味では、ある程度、歩行喫煙やポイ捨てに関する意識というものが浸透してきているのかと考えているところです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問・要望","question":"だんだん効果が出てきているということでありますけれども、これからもまたどんどん取り締まりをお願いしたいと思います。本区内での、年間、ポイ捨てによる火災や、また人的被害等があれば、品川区内での被害というものがあればお聞かせいただきたいと思います。","respondent":"菅生活安全担当課長","answer":"私のほうでは、ポイ捨て等による火災の発生状況というのは把握しておりません。","voiceIndex":42,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"わかりました。被害を起こした加害者たちに対して、どのような罰が課せられたような例が今まであったのか、あればどのような罰が課せられたかお聞かせいただきたいと思います。","respondent":"菅生活安全担当課長","answer":"これまで私のほうで、たばこのポイ捨てによる火災というのは把握はしておりませんけれども、通常、例えば家屋が燃えたなどということであれば、当然、放火、いわゆる刑法罰というところで、現住建造物等放火などの犯罪行為ということにもなりますし。","voiceIndex":44,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"わかりました。本区においても、歩行喫煙防止のための巡回員を置き、今、どんどん成果が出てきているということでありますけれども、喫煙者に対して警告を発することによって、いろいろトラブルになることも多いことと思いますし、何の権限もない巡回員です。これに対して、本来であればもう少し厳しい何かがあればいいわけでありますけれども、そのようなことというのは考えられないでしょうか。","respondent":"菅生活安全担当課長","answer":"生活安全サポート隊は、確かにそういった強制力はございませんけれども、これは区の条例で定められておりますし、また過料を取る際には、喫煙者に対して条例の趣旨とか、受動喫煙等で被害を受ける人がいますということは丁寧に説明しながら、協力をお願いしているような状況です。","voiceIndex":46,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"区民が、また都民が、平気でポイ捨てや歩行喫煙を行うという日本人のマナーの、悪いところを見せるよりも、やはり世界のスポーツの祭典であるオリンピック・パラリンピックが開催され、世界から注目されるわけでありますので、大変マナーの良い国として注目されるためにも、これから時間があまりありませんけれども、どのように指導していくのか、その点についてお聞かせいただきたいと思います。","respondent":"菅生活安全担当課長","answer":"本年度からＪＴとたばこ商業協同組合とも、マナーアップキャンペーンというものを実施しておりまして、これは指定喫煙所でやっているのですけれども、直接、喫煙者の方に、これからオリンピック・パラリンピックに当たって日本人のマナーのよさを示すということで、今後。","voiceIndex":48,"id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"次に１９７ページですけれども、上から２行目、高齢者スポーツの普及、５９万円余からです。体になるべく負担をかけずに続けられるスポーツをして、仲間と楽しく体を鍛えることができれば、長生きできるのではと考えておりますが、高齢化している社会ですが、運動して若返りましょうを合い言葉に、ネット上には５つの動画が紹介されておりました。そういう点についてお聞かせください。","respondent":"池田スポーツ推進課長","answer":"私どもスポーツ推進課でやっている事業についてですけれども、高齢者のスポーツ普及というところで、いきいきウオーキングというものを年４回実施しています。","voiceIndex":50,"id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"ぜひお願いしたいと思いますが、紹介されている運動というものが、太極拳、それからボーリング、ノルディックウオーキング、トレッキング、グラウンドゴルフ等が紹介されています。本区は、この競技の中で、一番推していくもの、何を皆さんに勧めていきたいと思っているのでしょうか。お聞かせください。","respondent":"池田スポーツ推進課長","answer":"こちらに載っていないところではありますけれども、昨年、しながわ体操を私どもで制作いたしました。区民の皆様には、ぜひ１日１回、しながわ体操をやっていただいて、健康を増進していただければということを一番望んでいるところです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"１７３ページの人権に関わる意識調査をまず伺いますけれど、結構、人権啓発課で意識調査はしていたと思うのですけれども、新たにまたやるのでしょうか。この結果をいわゆる施策にどのように活用していくのか、お伺いします。","respondent":"島袋人権啓発課長","answer":"人権に関わる意識調査は、前回、平成２６年度に実施しまして、５年ごとにする調査ですので、次年度に実施する予定です。","voiceIndex":55,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"２１０ページの監査委員費に関連して監査事務についてお伺いします。監査委員におかれましては、年２回、監査を実施していると思うのですけれども、前期・後期それぞれどれだけの数の部課を対象としているのか教えていただきたいのと、その結果をどのように所管に報告しているのか、また区民にはどのように周知しているか、具体的に教えてください。","respondent":"小川監査委員事務局長","answer":"委員ご指摘のとおり、監査は地方自治法に基づきまして、定期監査を前期・後期に分けて年２回、実施しています。前期につきましては全５３の組織を対象に、また後期につきましては庁外施設を、毎年、３０前後の施設を対象に実施しています。","voiceIndex":57,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"企画調整課を通して流れていくというお話なのですけれども、いわゆる監査結果を受けて、企画部門ではどのように所管に通知して、その結果を活かしているか、教えてください。","respondent":"柏原企画調整課長","answer":"それぞれの指摘については、各部署ごとに出ておるのですけれども、全庁的にかかわることもありますので、そういったことは全庁にかかわるのだということで、改めて企画調整課から全庁に、教育委員会は庶務課が改めてやっておりますけれども、全庁的に我々から周知して。","voiceIndex":59,"id":"exchange-025"},{"speaker":"藤原委員","kind":"意見","question":"監査委員事務局長、今、企画調整課から、そういう形で周知し改善に努めておりますというお話が出たのですけれども、今、企画調整課ではそういうふうにしていますという話は出ましたが、監査委員事務局長から見て、指摘を出した思いというのは通じていますか。","respondent":"小川監査委員事務局長","answer":"全課で監査の結果を受けとめることによりまして、より適切な事務執行がなされていくように、ひいてはよりよい区政に誘導していけたらという思いで、今後も監査を実施していく所存です。","voiceIndex":61,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"１８７ページの防犯設備整備助成金なのですけれども、これは防犯カメラについてお伺いしますが、私は防犯カメラの威力といいますか、効果というのをすごく感じたのは、去年か一昨年、渋谷区のスクランブル交差点で、たしか軽自動車か何かを揺らしている方が、防犯カメラでずっと警視庁が追跡して、その方たちを逮捕したというようなニュースを見たのですけれども、その辺の防犯カメラの効果について。","respondent":"菅生活安全担当課長","answer":"非常に有効なものだと考えております。","voiceIndex":63,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味において、もし警視庁に４月から戻られたときに、改めて東京都民の安心安全を守っていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"菅生活安全担当課長","answer":"まだ内示はありませんけれども、一応、今の予定ですと、今月いっぱいで、４月から警視庁に戻るのかと思っているところです。品川区には、大井警察署のときを除きますと、ちょうど３年間、勤務をするということで、本当にご縁を感じているところです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"人権啓発費について伺います。男女共同参画センター開設３０周年記念事業では、性の多様性について大きく取り上げていくと伺っています。昨年１２月のしながわ人権のひろば２０１８で、生活者ネットワークが求めていた「心に響かせるＤＶ根絶パネル」の展示が実現したことは評価しています。なぜ今回、２４枚全ての展示ができなかったのか、また展示を見た方からの感想や評価が届いていたらご報告ください。","respondent":"島袋人権啓発課長","answer":"引き続き、パープルリボンの週間のときに関しましては、人権啓発課の男女共同参画センター交流室におきまして、何かしらの展示等を考えていきたいと考えているところです。","voiceIndex":70,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"わかりました。いつか、２４枚全てがそろったパネル展示ができたらと要望いたします。暴力に関して、する側も受ける側も、まだ社会の中でのしつけや愛のむちだと容認してしまう状況が日本社会の中にいまだにあります。あらゆる暴力を自覚させ、発生させないための取組み、例えば若い世代や子どもにも伝わる方法での周知を求めますが、関係部署との連携が、現在どのようにとられているのか伺います。","respondent":"島袋人権啓発課長","answer":"こちらは１１月１１日からということで、期間は短いわけではありますけれども、確実に関係部署との連携をとりつつ行ってまいっているところです。やはり委員がおっしゃるように、虐待問題は決して人ごとではない。","voiceIndex":72,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ関係部署と連携し、周知徹底を進めてほしいと要望いたします。防犯に行きます。その観点から質問します。そして、逃げる訓練を定期的に行っていただきたいと求めますが、いかがでしょうか。まもるっちは防犯システムです。来年度のまもるっちのパンフレットや、まもるっち通信では、教育委員会とのそごがない、まずは逃げ、身の安全を確保するということが記載されているのか、伺います。","respondent":"菅生活安全担当課長","answer":"したがって、逆に、ただ逃げるということだけをまず考えるということになってしまいますと、どうしても、大きな声を出す、大声を出して周囲に知らせるといったことを怠ってしまうということもありますので、まずは逃げるのだけれども、当然、まもるっちも引くのだということは。","voiceIndex":74,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"市民科の中では、まずは逃げ、身の安全を確保してから鳴らすということを示しています。だから、今の答弁にあったとおり、やはり関係各課で認識が違うのです。ですので、きちんと認識を統一してほしい。そういうことをきちんとおっしゃられているのだから、きちんと子どもたちがそういうときに対応できるような周知徹底をしてほしいと思いますが、いかがでしょうか。","respondent":"菅生活安全担当課長","answer":"いろんなそのときの状況によって、児童たちが当然、大声を出したり、あるいは周囲に知らせるということを選択するということは当然考える。その状況においてやるべきだと考えています。","voiceIndex":76,"id":"exchange-032"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、１７１ページ、成人式経費、１６４ページ、広報広聴費、時間があれば１９９ページのオリンピック・パラリンピック開催周知事業についてお伺いいたします。成人式経費についてであります。２０２２年に民法が改正され、成人年齢が１８歳に引き下げとなる予定であります。そうすると、原則、それ以降の成人式は、１８歳が対象になるかと思います。","respondent":"米田総務課長","answer":"法律上は成年ということで、成人という言われ方はしておりませんので、その辺のところも含め、成人と言われる年齢がどこがふさわしいのか。この辺のところを、もう一度、見きわめ、検討して、成人式の開催の年齢について、また検討していきたいと考えています。","voiceIndex":79,"id":"exchange-033"},{"speaker":"芹澤委員","kind":"質問・要望","question":"品川区においてそれをどうするのかを少し確認したいのです。それで、実数が分かればで結構ですが、１８歳というのは、会社員などが少なく、学生の数のほうが多い点で、これまでの２０歳よりも参加率というのは増えてくると思いますので、３学年同時になった場合に、何名ぐらいの見込みで、施設は目星としてあるのかも教えてください。","respondent":"米田総務課長","answer":"そういうことも含めまして、どういう年齢層、３学年一遍にやるのか、また別のやり方をとるのかということについては、今後さらに検討を重ねていきたいと思ってあります。","voiceIndex":81,"id":"exchange-034"},{"speaker":"芹澤委員","kind":"意見","question":"やはり１８歳が特段、参加率が上がっていくと思っていますので、そもそも１８歳だけ単独でやったとして、きゅりあんに入るのかというところも少し疑問であります。まだ日は先でありますが、行政としていつごろの期日をもって対応というのを決めていくのかというのを最後にお聞かせください。","respondent":"米田総務課長","answer":"その辺も踏まえまして、今後、その辺の成人式のあり方について、さらに検討を進めていければと思ってあります。","voiceIndex":83,"id":"exchange-035"},{"speaker":"芹澤委員","kind":"質問","question":"続いて広報広聴費について伺います。位置情報サービスの活用について伺います。行政情報の周知として、皆様においては常に改良を進めていただいていると思いますが、特に若い世代については、紙媒体に目を通さないというのが１つの課題であると思っています。はＬＩＮＥ Ｂｅａｃｏｎ等を用いた情報提供の見解をお聞かせください。","respondent":"中元広報広聴課長","answer":"新しい技術がどんどん出てまいりますので、その辺のところは広報広聴課としましても情報収集をし、今後視野に入れながら、実際、自治体での活用事例やセキュリティーの問題ですとか、私も少し報道で見たら、勝手に情報が来ることに対して違和感を覚える若い方の発言も。","voiceIndex":85,"id":"exchange-036"},{"speaker":"芹澤委員","kind":"確認","question":"続けてＬＩＮＥについてですが、今、自治体でＬＩＮＥ＠というのを使って情報提供しているところが増えていますので、そこの点も１点確認したいのと、あとは、今、品川区の公式アプリが何個か出ているかと思います。ＬＩＮＥ＠を使う姿勢についてと、公式アプリにＢｅａｃｏｎを技術的に追加できるのかをお聞かせください。","respondent":"中元広報広聴課長","answer":"ＬＩＮＥ＠というものを使われている自治体につきましては、情報収集をさせていただきたいと考えています。現在、ココシルという、まちあるきのアプリがありますが、こちらは位置情報を活用させていただいた形で既にリリースをしています。","voiceIndex":87,"id":"exchange-037"},{"speaker":"つる委員","kind":"確認","question":"１６２ページ、総務管理費、１８１ページ、町会・自治会館建設等補助、１９７ページ、少年少女スポーツ普及事業、１９９ページ、パラリンピック競技事前キャンプ誘致、２０３ページ、戸籍住民課レイアウト変更経費について伺っていきたいと思います。それがいつ行われるのかということと、それから具体的にキャンプの受け入れの時期がいつごろを予定して、今、準備を進めているのか。そこを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"調印式は、基本的に受け入れしますということで、具体的なことはまた後になるのですが、調印式自体は３月中に実施する予定で、今、調整をしています。","voiceIndex":90,"id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"調印式は今月中、受け入れが６月下旬から７月にかけて２週間、１０名程度ということで確認させていただきました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今、委員からご提案のありました、例えばボッチャですと、これは老若男女、障害の有無にかかわらず誰でもできる、本当にすばらしいスポーツだと認識しておりまして、ボッチャでの交流というのも考えられますし、あとは障害者施設での交流といったものも。","voiceIndex":92,"id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"今回、ボッチャ、また事前キャンプ誘致で、全国的にも誘致やイベントなどがされているのかと調べる中で、当時は全然存じ上げなかったのですが、最近知った中では、もう２年前になりますでしょうか、１年半ぐらいでしょうか、天王洲でサイバーボッチャというイベントが行われたかと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２月に私どもで開いたパラリンピックスペシャルデーのときは、競技用車いすのＶＲ体験も含めたりして、なかなか好評を得たところですので、さまざまな形、手段を使って、パラリンピックスポーツの普及も考えていきたいと思いますので、今後研究を続けたいと考えています。","voiceIndex":94,"id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きます。総務管理費に関連して、これも一般質問で質問させていただいて、それに対するご答弁は、大きいくくりだったかと思いますので、具体的にお聞きしていきたいのです。学校行事などでも使用される表彰状などもあると思いますが、そうしたものに活用するよう考えていただきたいと思いますが、このあたりについてご答弁いただきたいと思います。","respondent":"中元広報広聴課長、黒田人事課長","answer":"ご提案のバナナペーパー等につきましては、今後、関係課で情報収集等を引き続き進めさせていただいて、どうしていくかという方向性も含めて、まずは情報収集のところから始めさせていただければと考えているところです。職員の表彰等で使う表彰状に活用できないかというお尋ねですが、表彰状を発注するには、区の紋章を刷り込んだり、表彰状として印刷にたえ得るかというところと、あと、筆耕というところで、筆で書いているところもありますので。","voiceIndex":96,"id":"exchange-041"},{"speaker":"つる委員","kind":"提案","question":"導入した当初年度なので、困難性もあるかと思いますけれども、その時期についての確認と、決算のときに、そうした財務書類、いつも年末に配付される時期ではなく、それが少しでも前倒しして決算の審議のときに活用できるようなタイミングで出てくるのかどうか、そのあたりを教えてください。","respondent":"品川財政課長","answer":"少し努力はしてみまして、うまく出せるようなタイミングがあるかどうかについては、また今後も検討していきたいと考えています。","voiceIndex":99,"id":"exchange-042"},{"speaker":"つる委員","kind":"意見","question":"最初の年度なので、いろいろ試行錯誤の中だと思いますけれども、議会としても、しっかりとそうした資料に基づいて決算の審議ができるというのが理想かと思います。それも公会計を導入する目的の一つかと思いますので、大変かと思いますけれども、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"会費制に移行するよう検討していただきたいということについてお伺いいたします。それこそまさに民業圧迫で、静岡県内の旅館の客を奪っているような結果になってしまっているので、品川区民の方が静岡県の旅館を利用すればいいだけの話であって、わざわざ品川区が保養所を持つ必要はないと考えておりますけれども、品川荘を含めた区民保養所の売却についてはいかがお考えでしょうか。","respondent":"米田総務課長、伊崎地域活動課長","answer":"そういった中で、今、品川区としてこういう形で、区有施設で９０分程度の時間をかけて初顔合わせというようなことでやっておる現状においては、会費を特に徴収しないで開催することが、今のところ妥当かと考えているところです。こちらの保養所の意義につきましては、やはり品川区の皆様が安心して保養施設としてご利用いただけるということ、それから、さまざまな町会・自治体をはじめとする団体が団体利用をしていただいているということなど。","voiceIndex":103,"id":"exchange-044"},{"speaker":"筒井委員","kind":"質問・要望","question":"その煙が家にまで入ってくるということなので、やはり駅前や商店街以外の、朝晩、通勤客が多い、人通りの多い時間帯に巡回の方を置いていただくなど、徹底して取り締まりを行っていただきたいのですけれども、いかがでしょうか。そのコンビニの前の灰皿は、今後、品川区としてどう対応していくのか。東京都受動喫煙防止条例では、どのような扱いになっていくのか、ご存じでしたらお知らせください。","respondent":"菅生活安全担当課長、川島健康課長","answer":"そういったところがあれば巡回したいと考えております。現状、例えばコンビニの角に吸い殻入れがあって、受動喫煙の被害があるというお話がありますと、私ども健康課でも、施設の管理者の方に配慮義務があるということで、お願いベースではありますが。","voiceIndex":106,"id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"ナイトライフ調査に行きますけれども、東京都でもＰＲＩＭＥ観光都市・東京ということで、ナイトライフ観光の推進をかなり強めておりますけれども、東京都と区の連携はどうされていくのかということと、やはりナイトライフ、ライトアップなどのスポットを見た後の品川区の個性ある飲食店の利用促進、ＰＲといった支援というのをぜひ行っていただきたいのですけれども、その点はいかがお考えなのでしょうか。","respondent":"立川文化観光課長","answer":"東京都との連携ですが、この事業自体が東京都観光財団の補助を受けて、経費面でまず連携しています。それから、スポットの関係なのですけれども、食事だけではなく、夜間の時間帯に楽しめるスポットについて、発掘を目的に現地調査を実施してまいります。","voiceIndex":109,"id":"exchange-046"},{"speaker":"筒井委員","kind":"意見","question":"ぜひ、そうしたライトアップとか、ハード面だけではなくて、ソフト面の飲食店のＰＲとか、ほかの催し物を見るだとか、いろいろ連携して、ぜひナイトライフ、夜の部分というのをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"１６３ページ、第２款総務費の第１項総務管理費の中の全庁共通プロジェクト推進経費、公有地活用等検討経費にかかわって、旧第一日野小学校跡地について伺います。私はこの問題を昨年１１月の決算特別委員会で伺い、さらに１２月の第４回定例会一般質問でも伺いましたが、区が区議会と区民にＴＯＣへの貸し付け期限と説明してきた２０２０年９月はもう来年であり、１年半後に迫りました。いかがでしょうか。","respondent":"柏原企画調整課長","answer":"現在はＴＯＣに貸し付けをしているというところもありますので、その期限が終わった後、どういった活用をしていくか、全庁的なところでどういった施設がよろしいかといったところの内容の精査といいますか、そういう調査といったところを内部で検討していくといった予定です。","voiceIndex":114,"id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"内部でということですけれども、昨年１２月の私の一般質問のご答弁の中で、事業内容については、ＴＯＣが検討を続けている段階だと。あるいはＴＯＣからは、まだ建て替えの意思はあると聞いていらっしゃると。そうしますと、ＴＯＣが来年、２０２０年９月以降も再び跡地の貸し付けを区に対して申し込んできたら、品川区としては再び貸し付けるということも選択肢の中に今あるのでしょうか。","respondent":"柏原企画調整課長","answer":"これまでも申し上げている部分ではあるかと思うのですけれども、法定上といいますか、双方の契約という行為におきましては、平成３４年度が事業用定期借地を活用した形での契約ですので、そちらの期間までの間は法定上は貸し付けというところで捉えているところです。","voiceIndex":116,"id":"exchange-049"},{"speaker":"おくの委員","kind":"質問","question":"今のご答弁は、少なくとも平成３４年以降は、これ以上、ＴＯＣが申し込んできても、区の意思としては貸し付ける予定はないのだと理解してよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"法定上といいますか、双方の契約が１０年間、定期借地権を使っておりますので、そこが契約の期限というところで捉えているものです。","voiceIndex":118,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"それで、向こうが新たに申し込んできた場合にはどうなるかということでお伺いしたのですけれども、その場合でも、新たに申し込んできても、もうこれ以上の契約に応じる意思は区としてはないということと、内部の検討でもそうなっていると理解しておいていいのでしょうかということなのですけれども、その辺をはっきり伺っておきたいのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"現段階といいますか、契約が１０年間の定期借地というところで期限を切っておりますので、それがいわゆる貸し付けの期限というところで捉えております。それで、その後の活用であったり、そういったところも、その辺を見据えた上での検討です。","voiceIndex":120,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は先日、不燃化特区に関して質問しました、品川区の耐震改修促進計画でも、区の方はその計画をやるに当たってアンケートをとっていらっしゃいます。それも私のその質問の中で引用させてもらいましたけれども、そのアンケートは結構いい結果というか、いいものだったと思います。そういうアンケートをとるなどしていただきたいと思いますけれども、その点はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"区有地の活用ですので、まず区としてどういった考え方といいますか、どういった活用ができるのかというのを検討する、いろいろ精査するというのが、まず第１段階といいますか、始めにあるものだと思ってあります。その後、いろいろな活用についてさまざまなご意見をいただく。","voiceIndex":122,"id":"exchange-052"},{"speaker":"おくの委員","kind":"質問・要望","question":"先ほど申しましたように、私がとった簡単なアンケートでは、特別養護老人ホームや公園、認可保育園などの要望が非常に強かったのですけれども、内部の検討においてはこういう事項も検討対象として挙がっているのでしょうか。最後にお伺いいたします。","respondent":"柏原企画調整課長","answer":"先ほどのご質問にもかかわる部分ですけれども、さまざまな行政ニーズ、我々もやらなくてはいけない行政の事業があります。そういった中で、施設のありようについては、いろいろな意見があるですので、さまざまな種類の活用といいますか、多方面から検討するというものです。","voiceIndex":124,"id":"exchange-053"},{"speaker":"横山委員","kind":"提案","question":"私からは、１６７ページ、シティプロモーション推進経費について、１９１ページ、品川文化プログラム推進事業助成についてと、１９９ページ、シティドレッシング、しながわ文化プログラム等についてお伺いいたします。区民の方々にとって、身近で気軽に多種多様な文化に触れることができる環境づくりこそが今求められていると考えますが、簡単に区のご見解をお聞かせください。","respondent":"立川文化観光課長","answer":"品川区では、平成２２年に品川区文化芸術・スポーツ振興ビジョンというものを作成いたしました。そこでは、「文化芸術・スポーツでつながり輝き続けるしながわを目指す」ということが、まず第１に掲げているところです。","voiceIndex":127,"id":"exchange-054"},{"speaker":"横山委員","kind":"提案","question":"私は、佐世保映像社の志岐誠さんから、渋谷ＴＡＮＰＥＮ映画祭ＣＬＩＭＡＸａｔ佐世保についてお話をお伺いしました。私は、山形市を視察し、映画祭やユネスコ創造都市加盟認定がされた経過などについてお話をお伺いしました。東京２０２０大会の開催を契機とした文化芸術イベントとしての映画祭を通じて、文化面での機運醸成を図るために、品川区での映画祭の開催をしてはいかがでしょうか。","respondent":"立川文化観光課長、辻オリンピック・パラリンピック準備課長、木村報道・プロモーション担当課長","answer":"それで、その次の段階としましては、区民芸術祭など、さまざまな文化イベントの取組みの中で、どういったことができるか。ですので、なかなかその中に区が入っていろいろなフィルムを撮ったりするというのは、現時点では少し困難かという気はしますが、建設から。動画、それから映画、そういうものによる訴求力というのですか、そういうものについては。","voiceIndex":129,"id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"区民芸術祭などで、いろいろな点をつなげていく。新しい風が吹き込むような取り組みを続けているようなのですけれども、品川区でも、区民の不幸せを減らして幸せを増やすために、新しい風を吹き込みながら、経済面、文化面、生活面のバランスのとれた発展を要望したいと思いますけれども、そこについて区の見解をお願いいたします。","respondent":"柏原企画調整課長","answer":"観光の面であったりシティプロモーションの面であったり、さまざまな観点がありますけれども、そういったところでのアプローチというのは都市に必要なものであると考えていますので、今後の捉え方というのは、関係している部署と十分連携しながら。","voiceIndex":133,"id":"exchange-056"},{"speaker":"横山委員","kind":"意見","question":"さまざまな部署も関係しているかと思いますし、オリンピック・パラリンピックに関しては、東京都との連携ですとか、そういったことも必要になってくるかと思いますので、将来的なことを考えて、ぜひ前向きに検討を進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問","question":"１６３ページ、企画調整費、長期基本計画策定経費からＳＤＧｓについて、２番目は、１７９ページと１８１ページの町会・自治会加入促進支援と運営事務サポート補助、時間があれば、１８７ページ、児童見守りシステム運営費でまもるっちのこと、そして、１８９ページ、旧品川警察署品川橋交通待機所取得、あと１９１ページのフィルムコミッション事業について伺います。","respondent":"柏原企画調整課長","answer":"日本経済新聞社の調査というところでございまして、品川区としても、その調査には回答しています。品川区としましては、１００点満点中で、評価いただいた点は６０.１２点でございまして、今ご紹介のありました全体の中では、４９位です。","voiceIndex":137,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"ただ、１つの共通の指標を持ってどういう取組みをしているのかというのは非常にわかりやすい。ちなみに、２３区では１０番目で、最下位は２２８位だった中野区なのですけれども、低いから一概に悪いとは言えません。１月に発表されました、東京都の目標に向かっていくアクションプランの中でも、ＳＤＧｓとのかかわりが示されたと思うのですけれども、その点について何か把握していれば教えてください。","respondent":"柏原企画調整課長","answer":"ただいま委員にご紹介いただきましたのは、東京都がこの１月に発表しております、「３つのシティ」の実現に向けた政策の強化ということで、実行プランという名前で発表されたものです。","voiceIndex":139,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０２０年に向けた実行プランの中でも、ＳＤＧｓの推進というのは、東京都の実行プランの推進と伴走して進めていくということが書いてあります。後で述べますけれど、民間のほうはかなり進んでいるというところもありますので、ここについてぜひ品川区としての宣言をしていただきたいと思うのですが、このあたりの考え方はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"委員からご紹介がありましたＳＤＧｓの考え方は、世界での共通言語との言葉をいただきましたけれども、品川区として今、検討に入っています長期基本計画は、区がどう行政を進めていくかという区の基本となる計画と捉えてあります。","voiceIndex":141,"id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜなら、やはり品川区はサンリオと一緒にやっているわけですから、何でこっちに声をかけてくれなかったのかというのが、少し残念でした。これも前に取り上げたのですが、もう何年も前からアブラヤシの保護の活動をやられていて、昨年、第１回目のＳＤＧｓ大賞、国から賞を贈られているのですけれども、今日、委員長の許可を得て、バッジを示させていただきたいと思います。そうしたら、どうすればいいか。","respondent":"伊崎地域活動課長","answer":"現時点では、書類作成ということでは、行政書士会が、やはりこの分野を得意としていらっしゃるのではないかと考えておりまして、そちらにご協力いただければと考えているところです。","voiceIndex":143,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問","question":"昨年の決算特別委員会でも申し上げたのですが、私も町会の一員として、マンションに対して町会加入のことで覚書というものを私なりにつくってみて、非常に難しかった記憶があります。そういったものの依頼というものを、果たしてお願いしてもいいものなのかどうか、そこについてのご見解をお伺いしたい。","respondent":"伊崎地域活動課長","answer":"行政書士会にお願いすることとなった際に、そういった書類の作成が、行政書士の業務の範囲を超えないものであり、お受けいただけるものということであれば、プレス発表に挙げております内容にかかわらず、広く町会・自治会の支援をしていただければと考えております。","voiceIndex":145,"id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"内々で聞いてみたら、行政書士会では喜んでお受けしますということでしたので、これはぜひそういったものも例示に挙げていただきたいと思います。では次に、まもるっちのことについて伺います。端的に伺います。時計をずっと見ながら歩くということは想定しにくいのですが、もし固定したままでも結構なのですが、時計の表示をぜひ復活させていただきたいと思うのですけれども、いかがでしょうか。","respondent":"菅生活安全担当課長","answer":"ただ、技術的な面や費用の面など、いろいろな課題がありますので、そういったことを考えながら、今後、教育委員会や通信事業者との協議の場で検討材料の一つとして取り上げたいと考えております。","voiceIndex":147,"id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ課長がいるうちにお願いしたいと思います。最後に、品川橋のところの品川警察署交通待機所の取得についてなのですが、文化観光課で計上されているのですが、ここについては、地域から防災目的で取得してほしいということを、ずっと何年も要望があったと思うのですけれども、ここについて、そういう声が届くのかどうか、最後ご答弁いただきたいと思います。","respondent":"立川文化観光課長","answer":"これは現在、東京都が所有しているものです。区で取得しまして、活用方法については、今後、地元の方々と相談し、検討していきたいと考えております。","voiceIndex":149,"id":"exchange-064"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私は、２０１ページの戸籍事務に関連して質問していきたいと思います。２回待つような感じになっているのですが、これはどういうあれで、ああいう仕組みが変わったのかどうなのかというのを教えていただきたいということが１つ。それをお願いします。","respondent":"提坂戸籍住民課長","answer":"１２月から、来年度からの証明窓口業務委託に先行いたしまして、フロアマネージャー業務というものを、先行して委託を開始しました。","voiceIndex":152,"id":"exchange-065"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それはどんどん進めていただきたいのですが、書くのはみんな普通に書くのです。そちらのほうが、よく説明で時間がかかっているというケースが非常に多いので、もうわかり切ったものに関しては、そういう窓口をどんどん設置していって、なおかつ発行するものに関しては、システムが変わればどんどん発行できるという仕組みをしっかりとつくっていただきたいのですけれども、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"ご本人が請求する場合というのは、年間に１回とか２回しか区役所に来ないので、なかなか書き方がわからないときも確かにありますので、その辺をうまく交通整理させていただいて、なるべく待たせないことができないか、検討してまいりたいと考えております。","voiceIndex":154,"id":"exchange-066"},{"speaker":"いながわ委員","kind":"質問","question":"前回の決算特別委員会においても、公明党の新妻委員が、「お悔やみワンストップサービス」という発言をされて、いろいろご答弁をされていると思うのですが、実際、ワンストップサービスについて、現状どういう状況になっているのか。もし前向きに検討されて、可能なのであれば、そうすればまさにワンストップサービスが実現すると思うのですが、いかがお考えでしょうか。","respondent":"提坂戸籍住民課長","answer":"それで、さまざまなワンストップサービスを行うというのは理想ではありますけれども、なるべくお客様に申請書を何回も書かせないようにするとか、ほかの窓口に案内したり、そういうことも今、検討してまいりたいと考えている段階なので、もう少々お待ちいただきたいと思います。","voiceIndex":156,"id":"exchange-067"},{"speaker":"いながわ委員","kind":"質問・要望","question":"時間があるので、１８７ページの自動録音機の無料貸与についてなのですが、これは６５歳以上とされておりますが、実際、今、現状はどういう状況になっているのか。要するに、貸与されている件数というのですか、世帯がどれぐらいあるかというのを教えていただきたいと思います。今までも補正で何回も増額しているわけでありますが、これは目指すところはどこなのか、お願いします。","respondent":"菅生活安全担当課長","answer":"これは平成３０年度の実績ですが、現在、補正予算を含めまして１,０００台を購入しておりまして、本年１月末現在におきまして１１２台残っている状況です。今後も来年度、１,５００台導入しまして、できる限り６５歳以上の世帯に配布を進めてまいりたいと考えております。","voiceIndex":160,"id":"exchange-068"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区内の６５歳以上は、８万人ぐらいいらっしゃるということなので、全ての方にそれを配布するというのは、なかなか難しい部分でもありますし、例えば子どもと同居されている方のところは除くとか、さまざまいろいろやり方があろうかと思いますので、計画的にしっかりと進めていただきたいと思います。これはたしかアナログには対応しないという話もありましたけれど、その辺はいかがですか。","respondent":"菅生活安全担当課長","answer":"アナログというよりも、いわゆる黒電話と言われるものには、設置はできません。","voiceIndex":162,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"旧大崎図書館ですが、現地での存続を求め活動してきた大崎図書館ユーザーの会の皆さんが、１月に、旧図書館の活用については解体ありきではなく、利用者、地域住民の声を聞いて、地域の方の要望している活用へ方針を変更してほしいという旨の要望書を提出いたしました。そちらの要望に対する区の考えについて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"基本的には、そういったところで予算の執行というところを目指していますので、基本的には、これまで区が考えていたとおり解体をして、次の用途というところで進めていくです。","voiceIndex":165,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"もともと補助２９号線推進のために、移転自体、必要がない図書館を、区がみずから動かす暴挙で許せません。もともとここは、地元名士で地主の方が大崎に図書館をということで、図書館用地として区に譲ったものでしたが、今回、それ以外の用途に使おうとしているわけで、それは問題ではないのか、伺いたいと思います。土地を譲った方の親族等に了承を得ているのかも伺います。","respondent":"柏原企画調整課長","answer":"前の土地の所有者等とのやりとりというのは、直接的なところではやったというところはございません。","voiceIndex":167,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"その方も、こんなことになるということは本当に、亡くなった松原さんも怒るのではないかということも言っていました。不誠実だと思います。伺いますけれども、区は何平米を幾らで買ったのか伺いたいと思います。当時の松原邸の庭石なども活用した日本庭園が整備されていますけれども、この日本庭園というのは貴重で価値があるものだと考えますけれども、区はこの庭園を残す考えがあるのかないのか、伺います。","respondent":"立木経理課長","answer":"金額は、いろいろありますので、この場では控えさせていただきたいと思います。庭園ですけれども、そのまま引き継ぎまして、灯籠等を置かれているということで、そのまま大崎図書館に引き継がれていると認識しております。","voiceIndex":169,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"幾らかというのは、いろいろあるので控えたいというのは、よくわからなかったのですけれども、なぜ幾らかというのを言えないのか。それと、この庭園を残す考えがあるのかということを聞いたので、もう一度伺います。","respondent":"立木経理課長","answer":"灯籠、それから庭園の一部、それから樹木等に関しては、移植できるものに関しては移植等を検討しています。先ほど少しお話がありました用地の部分ですが、今後、東京都からも用地活用の面でお話がある中で、今の段階で金額をこの場でお答えするのは控えさせていただきたいです。","voiceIndex":171,"id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"何か非常に不透明な部分が多いと思います。特に利用者の多い図書館でしたので、当事者、利用者の方々、地域の方々の声をよく聞いて活用を考えていっていただきたいと思います。これでは、現場労働者や業界団体が求める、上がっている労務単価と実際に職人等が受け取る賃金との乖離が全く埋まらないのではないかと思いますけれども、いかがでしょうか。","respondent":"立木経理課長","answer":"工事契約もしくはその他の委託契約等も含めまして、区がお願いしております契約に関しましては、当然のことながら、国の関係法令等を遵守していただくことが前提となっておりまして、それがきちんと守られていると認識しております。","voiceIndex":173,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"賃金を把握するというところに踏み出したことは、それはずっと求めてまいりましたから、評価します。最低賃金の２倍から３倍の賃金を労働者本人に保証するものになっています。伺いますけれども、公契約条例の検討に当たっては、労働報酬下限額を入れたものにすべきだと思いますけれども、いかがでしょうか。","respondent":"立木経理課長","answer":"契約先の雇用主と労働者との賃金の部分に関しまして、改めてそこで制限をかけるということは、契約元からしますと干渉になってしまうというところでは、公正な契約を執行していただくという中で、実態を把握するというところから。","voiceIndex":175,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"そこだけにとどまっていては、公契約条例を定める意味があるのかと、私は言いたいと思います。最低賃金は今、東京で時給で９８５円ですけれども、一方で、先ほど紹介したように、世田谷区の労働報酬下限額は、普通作業員で２倍以上になっている。この最低賃金をただ守ればいいということにとどまったら、そういったことが実現できるのでしょうか。伺いたいと思います。","respondent":"立木経理課長","answer":"そうした中で、きちんと各事業者で対応していただいているというところで考えておりますので、改めまして今回の要望も含めて、今のところ、最低賃金を新たに品川区として設定するということは考えてございません。は賃金の実態調査をするということになっております。","voiceIndex":177,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、要綱を制定して、まず現場が実際に幾らもらっているのかというのを把握する。それを踏まえて４月から要綱実施ですよね。生活も大変だという叫びが届いているわけではないですか。今のような形で「思う」ということで済まされるのですか。二重の設定をすることになるなどといいますけれども、ではほかの自治体は何でこういう労働報酬下限額というものを定めているのでしょうか。","respondent":"立木経理課長","answer":"そういったこともございまして、今まで実態調査等を行っていなかった中では、今度、４月から適用いたします要綱で、賃金の状況が把握できることと考えております。そうした中で今後、検討していきたいと考えております。","voiceIndex":179,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"本会議等でも、条例制定には、経営者、労働者、それぞれの意見や、学識経験者等の助言など、さまざまな角度からの検討が必要という認識も示されましたので、そうした方々をメンバーに入れた検討会を立ち上げて、しっかり検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"町会なども少し絡むかもしれませんが、よろしくお願いします。これは、設置拡大と効果の検証ということで出ているのですけれども、改めてこの目的を教えてください。これは長期的に絶対必要な分ですから、経費がかかるのはもちろん構わないのですが、職員の意識などは、１年間ぐらい経て、どの程度、その辺について成果が出ているか。その２点について教えていただきたいと思います。","respondent":"木村報道・プロモーション担当課長、齋藤会計管理者","answer":"デジタルサイネージの設置の目的です。こちらに関しましては、区政、それからイベント、地域の情報を幅広く、区の施設に来られた方にお知らせするというところが、まず１つ。それから、先ほどのコミュニティＦＭみたいなもの。一定程度時間をいただきますけれども、こういった説明責任という部分も含めて習熟させていただければ、新しい行財政のシステムとして運用できるものと考えております。","voiceIndex":183,"id":"exchange-079"},{"speaker":"鈴木（真）委員","kind":"確認","question":"第二庁舎２階と広報広聴課の前にあるのはわかるのですけれど、偶然聞いたのですけれど、第三庁舎の８階にもあると聞いて、私もこの前、見に行きました。実は私も、第三庁舎８階は行ったことがなかった。人から聞いて見に行った状況です。その辺を確認させてください。ここまで課を入れると、今年、平成３０年度決算は、部内の流用というのはできなくなったのかと思ったのですけれども、それはどうでしょうか。","respondent":"中元広報広聴課長、木村報道・プロモーション担当課長、品川財政課長","answer":"区民相談室に置いてあるデジタルサイネージシステムについてお答えします。あちらに関しましては、情報推進課と、それから私ども広報広聴課に、２台、検証機、テスト機というのですか。ですので、同じ目の中で違う部があれば、部間の流用は、同目の中で流用ができるという考え方です。","voiceIndex":186,"id":"exchange-080"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"見ていただくためということですので、そのままやっていただきたい。さっき第三と言いましたが、第二庁舎の８階でした。先日、ある会合で、幼稚園のお母さんの方から、子どもたちが東京２０２０大会に参画できないのかというようなニュアンスの質問がありました。この前、１つ、例えば文化プログラムという話題も出ている中で、何かそういうところに入れないのか、その辺を教えていただけますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ぜひお子さんが参加するようなものをしながわ文化プログラムに申請していただければ、私どもとしても広がりが出てきますので、とてもうれしいところです。","voiceIndex":190,"id":"exchange-081"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"確かに暑い中というのもあるのですけれど、多分、室内でやるものだと、エスコートキッズに参加できる人数にどうしても限りがでる中で、広く、いろいろな方が何か接触できるような機会をつくっていただきたいと思います。本当に、区立だけではなくて私立幼稚園とか私立保育園も何か絡めることができれば、その辺もぜひつなぎをつくっていただきたいと思いますが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"学校連携観戦プログラムのときのお話にもつながるのですが、お子さん同士で差が出るようなことがないように、いろいろな施策を進めていきたいと思っています。","voiceIndex":192,"id":"exchange-082"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１８５ページ、地域住民と外国人との交流促進。それから１８７ページ、児童見守りシステム運営費について、１６９ページのしながわＷｉ－Ｆｉスポット事業についてお伺いしたいと思います。","respondent":"遠藤協働・国際担当課長","answer":"当然、そのほかに、外国から観光などの目的でいらっしゃる方も多いと思いますけれども、特段、今のところは、例えばこちらの多言語化とか、そのような形で対応できて、特段、問題が出るような話は、特にこちらには届いていない状況です。","voiceIndex":195,"id":"exchange-083"},{"speaker":"塚本委員","kind":"質問","question":"そんな中で、こういった宿泊所と地域との連携や協働といったことが、１つ、肝としてうまく相互理解などというところに、いい関係をつくっていくというところに、１つの解決策というか、視点があるのではないかと思うのですけれども、そういったところについてご見解を伺えればと思います。","respondent":"遠藤協働・国際担当課長","answer":"簡易宿泊所など、そういうところでの地域とのつながりですけれども、例えば東海道の地域でありますと、既にそのような活動をやっていると聞いておりますので、その辺をほかに広げるような形で注視して、こちらで支援が必要であればさせていただきたいと考えております。","voiceIndex":197,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問・要望","question":"このまもるっち３についてなのですけれども、これまでも幾つか確認されてきているかと思いますが、経費というのは大分、今までのものと比べると、運営費も、通常の通信費なども含めて軽減されるというところがあるということですが、まず基本の機能、それから有料のオプションということで機能があるかと思うのですけれども、これがどういったものかを簡単にご説明いただきたいと思います。","respondent":"菅生活安全担当課長","answer":"その他、重さとか、そういったものにつきましては、大きな変更はないのですけれども、ただ、まもるっちのストラップが簡単に外れて誤報件数が増えているという状況がございましたので、引っ張るときの負荷を、従来よりも大幅に負荷をかけて。","voiceIndex":199,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"基本機能では、例えば電話ができるとかメールができるというように何ができるかということです。有料オプションで使うことができる機能が、あると思うのです。それは、どういうものかお聞きしたいと思っています。","respondent":"菅生活安全担当課長","answer":"有料オプションとしては、事前にあらかじめ登録された連絡先と通話やメールができるような構造になっております。","voiceIndex":201,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。例えば体制が少し足らなくなるだとか、システムを改修しなければいけないだとか、そのようなことがもしあるのであればお知らせいただきたいと思います。","respondent":"菅生活安全担当課長","answer":"それに伴いまして、まもるっちセンターの通話に関する通信料といったものがかなり必要だということもありますし、また、まもるっちセンターも現在、１０名のオペレーターで対応しておりますけれども、対応件数がまた増えるということになりますと。","voiceIndex":203,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"次なのですけれども、１６９ページのしながわＷｉ－Ｆｉスポット事業ということで、今年度、また幾つか拡大していただくということで、「図書館、保健センター等」と予算書には出ております。これまでの実績というか、今、どれぐらいの区有施設で展開されているのかと、今後の見通しとして区有施設にどんなスケジュール感で設置されていくのかを、まずお伺いいたします。","respondent":"山本情報推進課長","answer":"ＳＨＩＮＡＧＡＷＡ Ｆｒｅｅ Ｗｉ－Ｆｉのお尋ねです。これまでの実績というところでは、平成２７年度に開始してございまして、区有施設、公園、それから駅周辺で整備を進めてあります。現在、合計で４５カ所で整備を終えているところです。","voiceIndex":205,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"これはやはり、以前も同じ質問をさせていただいたのですけれども、なかなかつながりにくいという声もよく伺います。大井町駅周辺でありますとか、Ｗｉ－Ｆｉの電波としてはＳＨＩＮＡＧＡＷＡ Ｆｒｅｅ Ｗｉ－Ｆｉにつながっているのですけれども、実際に画面が固まるというか、動かないという。それと改善ということについての考え方を伺いたいと思います。","respondent":"山本情報推進課長","answer":"これは周囲の環境に依存するところが多いので、なかなか根本的な解決策というのは難しいところではあるのですけれども、今、検討しているところでは、２.４ギガヘルツ帯の電波を流すのをやめて、５ギガヘルツ帯だけにするか等、今、検討を進めているところです。","voiceIndex":207,"id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ、より低ストレスなＷｉ－Ｆｉ環境の構築にご尽力いただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-090"},{"speaker":"高橋（し）委員","kind":"提案","question":"１６９ページ、総務管理費の業務自動化（ＲＰＡ）導入経費について、それからこれは１７２ページになるのでしょうか、人事管理費で、区職員についてのお話です。先にＲＰＡのほうなのですが、以前、平成３０年の第１回定例会本会議でこの導入を提案し、区長の答弁もいただき、今回、このように実証実験という形で導入したということで、大変期待しております。そこまでお願いします。","respondent":"山本情報推進課長、黒田人事課長","answer":"それから対象業務の選定なのですけれども、まだ今現在は決まってございませんで、来年度に入りまして、全庁的な説明会を実施しまして、その後、個別のヒアリング等を行って、適正業務を４つ選ぶ予定です。区での人材派遣の活用の考え方ですが、基本的に委託との違いは、指揮命令が必要な職については人材派遣として人員を入れておりまして、まず人事課で契約しているような。","voiceIndex":211,"id":"exchange-091"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ平成３２年、そして早期の本格導入に向けて、スピーディー、そして適切に、今年度は事業を進めていっていただきたいと思います。人数が１３０人ということで、たくさんの方がお仕事をされていると。そして、そのルールに基づいて、区は過半数の労働者の意思をどのような方法で聴取し、そしてそのときの事業所単位というのは、どのような考え方でやられているのでしょうか。","respondent":"黒田人事課長","answer":"対応といたしましては、平成３０年１月に、私から職員労働組合に提案いたしまして、２月に意見をいただいたです。","voiceIndex":214,"id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"質問","question":"区と話し合いをしていただいたということなのですが、今、職員労働組合の話が出てきましたが、職場代表としてお話を伺った、そこで交渉したということですが、先ほどの厚生労働省の派遣法の改正のときに、対象事業所単位ごとの労働組合の構成員が過半数であるということが必要なのですが、職員労働組合は過半数なのでしょうか。","respondent":"黒田人事課長","answer":"職員の誰が組合員であるかということは人事課として確認はしてございませんが、相当数の組合員がいるとは認識してございまして、労働者派遣法での事業所の単位の考え方としまして、経営の単位として人事、経理、指導監督、働き方など、ある程度は独立しているという意味では。","voiceIndex":216,"id":"exchange-093"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは東京都のある局ですけれども、そういう形をやっているところがあるのですが、そういうものに照らし合わせて、このような仕組み、ほかの区などの関係も含めて、適切に行われているのでしょうか。これは、きちんとやって、派遣の方にお仕事をしていただきたいという意味でお尋ねしているのですが、いかがでしょうか。","respondent":"黒田人事課長","answer":"他の状況について詳細にはつかんでございませんが、例えば事務につきましては、各区職員労働組合の上部団体がありまして、そこと統一交渉を行っているということもありますので、そういった意味では、そういった団体とこういったことについて協議を行うというところについて。","voiceIndex":218,"id":"exchange-094"},{"speaker":"本多委員","kind":"質問","question":"１７１ページの新年賀詞交歓会について、それと職員給与費全般について質問します。最初に新年賀詞交歓会なのですけれども、直近で結構なのですが、案内を出す人数、参加者、それと平成３１年度の案内を出す人数、その辺を教えてください。","respondent":"米田総務課長、品川財政課長","answer":"ですので、平成３１年度は未定ですけれども、平成３０年度につきましては、１,９２４名の方に招待状をお出しいたしまして、実際に出席されたのは８８７名、出席率４６.１％ということになってあります。職員の関係の賃金などといった場合の費用等ですが、現状のところ、管理職が今、地域で会合等に行ったときに有料等である場合については、適宜、管理職が自身で出しているという状況です。","voiceIndex":222,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問・要望","question":"人事のほうはもう結構です。濃淡があまりにもあると感想を持ちましたので、聞かせていただきました。これでその質問は終わります。きゅりあんの新年賀詞交歓会のほうを聞いていくのですけれども、利用者の満足度などをどういうふうに捉えているのかと思います。それで、誇りを持って進めていただきたいと思うのですが、ただ、その辺の利用者の満足度など、どのような感じなのか教えていただきたいと思います。","respondent":"米田総務課長","answer":"それで、いかに限られた時間、スペースの中でご満足いただけるかというような中では、受付や会場内での円滑な移動、それから終了したときの退室等につきまして、なるべくご不便をおかけしないようなスムーズな移動。","voiceIndex":225,"id":"exchange-096"},{"speaker":"本多委員","kind":"質問","question":"参加者も増えていると思うのですが、もう本当に場所が狭い。以前は廊下を使ったりしていましたが、消防法の関係でだめですということなのですけれども、消防法については、避難通路の確保とか、そういうものは理解できるのですが、今のキャパシティーに対する、その参加人数では、そちらのほうが消防法の収容人員からみて大丈夫なのですかと、そんな感想を持つのですが、大丈夫なのでしょうか。","respondent":"米田総務課長","answer":"確かに会場としては、人数的には狭くなっておりますので、その辺のところ、区有施設の中で、あの広さ以上の会場を有するところは今のところございませんので、なかなか２会場以上に分けてというような形も、一堂に会しているところではいろいろ支障もあると思いますので。","voiceIndex":227,"id":"exchange-097"},{"speaker":"本多委員","kind":"意見","question":"快適な環境で、場所の選定については、ほかがないのか、面積的に聞こうかと思ったら、７階のイベントホールより広い施設がない。スクエア荏原もそうですよね。品川区の魅力を見せていくというのはいいと思うので、今すぐどうのこうのは無理かもしれませんが、こういう視点についてはいかがでしょう。","respondent":"米田総務課長","answer":"ご指摘いただいたところ、確かにアクセスの部分もありますけれども、一定のフラットな広さの中で、さらに活用できる会場等がもしあれば、お考えの、お話のありましたようなことも検討の余地があるかと思いますので、この辺のところは、新たにできる施設の中で。","voiceIndex":229,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"最後にしますが、新しい視点で場所を変えたりすることも必要かと思いますし、また、現状使っているきゅりあん７階のイベントホールを大改修してもいいのだと思います。品川区のホームページ、きゅりあんのホームページを見ますと、７階のイベントホールは７階の面積の３分の１ぐらいなのです。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１９３ページの文化センター運営費、そして１６５ページの広報広聴費について伺いたいと思います。冬は寒くて大変だったということで、何とかならないかということでご要望を伺っているのですけれども、この点については何とかならないでしょうかという質問です。よろしくお願いします。","respondent":"立川文化観光課長","answer":"荏原文化センターについてのご質問です。改修後、まだきれいになっていないところがあるという点、また、講習室について温度調整ができていないです。この辺につきましては、現場の状況を把握いたしまして、改善できるところは改善したいと考えているところです。","voiceIndex":233,"id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一つ一つの個別空調になっていないので、なかなかそういう細かい調節ができないということを言われていたのですけれど、そういうことも可能となるよう今後、検討していただくということでいいのでしょうか。","respondent":"立川文化観光課長","answer":"温度調整につきましては、なかなか施設全体で統一的な温度にするというのが難しい部分もありますので、こちら、施設整備の所管とも協議いたしまして、改善できるところは改善していきたいと考えているところです。","voiceIndex":235,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、区民に大きな影響を及ぼす計画について、説明会を開いて意見を聞いて、区民の意見を反映した計画にしていただきたいということで、そのためにも説明会を開いていただきたいということで求めてきました。これまでパブリックコメントを行う中で、区民全体を対象にした説明会をしたことがあるか、伺いたいと思います。あるのであれば、どの計画で説明会を行ったのかも伺います。","respondent":"中元広報広聴課長","answer":"パブリックコメントの実施状況についてのお尋ねですが、平成２９年度につきましては、パブリックコメントの案件が全体で８件ということで、今までで一番多かったのではないかと考えています。","voiceIndex":237,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民全体を対象にした説明会を、パブリックコメントをするに当たりやったことがあるかともお聞きしましたので、あるのか、ないのか。あればどの計画だったのかということをお聞きしましたのでお願いします。","respondent":"中元広報広聴課長","answer":"ただ、それぞれの所管におきまして、必要に応じて行われている説明会もあると存じておりますので、計画策定以外のもので、私のほうに情報が入っておりませんが、そういうものがあるのではないかと考えているところです。","voiceIndex":239,"id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その時間に来られない方、その場所にいらっしゃれない方がありますので、公平性の観点から、あらゆる区民の方々の参加する機会をむしろ妨げかねない」という答弁を、おととしの決算特別委員会のときに言われて、この答弁で今も変わらないのかということを去年の予算特別委員会で私が伺ったときに、そういうことであれば。","respondent":"中元広報広聴課長","answer":"要綱上もできるという規定にはなってあります。必要に応じて、必要であれば、それは各所管課の判断等で行うことはできます。説明会の開催実績といたしまして、品川区の学事制度審議会の検討に当たりましては説明会が行われている実績がございました。","voiceIndex":241,"id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民の意見を聞く場、また区民に対してさまざまな計画をきちんと深く理解してもらうというところからも、説明会は大事な場であると私は思っているのですけれども、それについての考え方、説明会についての区の考え方を改めて伺います。","respondent":"中元広報広聴課長","answer":"やるべきではないということで考えていることではございませんが、ただ実際に計画をきちんと、ホームページ上やカウンターなどで、お示しして見ていただいて、それに対してその場でご意見をいただいてもよろしいですし、やはり説明会をいつどの時間帯でやるかというのは。","voiceIndex":243,"id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このときは、「公平性の観点から、説明会はむしろ区民の参加の機会を妨げかねない」と言われたのです。これは、そうではないということでいいでしょうか。","respondent":"中元広報広聴課長","answer":"やはり特定の時間と場所を限ってしまうと、確かにそこに来られない方にとっては公平とは考えていただけないかというところは、変わってございません。","voiceIndex":245,"id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、説明会をやるということが、公平性の観点からむしろ好ましくないと考えているということなのかということなのです。説明会に対してどう考えているかということを伺いたいのです。というのは、私はもう、そういうふうに１つの場所で来られない人がいるというのであれば、さまざまな機会をもっとたくさんつくる。それから曜日や何かもさまざま変える。その点をお答えいただきたいと思います。","respondent":"中元広報広聴課長","answer":"それよりは、今、区民の皆様、いろいろな世代の方がいて、ライフスタイルも非常に多様化しています。やはりインターネット等を利用して意見をお寄せいただくということが今後の流れに沿うのかと考えているところです。","voiceIndex":247,"id":"exchange-107"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中でも、ほかの区は区民に対してやっているのです。区の計画をしっかりと区民に理解してもらいたい。それから、区民からの意見をその場で直接聞きたいという姿勢があるかどうかだと思うのです。この点についてはいかがでしょうか。","respondent":"中元広報広聴課長","answer":"それは、どこの職場におきましても同じような形で、職員は区民の皆様の声を丁寧にお聞きし、ご意見を伺い、できるところはできますし、やはり反映できないところはできないとご説明も申し上げて、コミュニケーションをとっているところです。","voiceIndex":249,"id":"exchange-108"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも６５件の意見が出されています。こういうのを、もっと説明会を開いて、やはり地域をどうつくっていくかということですから、そこのところをしっかりと区民にも理解してもらい、そこから意見を聞くということになれば、もっと計画を充実させることができると思うのです。区民に対しての説明責任を果たすのだという姿勢を持っていただきたいと思いますが、最後にお聞かせください。","respondent":"中元広報広聴課長","answer":"ですので、今後につきましても、現状、一定程度の期間の間に意見をまとめるというところで考えております。","voiceIndex":251,"id":"exchange-109"},{"speaker":"大倉委員","kind":"質問・要望","question":"１９３件で５６件増えているというところで、金額はどのような推移をされているのか教えていただきたいのと、先ほどもありましたが、都の補助金が２分の１、１台４,０００円以下というようなことだと思うのですが、都補助金について予算の制限というのは、例えば全体で幾らを超えてはいけないなどというのがあるのか教えていただきたいのと、今まで、４００台、５００台、１,０００台。","respondent":"木村報道・プロモーション担当課長、立木経理課長、菅生活安全担当課長","answer":"そのほか、関係団体では観光協会、それから文化振興事業団、商店街連合会、しながわ水族館と、委員よりご案内がありましたが。そのほかに、破損した庁有車の修理費等で、主なものになりますが、平成２９年度は１１３万円ほど、平成３０年度、今年度は３８２万円ほどかかってあります。これは、来年度、東京都の自動通話録音機の助成制度が拡大ということで、従来、平成３０年度は２万台の助成対象としていたのですが、今回。","voiceIndex":254,"id":"exchange-110"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺で、いろいろな方にさらに情報を発信していくということで、例えばシナモロールの情報発信をしているところに、例えば今回、戸籍住民課のシナモロールがメインになった出生届がつくられましたが、そういうのも例えばシナモロールのほうでやってみるとか、連携をうまく各課でとっていくと、またその各課ごとのフォロワーに違う情報が届いていくのかと思っているのですが。","respondent":"木村報道・プロモーション担当課長、立木経理課長、菅生活安全担当課長","answer":"一例といたしまして、例えば情報を掲載する際に、ハッシュタグを、先ほど言いましたシナモロールであるとか出生届とか、そういう形でつけて上げするとか。車の装備に関しましては、今後、車両入れかえに関しては、価格との兼ね合いもありますけれども、可能な限り。電話の買いかえということになるかと思いますが、これにつきましては、従来どおり、設置する側の負担ということでお願いしたいと考えております。","voiceIndex":258,"id":"exchange-111"},{"speaker":"大倉委員","kind":"質問・要望","question":"関連して、シティプロモーションで、魅力発信ワークショップがこの間、行われておりまして、いろいろな方々に発表をしていただいて、その中で、また品川海苔を復活させる取り組みが最優秀賞に選ばれたというところで、こうした人々が品川区に対してさまざまな意見を言っていただいたというところと、これがこれから進んでいくというところなのですが、参加していただいた方たちを。","respondent":"木村報道・プロモーション担当課長、菅生活安全担当課長","answer":"魅力発信ワークショップに参加いただいた方には、これからもお声を聞いたり協力を求めたりしていきたいと考えています。各警察署としっかり連携しながら、協力しながら、設置促進を果たしていきたいと考えております。","voiceIndex":262,"id":"exchange-112"},{"speaker":"大沢委員","kind":"質問・要望","question":"先方のあることですから、こちらでこういう話をするのも甚だ失礼なことかとは思うのですけれども、将来的にどうあるべきかということの観点からお伺いしたいと思うのですけれども、そういった場合、駅から間近にあるあそこの立地条件は、非常にほっておけないような立地条件だと思うのですけれども、そこの部分について、先方があることなので、どけとか、どかないとか。","respondent":"柏原企画調整課長","answer":"ただ、いろいろな要件も踏まえて、これから検討というところでありますので、そういったお話があったというのは、こちらでも考えさせていただければと思ってあります。","voiceIndex":267,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"この件については終わります。町会の運営も困難になってくると思うのですけれども、町会と高層ビルあるいは新しくできたビルの自治会、あるいは管理組合が関係を持つように、取り持つ事業というかアクションというのは、区のほうでやっていただけるのでしょうか。","respondent":"伊崎地域活動課長","answer":"そういった再開発のされている地区におきましては、再開発組合のほうに、区から町会加入のご理解をいただく、あるいは働きかけを行う、説明を行うということで、ご理解を得ながら町会への加入促進支援を行っていくというところで働きかけをしております。","voiceIndex":269,"id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"そこの折り合いがなかなかつかない部分があります。要は、こちらから、区が町会加入の条例等々の制定をしたのは存じておりますけれども、なかなかそこのところというのは、「お願いします」、「はい、そうですか」では済まないような案件だと思うのですけれども、そこのところはどのようにご認識されているでしょうか。","respondent":"伊崎地域活動課長","answer":"私が先ほど申し上げましたのは、再開発等で、主に住宅、住居が入る場合は、先ほど申し上げたような形でお願いするところですが、商店の方につきましては、管理組合を通してというよりも、やはり商店の関係の部署を通してのご説明。","voiceIndex":271,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問・要望","question":"それで、残りの２割が、どうしようかと、まだ宙ぶらりんな状態でありまして、足すと１０割になるわけでありますが、この６割のお店に関して、やはり商店街の入り口でありますから、やはり理解を持ちながら、既存の商店街あるいは商店との調和をとるべく、そのような動きをしてもらいたいのですけれども、そのあたりは、これは都市開発なのか、産業振興かわからないのですけれども、どういうふうに先方と。","respondent":"稲田都市開発課長","answer":"区といたしましても、そういうものにかかわりながら、武蔵小山の商業のさらなる発展を目指しながら、再開発との関係でやってきておりますので、今も建物は建ち上がっていまして、来年度、オープンを迎えるところですが。","voiceIndex":273,"id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"やっていただいている、取り扱っていただいているのはわかるのです。これは何日か前に私が質問させていただきました。ただ、何をどういうふうにされたいのか、どうしていただけるのかという部分を私は問うたのでありまして、やっていただいていることは十分にわかっております。その先、どのようにビジョンを描いていただいて、この問題を取り扱っていただくのかということをお伺いしたいのです。","respondent":"稲田都市開発課長","answer":"それに先立ちまして、区としましては、まちづくり再生方針というものをつくっていきたいと考えております。そういう中におきましても、商業との関係を強く連携してやっていきたいと考えていますので、今後もそういうもので引き続きやっていきますので、よろしくお願いいたします。","voiceIndex":275,"id":"exchange-117"},{"speaker":"大沢委員","kind":"意見","question":"引き続きお願いします。パルムも、今ではなく１００年先の武蔵小山ということを考えてビジョンも練っておりますので、いいまちづくりができるように、力強いプッシュ、支援をぜひともお願いしたいと思います。ただ、渋谷区や新宿区、私どもの地域、区よりも、より高い防犯性を要する地域ほうが防犯カメラが少なく、私ども品川区のほうが多いのは、どのように生活安全担当課長は考えていらっしゃいますか。","respondent":"菅生活安全担当課長","answer":"防犯カメラの関係です。品川区は、平成２９年末現在で８４３台、東京都の助成を活用しまして設置しておりまして、また平成３０年度中も１１５台を設置する予定となっております。これは、都内では本当にトップクラスの設置台数と考えております。","voiceIndex":277,"id":"exchange-118"},{"speaker":"大沢委員","kind":"質問","question":"今おっしゃった、３つの大きな盛り場の件については、防犯カメラは警視庁と直結されているということでよろしいですか。","respondent":"菅生活安全担当課長","answer":"これは警視庁にカメラセンターというのがございまして、そこがリアルタイムで、２４時間体制で監視していると聞いております。","voiceIndex":279,"id":"exchange-119"},{"speaker":"大沢委員","kind":"質問・要望","question":"時間がなくなってしまったのですけれども、何が言いたいかというと、公共の場にカメラがあるので、今、皆さんはこういう情報ツールが発達しているので、１億総何とかという言葉が昔ありましたけれども、みんな、１億総評論家的になってしまって、いつどのようなタイミングで、肖像権だ、プライバシーだと、また何か問題が起こりかねないので、そこのところもしっかりご意識しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"先に一言、監査措置報告について、一昨年の決算特別委員会で措置報告のホームページ上の掲載を求めたところ、その時点では、今後については監査委員協議会に諮るということで、あまり前向きに捉えていなかったのですけれども、４カ月後の１月末には、次の監査措置報告がホームページ上に出されました。幾つか質問いたします。それでも今回のような指摘があったことを、どのようにお考えになるのか伺います。","respondent":"立木経理課長","answer":"今後に関しましても、引き続き、これをチェックする立場、各係長とか課長への研修等もしっかりやっていきたいというところで考えているところです。","voiceIndex":285,"id":"exchange-121"},{"speaker":"吉田委員","kind":"確認","question":"ごめんなさい。高額のものについては、もちろん事務手続は主管課が行うのだけれども、最終的に経理課が確認しているということを伺ったのですけれど、それは少し違うのでしょうか。改めて確認させてください。それらの措置結果にも今回と同じようなことが書かれていたと記憶しております。それを前提とした場合、今回はどうやってきちんと徹底していくのか、もう一回、お答えを伺います。","respondent":"立木経理課長","answer":"そういった形になってあります。今回につきまして、今後、再発防止という点では、また人事課とも連携をとりまして、研修等といったものをしっかりとやっていくということで徹底させていきたいと考えております。","voiceIndex":287,"id":"exchange-122"},{"speaker":"吉田委員","kind":"質問・要望","question":"区全体として、公文書に対しての認識を確認して、こういう、初歩的でありながら、かつ重大なミスを防ぐため、根本的な改善が必要と考えますが、その点について見解を伺います。それから、これまで契約条項が記載されないまま交わされてしまった契約や、消せるボールペンで作成されてしまった公文書へのリカバリーというのでしょうか、そういう対応はどうなっているのでしょうか。確認させてください。","respondent":"米田総務課長、立木経理課長","answer":"今後、研修等も通じて、その辺のところを徹底し、二度と同じ指摘を受けることのないようにということで、もとあったものについては、きちんとリカバリーをしていきたいと考えています。こちらの契約約款に関しましては、済んでいるものに関しましては、きちんと履行の確認をした上で、あと先方の契約先とのお話し合いの中で、差しかえさせていただいているということで。","voiceIndex":289,"id":"exchange-123"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。過去に教育委員会に対する監査意見について取り上げたとき、他の委員から、「このような課題の発生時は成長していくための１つのチャンスとして捉えることができるのではないか。それで、時間がないのですが、先ほどの決算書のことで、つる委員からのご質問に対して、ご答弁が、これは場合によっては決算委員会のときに決算書等が出てこない可能性があるということでしょうか。","respondent":"品川財政課長","answer":"先ほどの答弁は、あくまで財務諸表のお話をしております。現在のところ、決算委員会には、成果報告書を出しておりますので、それが特に大きく変わるというものではございません。","voiceIndex":292,"id":"exchange-124"},{"speaker":"吉田委員","kind":"質問","question":"財務諸表です。だから、それが出てくるべきではないのですかということで……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-125"},{"speaker":"若林委員","kind":"質問","question":"１６３ページ、公有地活用等検討などについて伺いたいと思います。公有地のところ、活用検討ですが、まず区の基本的な考え方として、施設が配置される、それから用途を変える。要するに、土地を遊ばせないというように早期に活用して区民サービスに供していくという、速やかな対応という考え方でよろしいのか、お考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"今、委員ご指摘のとおりでございまして、そういう状況が出たときに、いろいろな検討をする中で、有効な活用というのが、建物も含めてやれるようにということで、全て検討してきたところです。","voiceIndex":296,"id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、旧第一日野小学校の跡地が２０２２年に定期借地権の契約が切れるというところで、具体的に年月が出ているわけですけれども、この２０２２年に向けて、今の区の考え方を照らし合わせると、今後のスケジュール等はどのように考えておられるか、お聞かせいただきたい。","respondent":"柏原企画調整課長","answer":"旧第一日野小学校の部分につきましては、今ご指摘があったように、契約の期間というのがありますので、その期間が満了するところを１つのラインと考えまして、その後の活用についてということで、さまざま行政の需要、それからいろいろなお声というのを考えながら。","voiceIndex":298,"id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"２０２２年、多少前後するかもしれません。それで視点を変えまして、旧第一日野小学校の跡地から少し離れまして、ＴＯＣの存在が今、品川区にとってどのようなものかというところの確認だけはさせていただきたいと思います。「五反田駅周辺にぎわいゾーンまちづくりビジョン」というのが、数年前ですか、地域の方々も含めて、結構な方が、結構な日数、年月をかけて、このビジョンをつくりました。","respondent":"稲田都市開発課長","answer":"この五反田のにぎわいのために、この３拠点を中心としながら、にぎわいづくりをやっていこうということで、ＴＯＣにつきましても、現在、建て替えの期限等も来ておりますけれども、そういう点も含めながら、にぎわいづくりとまちづくりをやっていこうと考えております。","voiceIndex":300,"id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"五反田、大崎は、桜の名所である。この地域には、五反田文化センターがあり、図書館機能があり、区民のいわゆる文化活動の１つの拠点であり、また、なかなか都内には珍しいというのでしょうか、プラネタリウムがあって、毎年、生涯学習も含めた区民の皆様のためのさまざまな企画がされていて、著名な方々もお越しいただいていると。それからもう一つだけ、１７７ページの非常用電源確保対策。","respondent":"柏原企画調整課長","answer":"非常用電源の平時等の活用です。こちらにつきましては、何かあったときに使うための電源等も含めて、常時使えるような形での体制をとっています。そういったところも含めて、いろいろな活用については、今後、あわせて検討していきたいと思っているところです。","voiceIndex":302,"id":"exchange-129"},{"speaker":"伊藤委員","kind":"確認","question":"先に情報化推進経費でありますけれども、庁内のネットワークや住民基本台帳等のシステムは確立したと考えているわけでありますけれども、同時に情報が集約されて、さらに３９万人の区民の方々のデータを所有しているわけでありますから、改めて、そのデータをウイルスやハッカー等外部からの日々巧妙化する不正侵入に対し、どうセキュリティーを確保していくかということの確認が１点と、それから昨今。","respondent":"山本情報推進課長","answer":"セキュリティーについてのお尋ねです。区としましては、区の保有する情報資産を守るために各種セキュリティー対策を実施しています。","voiceIndex":305,"id":"exchange-130"},{"speaker":"伊藤委員","kind":"確認","question":"だから、デジタルで対応するのはもちろん一緒なのだけれども、実際のデータを全く違う場所にアナログ的にといったらいいのか、保管しているのでしょうかということを確認したいのです。つまり、今、万全な対策をとっていることはわかるのだけれども、それでもなお対処できない事態が昔起こったわけだから、やはりそのことについては、もう一つ、前に進んだ答弁をお願いしたいのですが、いかがでしょうか。","respondent":"山本情報推進課長","answer":"今ご案内いただきましたバックアップの関係ですけれども、住民情報システムのデータに関しましては、委員ご案内のとおり、磁気テープでの保存に変わっておりまして、区役所庁舎外での保存というのを行ってあります。","voiceIndex":307,"id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"私の聞き方が悪かったですけれど、要は別の場所でしっかり保管されているのでしょうか。そのことの関係をお願いします。","respondent":"山本情報推進課長","answer":"委員ご案内のとおり、そのような対応をとってあります。","voiceIndex":309,"id":"exchange-132"},{"speaker":"伊藤委員","kind":"確認","question":"わかりました。それから、仮定の話でありますけれども、バックアップの復元が必要となった場合には、どれぐらいの時間で、区役所のシステムを再開することができるのでしょうか。できるだけ短いほうがいいと思うのですけれども、確認のために答弁をください。お願いいたします。","respondent":"山本情報推進課長","answer":"バックアップ、復元というところですけれども、実際はシステムエンジニア等に委託して行うところになりますけれども、こちらの時間というところは、正確なところは出てこないのですけれども、早急に対応できるような体制は整えてあります。","voiceIndex":311,"id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問","question":"これも古くて新しい問題でありまして、新しい脅威が毎日毎日出てくるわけでありますから、十分な対処をお願いしておきます。そうすると、その情報を活用することで、いろいろな区民サービスが向上する可能性があるわけであります。だから、そういう形で、新たな観点で、住民基本台帳データを、使っていくことが必要だと思うのだけれども、いかがでしょうか。答弁をお願いいたします。","respondent":"山本情報推進課長","answer":"そういった意味で、虐待の芽をつむ、早期発見というところでは、活用の方法があるかと思います。は所管で実際にシステム構築等を行い、運用する形になるかと思いますけれども、その辺は連携して調整していきたいと考えています。","voiceIndex":313,"id":"exchange-134"},{"speaker":"伊藤委員","kind":"質問","question":"これはすごく新しい観点だと思うのです。だから、現下、虐待のことに関してだけ、こういう住民基本台帳の情報の活用というのは、すごく利便性・活用性があると思うので、改めてこれを進めていくなり検討していくなり、１つの方法とみなしていただけると思うのですが、いかがでしょうか。","respondent":"山本情報推進課長","answer":"データの活用というところでは、ほかの自治体でも一部始まっていますけれども、住民情報システムの情報を匿名化し、データ化して分析等々を行っているところです。そういった部分で可能性は大分あると思ってありますので、区としても考えていきたいと思ってあります。","voiceIndex":315,"id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問","question":"だから、セキュリティーの中で守られているということが大前提なのだけれども、せっかくのデータを、それぞれの各部署で有効に活用していく手段をつくっていくということも、これからの１つの方向性ではないかと思うので、企画部門でいいのか、答弁をお願いいたします。","respondent":"柏原企画調整課長","answer":"ただし、法制度上で、例えば個人情報というのは取り扱いが非常に限定されている部分があったりしますので、あと、おっしゃっていただいたセキュリティーや個人情報の関係は十分に注意しながら、さまざまな活用について。","voiceIndex":317,"id":"exchange-136"},{"speaker":"伊藤委員","kind":"質問","question":"シティドレッシングについては、簡単な質問ですけれど、プレス発表によれば、区内商店街の街路灯に東京２０２０大会の装飾を施すことで、オリンピックの演出とあるのですけれども、ドレッシングとは、着付け、服、装いを意味する。これももちろんいいのですけれども、もっと多面的な政策を展開すべきと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これから、もう１年前になりましたので、多面的ないろいろな手法をとって、気運醸成のための雰囲気づくりをどんどん進めていきたいと思っていますので、いろいろな形で進めていく予定です。","voiceIndex":319,"id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"戸籍及び住民基本台帳費に関連してでありますけれども、これはたしか午前中の質問で出ました。先ほど、午前中の質問でもありましたし、以前にほかの委員から質問がありましたけれども、これも１つの方法だと思うわけでありますので、改めてワンストップサービスについての品川区のお考えをお聞かせください。お願いいたします。","respondent":"提坂戸籍住民課長","answer":"戸籍住民課の窓口以外の窓口の事務についても、限られたスペースの中でどれだけできるかということを、ほかの課と連携しながら検討してまいりたいと考えています。","voiceIndex":321,"id":"exchange-138"},{"speaker":"伊藤委員","kind":"質問","question":"もちろん、すぐに実現できるとは私たちは思っていないのだけれども、加えてＩＣＴとかＩｏＴ技術を活用すれば、さらにこれが先に進むことが当然予想されるわけであって、今の現時点での課長の答弁は理解するのだけれども、新しい品川区の未来に向かって、１つの方向性を示していくべきと思うのですが、いかがでしょうか。答弁をお願いいたします。","respondent":"提坂戸籍住民課長","answer":"そういうものがどの程度活用できて、お客様の待ち時間を減らすことができるかということで検討してまいりたいと考えているところです。","voiceIndex":323,"id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１９７ページのスポーツ推進費から、品川区スポーツ推進計画策定について伺いたいと思います。このスポーツ推進計画は、区独自につくられるものなのでしょうか。それとも、オリンピック・パラリンピック等に向けて、国や都からの流れで２３区全体でつくろうとなっているものなのか、伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"スポーツ推進計画についてです。今回出していますスポーツ推進計画につきましては、品川区独自での策定ということで考えてあります。","voiceIndex":326,"id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"独自のものというところですけれども、なぜこれを策定しようというふうになったのか、経過を聞かせていただきたいのと、あと策定までのスケジュールです。策定委員会等々もつくられてやっていると思うのですけれども、何回ぐらい、どういったメンバーでなど、その辺がわかればお知らせください。","respondent":"池田スポーツ推進課長","answer":"日程についてですけれども、予定といたしましては、来年、平成３２年に長期基本計画ができますので、その長期基本計画策定以降に、同時にできるような形で、スポーツ推進計画が策定できればというようなことで考えているところです。","voiceIndex":328,"id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど課長もおっしゃられた、平成２２年に策定された、品川区文化芸術・スポーツ振興ビジョンですけれども、私はここに障害者の位置づけがないということが大問題だということで指摘しまして、障害者スポーツ振興計画の策定を求めてきましたけれども、今回の品川区スポーツ推進計画に障害者は位置づけるべきだと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"私どものスポーツの推進に当たりましては、私が常に言っていますように、いつでもどこでも誰でもということで、当然、障害をお持ちの方も、今回のスポーツ推進計画に重点的に入るような形で考えているところです。","voiceIndex":330,"id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、これはどのようにされるのかを伺いたいのと、そこにやはり障害者当事者、家族、団体にも、障害者に特化した調査をすべきかと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"推進計画の内容についてですけれども、章立てということを、今お話があったところですけれども、実際に推進計画の策定につきましては、策定委員会で、こういった形でつくるというふうに決めてまいりますので、今、ご要望のあったことについては。","voiceIndex":332,"id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、区が主体でつくっていただきたいと思うのです。しかし、平成７年ですので、もう２４年たっています。東京都でも、東京都障害者スポーツ振興計画が平成２４年に策定されています。今、スポーツ推進委員やスポーツ・レクリエーションの委員は、日々、スポーツ推進に向けて頑張っていただいていると思うのですけれども、障害者スポーツ指導員というのは、品川区にはどれぐらいいらっしゃるのでしょうか。","respondent":"池田スポーツ推進課長","answer":"障害者スポーツの部分につきまして、平成６年のプログラム策定ということで、私ども、確かに平成６年に、柳沢教授にご依頼いたしまして、スポーツプログラムを策定していただきまして、それ以降といいますか、昭和５６年の国際障害者年を契機に。","voiceIndex":334,"id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、やはり品川区でもどういった実態なのか、障害者に聞き取り、また障害者を支援する皆さんに聞き取って、障害者スポーツ計画を策定すべきではないかと思うのですけれども、いかがでしょうか。必要なことというのは出てくるかと思いましたので、やはりこうした障害者スポーツ計画を品川区として策定していく。そして、さらに障害者スポーツセンターをやはり建設していただきたいと。","respondent":"池田スポーツ推進課長","answer":"障害者スポーツセンターをですけれども、委員がお話しされたように、私どもとしては、東京都に城南地区に設置するようにということを、ずっと要望しています。今後も要望については変わらずやってまいります。","voiceIndex":336,"id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、東京都の障害者スポーツ振興計画、スポーツをする上で必要なことというので答えられている内容は、障害者スポーツセンターができれば結構解消される中身なのです。ですので、そうしたことを早く実現させていただきたいですし、品川区のスポーツ推進計画にしっかりと障害者を、みんなと一緒ではなくて位置づけるべきだと思います。強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":338,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"私は、総務全般で、職員定数の問題を伺います。そして、この定数内職員は正規職員といいますが、４月１日の、新年度の職員定数である定数内職員は２,４８９名とあります。ということは、実際、公表されている職員数は２,４８９名ですが、正規の休職者と正規派遣職員を足した人数の合計が、区で正規職員として登録している人数なのでしょうか。教えてください。そして、合計で何人になるのか教えてください。","respondent":"黒田人事課長","answer":"定数条例上の職員数ですが、これは課といった職場で仕事をする職員の数ということで、委員ご指摘のとおり、定数外の職員の数は除いているものですが、予算書では、１０月１日ですが、現員数ということで、いわゆる休んでいる職員も含めて人数としては計上していますので。","voiceIndex":340,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"その中で少しお聞きしたいのですが、休職中の正規職員の方が、戻れる状況になった場合ですが、これはもとの職場に戻れるのでしょうか。というのは、そこに休職者のかわりに代替の職員、正規職員の方が補充されていると思うのですが、その辺について少しお聞かせください。","respondent":"黒田人事課長","answer":"は休職者ですと、一番多いのが、いわゆる育児休業ですが、育児休業の職員につきましては、任期つきで育児休業代替という制度で職員を採用していますので、育児休業に入る期間から任用が始まりまして、基本的には年度末までの任期ということで運用していますので、翌年度。","voiceIndex":342,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"ということは、そういう代替職員の場合には、正規職員ではなくて、非正規職員、期限つきの職員を採用しているということですか。それから、もう一点は、派遣職員の方がいると思うのですが、この方たちも同様に、一時的に非正規雇用の非常勤の職員なのでしょうか。２点お聞かせください。","respondent":"黒田人事課長","answer":"それで、いわゆる人材派遣につきましては、人材派遣会社で雇用されていて、こちらで人材の派遣をお願いしているということでありますので、非常勤職員ということではなくて、これは民間企業の社員が。","voiceIndex":344,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、我々ではなかなかわかりにくい、民間ではわかりにくい中身なのですけれども、先ほど２,６１６名の方がいるというお話でしたが、だったら最初からそういうふうにしておけばいいのではないですか。これでは、職員定数をわざと、一生懸命やっている行財政改革ではないですけれども、定数を少なく見せているような感じもしますし、このような手法をなぜとらなければいけないのですか。","respondent":"黒田人事課長","answer":"例えば短時間で勤務していただく非常勤職員の方がいらっしゃる方が事業運営がうまくいくというところであれば、そういった、常時勤務を要しない職をつくりまして、各事業運営の中に非常勤職員を配置したり、人材派遣につきましては、職員でなくても、定型的な業務でありますとか。","voiceIndex":346,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"少し別の視点でお聞かせ願いたいと思います。このたび、わざわざ公益的法人等へ職員を派遣することができる団体が追加になっています。これも正規雇用ではなくて、これも非常勤とか臨時で雇っている職員なのですか。これの理由は何ですか。教えてください。別段、そんなに忙しい部署でもないのに、区から職員を、そこに派遣してやるという意味合いがわからないのですが、教えてください。","respondent":"黒田人事課長","answer":"この派遣条例に基づく派遣というのは、法人の職員としての身分もあわせて持つということになりますので、その法人の職務も本格的なことができるということで、区政にとって密接な団体でもありますので、そういった事業運営の中では、そういった派遣も必要であると判断しまして。","voiceIndex":348,"id":"exchange-151"},{"speaker":"須貝委員","kind":"意見","question":"今、研修というお話がありましたが、区の職員がそちらで研修するという、まずこれがおかしい。そこで人数が必要なら、そこで人を公募するのが筋です。これについて簡単に見解をお聞かせください。","respondent":"黒田人事課長","answer":"派遣法の目的としましては、地域における人材の有効活用を通じて、適切な公民連携によって諸政策を推進するというものです。","voiceIndex":350,"id":"exchange-152"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は１８９ページ、歴史館職員給与費、１９５ページ、資料整理・外部倉庫預入、リニューアル基本計画検討経費について伺います。これが中心的な仕事になってくるのか。リニューアルのことを考えれば、やはり資料整理がまず先にあるのだろうと考えていますので、この辺の学芸員の方々の中心的な仕事、どういう形で学芸員の方を活用していくのか。ここをまず初めにお伺いしたいと思います。","respondent":"黒田人事課長","answer":"学芸員の採用ですが、本年度、採用試験を行いまして、２名の学芸員を採用する予定です。配置先の予定といたしましては、歴史館と、教育委員会にあります文化財の担当へ１名ずつ配置したいと考えているものです。","voiceIndex":353,"id":"exchange-153"},{"speaker":"石田（秀）委員","kind":"質問","question":"大学生に聞いたら、そういうのは資料として、その学科にいる大学生は買わなくてはならないみたいなときもあったりして、そういうのを安く売ってくれるのなら、幾らでも買う人はいるのではないですかなどと言われたけれど、いただいたものを行政側が売っていいのかというと、これは微妙なので、私はわからないけれども、そういうことを含めて、今このときにそれをやるべきだと考えていますけれども。","respondent":"立川文化観光課長","answer":"ただいま委員ご指摘のございました寄贈に関するルールの点です。こちらにつきましては、やはりご指摘も踏まえ、どういった決まりで寄贈を受けるかというのは具体的な検討を進めてまいりたいと考えているところです。","voiceIndex":355,"id":"exchange-154"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこの部分はぜひやっていただきたいのと、どうして学芸員の方かというと、お返しできるものや、ルールが変わるのなら処分をさせてくださいという確認も必要になってしまうではないですか。それを処分していいのかどうかということも含めて、確認作業もやっていただきたいと思いますので、そこはもう一遍、答弁をいただきたいと思います。これはしっかり残していくべきだろうと考えています。","respondent":"立川文化観光課長","answer":"集客施設につきましては、そのあり方について、こちらは特徴を出して集客ができるですので、立地柄、慎重な検討が必要かと考えておりますので、こちらもあわせて検討を進めていきたいと考えているところです。","voiceIndex":357,"id":"exchange-155"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お金がかかる話ですけれども、やはりそれは、その中で評価してくれる方が、変な話、お茶室を使うのだろうと考えていますし、先ほどのレストランの考え方も、例えば大井地区なり山王地区の女性の方々が来てくださる。それはどこまでやるかは別としても、そういうことをぜひやっていただきたいと思いますが、もう一度、その辺の考え方を、ぜひ教えていただきたい。","respondent":"立川文化観光課長","answer":"今後は外国人観光客を含め、多くの方に楽しんでいただけるスポットとして、いわゆる歴史館を新たにリニューアルしていきたいと考えております。","voiceIndex":359,"id":"exchange-156"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"さっき１つだけ話があったので、１９９ページだけど、パラリンピック啓発イベント。これが、間違っていたらごめんなさい。でも、パラアリーナを品川区に寄贈してもらってもいいじゃないですか。管理運営は品川区でやればいいじゃないですか。それは東京都でやってもらってもいいのですけれど、そういう動きをぜひかけていただきたいと思いますけれども、最後にそれだけお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"とてもすばらしい施設でして、ぜひとも何か継続する形はないかというのは、模索しながら、東京都や関係機関にも働きかけはしていきたいと考えています。","voiceIndex":361,"id":"exchange-157"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、１７５ページ、働き方改革推進に関連して、１８９ページ、しながわ発見出会い事業、ナイトライフ調査、マップ作成、２０７ページ、選挙費について、２０８ページ、統計調査費についてお伺いします。ナイトライフ調査、マップ作成ですが、ナイトメイヤーについて、その創設のお考えがあるのか教えてください。そこで、羽田新飛行ルートに関するアンケート調査についてお考えをお知らせください。","respondent":"黒田人事課長、伊崎地域活動課長、立川文化観光課長、秋山選挙管理委員会事務局長、鈴木都市計画課長","answer":"私から、職員の休暇制度についてお答えいたします。区では６年ほど前まで５年間、結婚サポート事業を実施しておりまして、当時はマッチングというものを中心にやっておりました。ナイトメイヤーにつきましては、東京で、いわゆる民間におきまして。実は平成１４年に電磁記録式投票法という法律が施行されまして、地方選挙においては、実はネット投票が既にできるようにはなってありますが。","voiceIndex":364,"id":"exchange-158"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"陰ながら応援します。これは要望で終わります。それはぜひ、さらに強く求めていただきたいと思います。国が一定の地域の理解を得て、この事業は行っていくという発言をされているのであれば、これは品川区が調査をかけるのか、国に対してしっかり調査をかけるように働きかけるのか、二通りあると思いますが、まずはこれは国策ですから、国にしっかり品川区民に対して調査をかけるよう求めるべきだと思います。","respondent":"黒田人事課長、鈴木都市計画課長","answer":"ただいま委員からご提案がありました不妊治療に係る休暇ですが、職員の休暇制度につきましては条例で規定がございまして、条例を改正するためには人事委員会の意見聴取を行い、公務員制度としての均衡を図るというところもありますので。しかしながら、やはり事業主体、これは国が進める事業ですから、その方法、確認については、国がしっかり検討して考えていくべきだですから、区としてもその方法について、国にはしっかり今後も申し入れをしていきたいです。","voiceIndex":370,"id":"exchange-159"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ調査の件は国にしっかり働きかけをしていただければと思います。不妊治療の休暇ですが、これは行政がやるから民間も大きく動き出すことができるのです。なので、これはぜひ、品川区としても、そういった休暇制度をとれるような制度設計を行っていただければと思います。要望で終わりますが、よろしくお願いいたします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":373,"id":"exchange-160"},{"speaker":"南委員","kind":"質問","question":"１７３ページの総合教育会議費について、そして２０３ページの住民基本台帳関係費について伺います。そして、実施してみて、区の評価、これからの課題は何だと思うか教えてください。この視点について、品川区の認識と、そして改めて伺いますけれども、こういった要請について品川区の対応は、具体的にはどういうふうにされているのか教えてください。","respondent":"米田総務課長、提坂戸籍住民課長","answer":"その中では、区長部局が実施している子ども・子育ての関係の施策について、関係課長等よりご紹介申し上げ、教育委員の方からご意見をいただいたり。自衛隊による住民基本台帳情報の請求についてですけれども、以前、陸上自衛隊の高等工科学校の生徒の募集に関しまして。","voiceIndex":375,"id":"exchange-161"},{"speaker":"南委員","kind":"質問・要望","question":"自衛隊の問題でありますけれども、品川区は提供はしていないということで受けとめていいのかと思ったのですけれど、そこの確認です。それで、そういうふうな要請をしてきたことについて、品川区としてはどういうふうに捉えているのか、改めて認識を伺いたいと思います。したがって、改めてこの問題についての認識、見解を伺いたいと思います。","respondent":"米田総務課長、大野計画担当課長、提坂戸籍住民課長","answer":"課題というのは、おそらく議題として供されるものだろうと想像いたしますけれども、この間については。今ちょうど、平成３２年度開始の長期基本計画を策定しておりますので、そういったところで、タイミングをあわせた策定といったところを、今。他の自治体におきましては、自衛隊の要請に沿った形で、住所、氏名、性別。","voiceIndex":378,"id":"exchange-162"},{"speaker":"南委員","kind":"質問・要望","question":"総合教育会議というか、教育大綱の新しい立ち上がりについてはわかりました。先ほどの総合教育会議について中止をするべきだと私は思っているのですけれども、そういう方向性について、改めて、今の現状の検討、議論している中身等々について、やはり不要な、二重なやり方だということを指摘しなければいけないと思っているのですけれども、その点についての見解を伺いたいと思います。","respondent":"米田総務課長","answer":"教育委員の方からも、区長との意見交換は必要な場面であるというようなことで、今後もこれを進めていくというようなことで、お互いに考えていることを意見交換しながら、行政として適切な教育の方向性を持っていこうというようなことで実施しているものです。","voiceIndex":382,"id":"exchange-163"},{"speaker":"南委員","kind":"意見","question":"私は最後に強調したいと思いますけれども、不要だと思います。中止すべきです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":384,"id":"exchange-164"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした取組みは有効と考える一方、人口増や少子化、少子高齢化の加速によって、区は今後も多様化する行政需要に対して応えていく必要性から、業務のさらなる効率化による生産性の向上や、よりよい区民サービスを実現するために、さらなる業務の分析や改善に取組んでいくことが求められると考えます。","respondent":"黒田人事課長","answer":"今後とも、そういった業務の中でどういった職が適する職かというところも検討しながら探っていきたいと申しましょうか、せっかく採用した暁には、ご活躍いただきたいと思ってありますので、そういった中で検討してまいりたいと考えています。","voiceIndex":386,"id":"exchange-165"},{"speaker":"こんの委員","kind":"提案","question":"１例をというか、先進事例というか、申し上げたいと思います。知的障害者の方々の特性による職域の認識を改めて、品川区としての働き方改革の一翼を担っていただくために、社会参加、体験を希望するこうした障害者、知的障害者や精神障害者の雇用を提案したいと思いますけれども、いかがでしょうか。","respondent":"黒田人事課長","answer":"ただ、そういった業務をどうやって切り出して集めて、仕事として確立するかというところについては、業務分析のほか、それぞれ職員の働き方、個々の職員の意識の改革も必要かと思ってありますので、そういった中で、現在、業務改善プロジェクトというものをやってありますので。","voiceIndex":388,"id":"exchange-166"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたことを、認識としてというかお考えとして持っていらっしゃるということが確認できましたし、またプロジェクトの中でもそうしたことを検討してくださるという今のご答弁をいただきましたので、ぜひ、一方で障害者の雇用、障害者の方が社会参加、体験をして、スキルをアップしていきたいということもありますので、区としての業務の分析をしていただいて、どこがどういうふうに。","respondent":"池田スポーツ推進課長","answer":"夏季プール一般開放といたしまして、区立の学校８校を一定の期間、開放していますけれども、日よけが少し不足しているところはありますので、開放するプールにつきましては、日よけのテントを設置するというようなことを考えているところです。","voiceIndex":390,"id":"exchange-167"},{"speaker":"こんの委員","kind":"提案","question":"学校体育館は、まず設置が順次ということなので、大型の扇風機を入れていくということです。一気にはつけられないので、そうした対策は必要だと思いますけれども、その点は進めていただきたいと思います。ここでは地域スポーツ施設開放の件なので、学校の施設のことは要望だけにしておきますけれども、プールサイドにつける日よけはどんなものを考えていらっしゃるのか、最後、お考えだけお願いします。","respondent":"池田スポーツ推進課長","answer":"可能であれば、ビーチパラソル。ビーチパラソルが設置できないところはブルーシート等で覆いができるような形で、簡易な屋根をつくりたいということです。","voiceIndex":392,"id":"exchange-168"},{"speaker":"渡部委員","kind":"質問","question":"２点伺っていきます。当然、品川区は競技会場であって、オリンピックを盛り上げよう、パラリンピックを盛り上げようと、今日の議論でもさまざま出てきている中で、実際、そのような流れに乗っかって、みんなができるような取組みの中で、庁有車は何台ぐらいそれをやっているか、もし数がわかれば教えてください。","respondent":"立木経理課長","answer":"庁有自動車、経理課のものと、あと所管で持っているものがございまして、８４台ほどあります。その中で、オリンピック、それからワールドカップのナンバーをつけている車両は、今、一台もございません。","voiceIndex":395,"id":"exchange-169"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区と書いてある車にそういうものがついていると、区も頑張っているのだ、ついでに番号も、４７５８か何かに統一して、オリンピックマークもついていて、「品川区はやる気があるな」というぐらい、やってほしいと思ったので。多分、見かけたことがないので、ないのだろうと思ったのですけれど、要望でとどめますが、機会があればこれを進めてほしいと思います。まだオリンピック開催まで時間はあります。","respondent":"提坂戸籍住民課長","answer":"４月から窓口業務委託を開始するわけなのですけれども、まず窓口でどこに申請書を出せばいいかとか、迷われているお客様に適切に案内するためのフロアマネージャーもまず委託します。それから、窓口に申請書を出した際に、その受け付けも委託します。","voiceIndex":397,"id":"exchange-170"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区のホームページで、よくあるお問い合わせを開いても、何もなくて、多分、それこそ士業に代理で来てもらったりする方は、「もうお願いしたよ」というので、お金を払えばそれで終わるのだけど、大抵の方は自分たちで来て、そういう作業をやるときに、何度手間にもなってしまってというのはあると思うのだけど、何かその辺の改善策を考えてほしいと思うのですけれども、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"今回、委託を入れるに当たって、レイアウトも変えるのですが、カウンターのほうも、すぐに要件が終わるお客様についてはハイカウンター、若干お時間がかかるお客様についてはローカウンターの形に見直しを図る予定です。","voiceIndex":399,"id":"exchange-171"},{"speaker":"渡部委員","kind":"質問・要望","question":"とにかく、これは委託が１２月から始まるというのも承知していますし、これから本格的に動く中で、今までの問題点なども精査しながら、これから使いやすいカウンター等もつくられていくのだと思うので、まずはしっかりとしたマニュアルをつくられて、皆さんが、来庁いただく区民の方々からしてみれば、区の職員も委託先の従業員の方も関係ないわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":401,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":124331,"voices":402}},{"id":"r01-20190308-3","meetingId":"r01-c-budget","date":"2019年3月8日","dateIso":"2019-03-08","committee":"予算特別委員会","time":"午後１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"おはようあります。太陽の光が明るい中で質問するのが久々なものですから、よろしくお願いいたします。２３９ページ、児童相談所移管推進事業と、２５９ページ、オアシス・ポップンルームの運営についてお伺いをしたいと思います。児童相談所でありますけれども、品川区も準備を始めていると思う、もちろんやっていると思いますが、４月から明石市で始まる。拡充、それから、強化をしていく。","respondent":"高山子ども育成課長","answer":"その後の話としましては、児童相談所の開設については子供の森公園を予定しておりますので、そちらについての設計経費などは今年度も計上させていただいているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その役割分担がありますよね。東京都との役割分担、ここら辺の相談を今進めていくときに、どこまで突っ込んで相談を聞いて、なおかつ、それを東京都とどのように連携を図っていくのかということが非常に求められてくるのだろうと思っておりまして、そこら辺の連携のやり方をどう考えられているのかということをお聞きしたい。設置をしていくわけですよね。","respondent":"二ノ宮児童相談所移管担当課長、高山子ども育成課長","answer":"私から、お尋ねのありました都との連携と児童相談所の業務の引き継ぎの関係のご質問にお答えいたします。私どもが児童相談所を開設した暁には、基本的には自力で解決すると、場合によっては東京都と調整ということになります。１点目ですけれども、場所の問題ということで、当面は、第三庁舎の５階部分に執務室を構える予定でございまして、その後は、４階部分の入居の状況なども踏まえながら、段階的にさらなる移転を考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つだけ、都議会の中でもいろいろ質問が出たり、東京都の回答があったりする中で、東京都は、私の理解が間違っていたらこれは言ってください。もう一個は要望になるけれども、これは本当にそこら辺、真剣にやっていただいて、拡充をして、いろいろな対応ができるような体制をぜひ早目にとっていただきたいなと思いますので、その１点だけ答えてください。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ただいまのご質問につきましてですが、正直申しまして、東京都は心配しているという部分は多分、将来的にも変わることはないと思います。ただ、その一方で、現実的に、先行３区の開設時期も迫っておりますので、現実的に協力のほうに向いてきたというところが正直な感覚です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひよろしくお願いします。この前、ある３団体ぐらいのお母さんたちの会のトップクラスの方々とお話をさせていただきました。在宅支援であるオアシス、これは５００円でお金を払っていく。ポップンだって運営にお金がかかるわけですけれども、お金をかけなくても、場の提供さえあれば、その方々に、逆に私が言ったのは、みんなまとまって、プロポーザルでもいいから、そういう提案をしてくださいと。","respondent":"高山子ども育成課長","answer":"委員ご紹介のそうした新たな食を介したつながりといいますか、孤立化、孤独感を取り除くような、そうした事業は、２３区で見ても、なかなか取組みの例がないことですから、そうした支援をそのような団体にすることによって、よりその活動の幅が広がるということであれば、今後。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"２人で来ても、そこへ座って一緒に話を聞いてくれる。そういうスナック型みたいなものがいいのではないですかなんていう話を踏まえて考えていただけないかなと思っておりまして、ぜひその考え方について、意見を聞いてほしい。逆にそういう情報をとって、旧荏原四中跡だとか、空き家とかあるわけだから、そういうところの活用をぜひ考えてほしいけど、最後、そこら辺の活用のところを聞きたい。","respondent":"高山子ども育成課長","answer":"空き家活用という点で申しますと、いわゆる住宅部門のほうでそうしたストックの情報を持っているときに、その全体的な活用については、私ども、子ども未来部も含めて考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、オアシスルーム、区内に１０カ所、整備をしていただいております。そこで、細かい数は結構ですのでこの現在の１０カ所の利用状況、ここはちょっと多めに使われている、こちらはちょっと利用が低いとか、そういうことが見えているかと思うのですけれども、そういう利用情報を見ながら、どういう手を打たれているのかということをちょっとお伺いをしたいと思います。","respondent":"大澤保育支援課長","answer":"上限の６０回ですけれども、いっぱい使ってしまって、それ以上というようなご要望は今のところはあまりいただいたことがございませんので、６０回の上限で大体ニーズには応えられているというふうに認識しています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、２つ開設をされますオアシスルームは、これまでは区有施設の中に設置がされている例がありましたけれども、今回は、戸越６丁目、民間のテナントの一角を借り上げてのオープンということで、どういう流れでこの民間でのオープンに至ったのかという経緯をお知らせいただきたいと思います。その後、この地域への開設も手を打っていただいているのかということ、民間施設も含めて教えてください。","respondent":"大澤保育支援課長","answer":"八潮、勝島地域にオアシスルームがなくて、あちら側の方がなかなか利用できないというお声はいただいておりますので、今後の開設に向けて、努力してまいりたいと考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"さまざま、また開設のほうは準備を進めていただきたいと思います。関連いたしまして、病児保育室についてお伺いいたします。今回、３１年度にまた新たにオープンして、区内で４つのこの病児保育室が整備をされることとなりました。この考え方ですけれども、現在、２カ所が４カ所に拡充される今後の考え方、拡充の方向性があるのかというところをぜひお聞かせください。","respondent":"佐藤保育課長","answer":"具体的には、子ども・子育て支援事業計画を今後、来年度、改定いたしますので、この中で詳細を詰めていく予定です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"まだ拡充の検討をしていただけるということで、いい答弁をいただきました。実は、東品川、勝島地域というのは、新しい大きなマンションが建っております。現在、４カ所のところというのは比較的、荏原地域、大崎地域でありますので、具体的に、東品川、また、勝島地域のあたりで具体的にぜひこの拡充をお願いをしたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"病児保育などの拡充の関係ですが、委員ご指摘のとおり、武蔵小山、上大崎、南大井、中延のほうに４カ所ありますので、今後も地域バランスを考えて、適切に整備できるように調整してまいりたいと考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"どうぞよろしくお願いいたします。高齢者住宅について、建設型の高齢者住宅についてお伺いをいたします。そこで、お住まいの方から、不便があるというお声を聞いておりますけれども、今後、３１年度におきまして、この高齢者住宅においてのどのような整備がされるのか、お伺いをしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"３１年度につきましては、毎年、適宜改修工事を加えさせていただいている中で、各設備の更新工事なども行わせていただいておりまして、冷温水ポンプの交換工事を予定しています。防犯カメラの設置工事も、予定をしています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"さまざま計画的には整備が進んでいるというご答弁をいただきました。今、お声をいただいているのは、住んでいるお部屋の中のことで不便があるというお声もいただいております。私は八潮の住宅の中しか確認をしたことはありませんけれども、その当時の３０年前におきましては、いい設備であるなというふうには認識をします。このお住まいの中の設備に関しての整備はどのようにお考えか、お聞かせください。","respondent":"宮尾高齢者地域支援課長","answer":"今後も、より快適にお住まいいただけるように、指定管理者とも適切に連携をとらせていただいて、管理、運営に努めてまいりたいと思います。","voiceIndex":26,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"２４５ページ、保育園運営費、２５２ページ、保育支援費など、待機児童問題、保育園保育料問題、そして、２５９ページ、幼児教育の無償化についてお伺いをいたします。数字を教えてください。以上、よろしくお願いします。","respondent":"佐藤保育課長","answer":"私立に関しましては、０歳児が２、１歳児が０です。２歳児が２６、３歳児が１４０、４歳児が３０５、５歳児が４２９で、合計が９０２です。私立と公立あわせて、空き状況全体で、１,１７５という数が今のところ出ております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"二次の不承諾通知を受けた９１５人の内訳はわからないのでしょうか。ぜひ今後知りたいので、お願いします。","respondent":"佐藤保育課長","answer":"不承諾を受けた方ですね。０歳児が１５８、１歳児が４８８、２歳児が１３３、３歳児が７８、４歳児が３７、５歳児が２１です。","voiceIndex":31,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"確認","question":"平成３０年度の最終の数字です。他の施設が２６８人引いています。質問ですが、不承諾者数７０６人から６８７人を除いていますけれども、６８７人は、認可保育園を申し込み、希望がかなわなかった子どもたちですけれども、４点伺います。４点目、育休中４６人の状況はどのような状況なのでしょうか、教えてください。４月入園が決まれば、４月から働きたい人ではないのでしょうか。この点を教えてください。","respondent":"大澤保育支援課長","answer":"１点目の待機児童にカウントしない理由ですが、これは厚生労働省の待機児童の定義に沿ってカウントしたものですので、それに沿っているというのが考え方です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"入園がかなわなかった人は全て待機児と考えるべきではないでしょうか。続けて質問をいたしますが、２０１８年、昨年の数字をもう一つ聞きます。答弁の中で、３００人の空きがあるので、選べばどこかに入れると趣旨で、待機児はほぼ解消したと、この点を伺いますけれども、質問です。認可と認証で３００人です。この点をお伺いします。改めて、認可保育園の空き、０歳、１歳、２歳、それぞれ教えてください。","respondent":"大澤保育支援課長、佐藤保育課長","answer":"３０年４月の空きの状況ですけれども、認可保育園の空き状況が９９２と、残りが認証ということになります。２番目のご質問ということで、４月の二次選考の認可保育園の空きですけれども、０歳児は２名、１歳児は０名、２歳児は３３名です。","voiceIndex":35,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません、冒頭に言ったのですが、２０１８年、昨年の数字をもう一回お聞きしますと言ったことですが、ちょっといいです、持っているので。既に認証に入っているにもかかわらず、認証から認可に４月、移った後に空きますよという数字を示したら、そのまま認証で我慢しなさいということになるのではないでしょうか。切実な声が届いています。解消は取り消していただきたいと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"認可と認証とあわせて、きちんと区としては施設を用意しているという認識ですので、待機児童は３０年４月も、３１年４月も実質的にはゼロということで認識しています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが入れないのに、どうして認可の待機児にならないのか。保育料、第２子以降の保育料軽減について、お伺いをします。１子、２子、共産党としては、１子、２子、３子など、数え方を戸籍上と同じにしていただきたい、こう求めていますが、品川区は小学校３年生までの兄弟がいる第２子保育料が半額、第３子以降が無料となっています。どの子も受けられるようにしていただきたいのですが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"今後もそういった多子の軽減について、さまざま検討して進めていきたいと思います。","voiceIndex":40,"id":"exchange-017"},{"speaker":"松永委員","kind":"確認","question":"私からは、２１９ページのいきいき健康マージャン広場、２０８万２,０００円について、２１９ページの高齢者外出習慣化事業、５２９万１,０００円について、２４３ページの子ども食堂開設・運営支援等、しあわせ食卓事業についてお伺いいたします。２１９ページのいきいき健康マージャン広場について伺います。お知らせください。３つのコースの状況はどのようになっているのでしょうか。あわせて伺います。","respondent":"宮尾高齢者地域支援課長","answer":"初めて取り組む方につきましては、毎年２月に広報紙で募集をさせていただきまして、今年につきましては、２月２１日号の広報紙で募集をさせていただいたところです。","voiceIndex":44,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"今の状況というのは、空き状況はないということでよろしいでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"リアルタイムで常に把握、必ずしもできていない部分があるのですが、基本的には埋まっているという状況です。空いているときに、お問い合わせがあれば、そこをご案内をすることになります。","voiceIndex":46,"id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"こうした空き状況についてなのですが、毎回チェックの電話をしなければ確認できないということであります。そうした中で、インターネットを活用して空き状況がわかれば便利になるのではないかと思うのですが、いかがでしょうか。この３つのコースについて、人気のあるコースで入れない状況が続いているのではないか。各コースの定員数を確認したところ、少ない感じがいたします。","respondent":"宮尾高齢者地域支援課長","answer":"確かにお問い合わせをいただくような形を、今、とらせていただいておりますが、委員がおっしゃっているように、インターネットを使う方、あるいは、使っていらっしゃらない方もありますので、その辺を少し丁寧に進めてまいりたいというふうに思っております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"よろしくお願いします。立会川近辺にお住まいの方より、会場までの距離が遠いということで、その方は東品川のほうまでタクシーで行っているらしいのですが、その辺を含め、会場数を増やすことは今後可能なのかどうか、お知らせください。品川区内には、約４１のマージャン店があると思うのですが、そことの連携や空き店舗の利活用について検討してみてはどうかと思うのですか、区の見解をお伺いしたい。","respondent":"宮尾高齢者地域支援課長","answer":"そのかいもあってということではないのですが、３１年度につきましては、１コース、増やしていただくというご協力をいただいたところです。今後もいろいろな可能性も含めて、研究してまいりたいと考えています。","voiceIndex":50,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"同じく２１９ページの高齢者外出習慣化事業、５２９万１,０００円についてお伺いします。先ほども述べさせていただいたように、いきいきマージャン広場もこの事業に似ておりますので、関連して質問いたします。初めに、平成３０年度決算額より約３６万円の減額でありますが、この高齢者外出習慣化事業のこれまでの実績や主な内容について伺います。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者外出習慣化事業ですが、こちらは、内容といたしましては、調理設備のある施設を活用させていただいて、地域のＮＰＯ等に委託をして、高齢者の方に、栄養バランスのとれた食事の提供、あるいは、会話を楽しんでいただくなどして、顔見知りの輪を広げていただく。","voiceIndex":52,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"その利用者数が減ったというのは、何か問題があって減ってしまったのかどうかというのは区は把握されているのでしょうか、お伺いしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"こちらは、実際にお申し込みいただいた方の中で、体調不良等を理由に欠席をされる方がいらっしゃる、こういうふうに分析をしています。","voiceIndex":54,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"２４３ページの子ども食堂開設・運営支援について伺います。そこで、子ども食堂の取り組みが開始されてから、課題や要望等も運営側から出てきていると思います。人員については、ボランティア体制。そこで、この来年度の予算にありますこの運営支援について、どのくらいの予算がついており、主にどういったところに活用されているのでしょうか。あわせて伺います。","respondent":"廣田子ども家庭支援課長","answer":"今、１７カ所ありますけれども、１つ休止しているところがありますが、そちらにつきましては、ほかのところでシェアを広げて、残念ながら、品川区からは外れた場所で広げているというところで、現在休止しておりますが、その他のところでやめてしまったところは。","voiceIndex":56,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"もう一つ、私が聞きたかったのは、子ども食堂開設・運営支援等で約１,１００万円のうち、その内訳です。運営費にどのぐらいかかっているのか。子ども食堂の開設について、お伺いしたいのですけれども、来年度、何カ所開設する予定なのでしょうか、あわせて伺います。","respondent":"廣田子ども家庭支援課長","answer":"今後の開設予定については、子ども食堂については、地域の方がやりたいとおっしゃったことを支援しているところではありますが、現在開設予定のところが二、三カ所、もう既にあるというふうには聞いてあります。","voiceIndex":58,"id":"exchange-025"},{"speaker":"藤原委員","kind":"提案","question":"２３３ページ、国民年金事務費について、まず、お伺いしますけど、来年度、制度が変わるのは二つあると思うのですけど、産前産後保険料の免除制度と、もう一つは、年金生活者支援給付金が大きく変わってくると思うのですが、具体的に教えてください。それと、２３７ページの児童センターなのですけれども、すまいるスクールの有料化の後、利用者数、利用する形態など、変化が出てきたか、教えてください。","respondent":"三ッ橋国保医療年金課長、吉田保育施設調整担当課長、飛田障害者施策推進担当課長、大澤保育支援課長、佐藤保育課長、高山子ども育成課長","answer":"年金生活者支援給付金につきましては、施行については平成３１年の１０月１日、消費税の１０％引き上げの日とされておりまして。今回、１階部分の柱を除いて、ほとんど解体したような形で工事を行いますので、全面的な改築というふうに認識しております。今度１０月にオープンいたしますが、当初、プロポーザルで区が求めた事業と、法人が挙げました自由提案については。次のオアシスについてですが、ざっくり言いまして、１時間３,０００円ほどかかっておりますけれども、それについて。","voiceIndex":62,"id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"だから、この去年まであったかもしれないのですけれども、いわゆる待機児童対策担当課長がなくなったというふうに、私は思っているのですけれども、その辺についてお伺いしたいと思います。それと、最後に１点、２１３ページで成年後見制度なのですけれども、毎回聞いているのですけれども、品川区の成年後見制度は、いわゆるトラブルというか、事件性になる問題はないのですよねという確認をします。","respondent":"三ッ橋国保医療年金課長、大澤保育支援課長、大串福祉計画課長","answer":"年金制度につきまして、職員一同、きちんと説明ができるように対応してまいります。３０年４月から待機児童は実質的にゼロになりましたので、待機児童対策担当課長というのもいなくなりましたが、引き続き、保育支援課としては。そうした状況ですので、不正といったところでは今のところ聞いてない、報告ないといったところです。","voiceIndex":69,"id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"２１３ページ、１目福祉計画費、２３４ページ、１目子ども育成費でネウボラ事業、時間があれば、２５５ページ、遊戯場提供支援事業について伺います。管理人が在宅介護支援センターへ相談へ行ったときに、在宅介護支援センターから後見人に、利用者の状況確認をしてもらうことなどはできないものなのでしょうか。これらの課題について、区はどのような認識を持ち、成年後見制度を促進していくのか、伺います。","respondent":"寺嶋高齢者福祉課長、大串福祉計画課長","answer":"今回の件は、私どもにもご相談がありましたので、関係各所と対応しまして、最終的には結論までは到達したのですけれども、基本的には、在宅介護支援センターのほうで対応ができないといったような判断があった場合に。ただ、今現在、やはり成年後見制度と個人情報の関係といったところ、また、被後見人のご意思といったところがありますので、その辺につきましては、今後も検討はしていきたいと思います。","voiceIndex":74,"id":"exchange-028"},{"speaker":"田中委員","kind":"確認","question":"まず、こういう状態に陥ったときには、在宅介護支援センターに相談に行き、そして、なかなか対応がされないようだったら、区に問い合わせるということで、確認しました。後見制度のほうです。後見制度については、利用者が、周囲に利用を知らせたくない場合、今回の事例のようなことが起こり得るということを、利用を検討されている方には伝えているのでしょうか、伺います。","respondent":"大串福祉計画課長","answer":"やはり成年後見制度をご利用される方の中で、周囲にそういった自分が後見制度を利用しているということは知らせたくないというお気持ちがあれば、それは尊重すべきところですし、また、それ前提にして。","voiceIndex":77,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"しかし、私の探し方が悪いのか、区のホームページでは確認ができませんでした。そのような配慮も必要だと考えますが、いかがでしょうか。そして、ホームページ上の配慮がされたと仮定して要望いたしますが、思いがけない妊娠の相談窓口ホームページにつながるＱＲコードを、男女両方のトイレの個室などに設置することはできないでしょうか。男女ともに、思いがけない妊娠の相談窓口を求めています。","respondent":"大串福祉計画課長、仁平品川保健センター所長","answer":"先ほどの、田中委員のご質問のところですけど、区が関与しているのは、区長申し立てを行ったものだけでございまして、親族後見に係るものについては区のほうでは関与していないです。ホットラインの掲載の件ですけれども、現在、ホームページ上のどこが一番入りやすいかというところと、その他の広報紙掲載等も必要ではないかということで、今、検討を進めているところです。","voiceIndex":79,"id":"exchange-030"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、２１５ページ、認知症高齢者支援事業について、あとは、２１７ページ、高齢者福祉施設支援事業について、時間が余れば、２５８ページの生活保護費について伺います。把握している中で結構ですので、品川区の中で認知症患者数とその利用者の割合、もしくは、人数というのを教えてください。それと、品川区が考える認知症の方が徘徊をしていくことに対するリスクというのもあわせてお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"ＧＰＳを利用した形の機器、これは有料になりますけれども、こちらのほうが３０年度の当初の数字しかわかりませんが、２２名ということになっております。それから、品川区が考える徘徊高齢者のリスクですけれども、１つはやはりご本人の身の危険ですね。","voiceIndex":86,"id":"exchange-031"},{"speaker":"芹澤委員","kind":"質問・要望","question":"認知症の中で、約６割を占めるアルツハイマー型という認知症が徘徊をしやすい認知症というふうに伺っております。現在の品川区の探索システムの対象枠でありますが、認知症による徘徊歴があり、原則６５歳以上の方という制限になっています。そうであれば、この記述というのは修正をしていくというのも検討していただきたいと思いますが、ご意見をお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"ＧＰＳ関係の機器のほうはこういった今規定になっておりますけれども、その前段にご案内したいわゆるアイテム、見守りキーホルダー等につきましては、これは外出に不安のある方というくくりでやらせていただきまして。","voiceIndex":88,"id":"exchange-032"},{"speaker":"芹澤委員","kind":"確認","question":"もう一度確認したいのですが、今、２つアイテムがあるということでお話はいただいております。２つとも同じような目的になるかと思いますが、この条件をつけなければならないという理由があるのかがわからないのですが、もう一度お願いします。","respondent":"寺嶋高齢者福祉課長","answer":"１つは、予算規模、それから、実際にご本人の負担のものということもあるのですけれども、最初にご案内した、今、２２２名の方にご利用いただいている見守りアイテムというのは、まず、ご利用者のご負担がないということ、それから、個人情報がわからないように番号登録をして。","voiceIndex":90,"id":"exchange-033"},{"speaker":"芹澤委員","kind":"質問","question":"続いて、高齢者福祉支援事業について伺います。行政として、人材の育成、あとは、就職支援と同時に、業務の効率化を図って、人材１人当たりの業務量を減らしていくということも大切かと思っています。なり手不足に対して、今、区の取り組みと、あとは、この保育、介護におけるＩＣＴ化、進んできているとは思いますが、その評価をまずお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"我々も、いろいろな展示会等に行っているので、そういった機器の確認をしたり、メーカーに来ていただいていろいろご説明を受けたりと、こういったことで、少しでも業務の負担軽減、効率化ができるような形のものが導入できればということで、日々情報収集に努めているところです。","voiceIndex":92,"id":"exchange-034"},{"speaker":"芹澤委員","kind":"質問","question":"今、ＩＣＴ化というと、大体施設においてはハード面とソフト面のＩＣＴ化というものがあると思っています。この保育に関しては、ＩＣＴ化推進というのは品川区が進めていて、介護のＩＣＴ化というのは補助金とかが東京都から出ているような気がするのですが、これを品川区がやらないというか、そういう分け方がなぜこうなっているのか教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"詳細のその決まり事があるかと言われると、なかなかこれは難しいのですけれども、まずは東京都のほうがいろいろな補助メニュー、それから、事業メニュー等を示すということで、これが一定程度、全国的にもオーソライズされているような内容であるということが感じられますので。","voiceIndex":94,"id":"exchange-035"},{"speaker":"芹澤委員","kind":"確認","question":"今、品川区の中に外国人が非常に多いかと思うのですが、生活保護を受けている外国人がいらっしゃるのかどうかということと、あとは、国会のほうでこれは議論されるべきお話だと思いますが、現状で、品川区のところに外国人が窓口へ来たときに、それを受ける、受けないというのを対応できる根拠法というのは何になっているのかというのをちょっと確認でお聞かせください。","respondent":"矢木生活福祉課長","answer":"本来は、日本国籍を有する方ということになってありますが、局長通知等で生活保護法準用という形で生活保護、外国人の方についてもご相談は承っているところです。","voiceIndex":96,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"というのも、今、東京都で、民間におけるファンドを活用した福祉貢献型建物の自律的な整備促進等に関する検討会というのを行っておりまして、そこでも福祉貢献型建物はやはり低収益と言われている福祉関連施設と収益が見込める収益施設を一体とさせて、それで、収益性の確保、そして、民間からの投資も可能ということで。","respondent":"宮尾高齢者地域支援課長","answer":"私ども、高齢者多世代交流支援施設、ゆうゆうプラザということで、現在、３カ所、３月１日に４カ所目の平塚ゆうゆうプラザをオープンをさせていただいたところです。","voiceIndex":101,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"次に、認可外居宅訪問型保育、ベビーシッターについてお伺いいたしますけれども、歳出予算見積書では、月３人ということで想定されていますけれども、これ、私としては少ないのかなと思っているのですけれども、その今のベビーシッターの利用状況についてのご見解と、なぜ少ないのかということをまずお聞きしたいのと、また、今。","respondent":"大澤保育支援課長","answer":"利用者が少ない理由としましては、３０年度新規開設の認可保育園が数多くございましたので、一定、認可保育園のほうで需要が満たされているということだと考えております。","voiceIndex":105,"id":"exchange-038"},{"speaker":"筒井委員","kind":"提案","question":"このベビーシッターの助成なのですけど、保育園を申し込んで不承諾が要件となっているのですけれども、それが結構、今後、使い勝手が悪くなるのかなと思っていまして、この不承諾要件は、撤廃というか、区からそうしたことは提案できないのかということと、また、当初からベビーシッターを利用したいという方もいらっしゃると思うのですけれども、そういった区民からのお声というのは入っているのでしょうか。","respondent":"大澤保育支援課長","answer":"不承諾の要件の撤廃に関しましてですけれども、やはりこれは待機児童対策の一環ということで、既存の認可保育園が、まだ空きがあるような状況ですので、そちらの施設をまず第一に使っていただきたいということと、あと、ベビーシッターは基本的に１対１ですので、今。","voiceIndex":107,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。次、支え愛・ほっとステーションなのですけれども、今、全１３カ所ありまして、相談の件数の多さに地域差があるのかということと、社会福祉協議会から来ている２人のコーディネーターで、ちょっと業務の対応が難しいということはないのでしょうか。","respondent":"大串福祉計画課長","answer":"中には、当然、対応が難しいといったケースも出てきております。そうしたときには、やはり区であったり、在宅介護支援センターであったり、そういった専門機関のほうで受けとめさせていただきながら、対応する。そういった状況です。","voiceIndex":109,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。非常にいい事業だと思いますので、引き続き、ご苦労あるかと思いますけれども、どんどんやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-041"},{"speaker":"おくの委員","kind":"提案","question":"品川区国民健康保険事業会計の４２４ページ、国民健康保険料にかかわって、子どもの国保料均等割、無料化について質問いたします。そこで、共産党は、品川区に対して、区独自にでも実施できる子どもの均等割の廃止、無料化ということをこれまでも何度も提案してきました。こういう区が子どもの均等割無料化ということを拒む理由は、今のような認識でよろしいでしょうか。ご質問いたします。","respondent":"三ッ橋国保医療年金課長","answer":"その国民皆保険制度の相互扶助の考え方に基づいた制度です。その中で、所得割、均等割という部分があります。今回、委員ご指摘のように、子どもの公平性の部分ですけれども、やはりこの子どもの均等割という部分では、一般財源から賄うこととなり、非常に困難と考えております。","voiceIndex":113,"id":"exchange-042"},{"speaker":"おくの委員","kind":"質問","question":"それで、一般財源から賄うことになると、国保加入者以外の区民にも負担が行くことになるので、不公平になるのだという答弁が過去にあったのですけれども、そういう認識でよろしいのですか。","respondent":"三ッ橋国保医療年金課長","answer":"公平性の観点ですけれども、国保以外の被用者保険の方を含めた一般財源から賄うこととなりますので、公平性の観点から、非常に困難と考えております。","voiceIndex":115,"id":"exchange-043"},{"speaker":"おくの委員","kind":"提案","question":"つまり、私が払った消費税は、おくのが払った消費税や所得税はおくののために使われるべきだと。要するに、税金に色はない。だから、できることはやっていくべきだと思うのですけれども、そういうできる範囲でやっていこうではないかということで、やれることをやっていただきたいという提案なのです。だから、国保加入者以外の方の負担をという論は成り立たないと思うのですけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"子どもの均等割の部分ですけれども、国保制度というものにつきましては、先ほど申し上げましたように、０歳から７４歳までの方の社会保険やほかの保険などに加入する方、生活保護の方を除く全ての方が対象となっております。これは国民健康保険制度、皆保険制度です。","voiceIndex":117,"id":"exchange-044"},{"speaker":"おくの委員","kind":"質問・要望","question":"この今の日本社会の中で、同じ医療サービスを受けるのに、２倍以上の負担を強いられている。だからこそ、品川区もぜひ立ち上がっていただきたいと思います。品川区から正式な回答がありまして、この品川区では２億円の財源でできるということを正式に回答しました。その額でできることですから、ぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-045"},{"speaker":"つる委員","kind":"提案","question":"私は、昨年の第３回定例会で、２０１５年から調布市の駅前で展開されているカフェ「aona」を参考に、品川区もそうした気軽に立ち寄れるという視点で提案をさせていただいて、「aona」はまさに、先ほど石田秀男委員が質疑されたような方を対象にしているような施設でありまして、児童館や保育園の子育て広場などを積極的に利用できず、潜在化して孤立している子育て世帯を。","respondent":"高山子ども育成課長","answer":"ご提案いただいておりますいわゆるパパママカフェというような、そうしたこれまでなかなか取り組みが比較的できてない部分につきましては、文字どおり、なかなか場所でありますとか、いわゆる担い手の問題等もありますので、今現在、著しい進捗があるというわけではありませんが。","voiceIndex":122,"id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"そうした方々との結びつき、これをしっかりいかに品川区としてつくっていけるか、そこが品川区、今、人口は増えていますけれども、やはりそれをしっかりと定住していただくとか、そうしたことも含めて、幅広く施策展開をしていく中では、そこの視点というのは大事な視点かと思いますので、積極的にそういう情報収集をしていく、確認だとか、交流だとか、そうしたこともやっていただきたい。","respondent":"大澤保育支援課長","answer":"この行政枠の利用について無料にするということに関しましては、さまざまなハードルがあると思いますけれども、現在、その課題について洗い出しを行っておりますので、今後この課題解決に向けて検討を進めてまいりたいと考えているところです。","voiceIndex":124,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"課題解決に向けて検討ということで、駐車場の事例を引き合いに出させていただきましたが、ぜひそういう方向でしっかりとするようにやっていただきたい。次に、すまいるスクール運営費でありますが、これも昨年の第３回定例会で質問させていただいて、その後の決算特別委員会でも質疑をさせていただきました。","respondent":"高山子ども育成課長","answer":"現状で申しますと、大きくは検討のほうは進んでおりませんが、一つは、先だって実施しておりますすまいるスクールの利用者アンケートのほうで、直接的ではありませんけれども、給食利用についてのお尋ねというのも一つ、質問項目の中にも入れてあります。","voiceIndex":126,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"私が求めているのは、その長期休業中における配食サービスの活用という視点での設問項目、それに対してはどういうお答えなのかというところも大事なので、当然それが含まれたような設問の聞き方であれば、当然そうした回答というのは参考になるかと思いますけれども、ぜひそのすまいるスクール、長期休業中、ここは利用とかというのは、一般質問等でもお伝えさせていただいたとおりでありますので。","respondent":"宮尾高齢者地域支援課長、川島健康課長","answer":"区では、これまでも元気な高齢者の方が要介護にならないようにということで、各種介護予防事業を実施をさせていただいているところです。フレイルの３要素を踏まえた事業の体系化というところも行ったところです。そういった世代の方たちの担い手になる方ということで、健康づくり推進委員に対して１月に実施した研修交流会の中でもフレイルを取り上げたところですが、大変好評でして。","voiceIndex":128,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ、大きく、介護予防という視点も含めて、考えていただきたいと思います。最後の障害者福祉については、これはまた別の款でも確認します。まさにそうした商品、ブランド化させて展開をしていく、そうしたことが、親なき後の障害をお持ちの方の生活をしっかり支えていく部分で非常に大事な視点かと思いますので、また別の機会でここについては伺っていきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２３９ページの児童相談所移管推進事業についてとファミリーサポートセンター運営費についてをお伺いいたします。１点目はファミリーサポートセンター運営費についてお伺いいたします。区民の方から、希望する時間帯に提供者がいないために、利用したくてもできないというご意見を伺っていますが、現在の品川区におけるファミリーサポートのマッチングの状況を教えてください。","respondent":"廣田子ども家庭支援課長、高山子ども育成課長、二ノ宮児童相談所移管担当課長、黒田人事課長","answer":"私からは、ファミリーサポートセンターのマッチングの状況についてお答えいたします。最後、３点目の支援が届きにくいポスト青年期の子どもたちへの支援という点で申しますと。ご紹介のありました支援と介入という部分につきましては、児童相談所の設置の暁における両者の関係ということになるかと思うのですけれども。児童相談所の職員の対応の件について、お答えいたします。","voiceIndex":133,"id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"文部科学省認定ＡＦＴ、１級色彩コーディネーターの前出幸乃さんにお話をお伺いしました。区の発注工事における内装等の分離発注の検討を要望いたしますが、ご見解をお聞かせください。品川区の子どもたち、区民の方々、そして、品川区のために働いていただく方々、子どもたちにかかわる全ての方々が、毎日一分一秒でも長く笑顔で過ごしていただけるような環境整備について、区のご見解をお伺いいたします。","respondent":"高山子ども育成課長、二ノ宮児童相談所移管担当課長","answer":"そういったこともありまして、昨年よりもいわゆるケースのやりとりであるとか、あるいは、情報交換の件数が多くなっておりまして、２桁というふうな状況もありますので。私のほうから、残りのご質問にお答えいたします。","voiceIndex":138,"id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"設計のほうについてなのですけれども、分離発注というところ、要望と、プラス、ちょっとコメントのほうもいただきたいなというような思いで質問をさせていただいたところだったのですけれども、ぜひ、詳細について、お願いいたします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"僣越ではありますが、現在ご審議いただいております予算案におきましては、あくまでも実施設計に関する予算ということでご審議いただいているものと考えていますので、その先のいわゆる工事費の執行に関する点については、今。","voiceIndex":141,"id":"exchange-053"},{"speaker":"横山委員","kind":"質問・要望","question":"今の段階でということで、そのように承らせていただいて、今、趣旨のほうもお話させていただきましたけれども、限られた予算の中で、お子さん方、保護者の方々にとって、どのような空間がいいのか、また、働く職員の方々にとって、どういったことができるのかということ、これから細かいところは進めていただくのかと思うのですけれども、発注のあり方ですとか。","respondent":"高山子ども育成課長","answer":"これまで、基礎自治体として取り組んでまいりましたさまざまなそうした子育て支援施策と新たに受けとめる強い権限を持った児童福祉業務としっかりと融合して、子育てするなら品川というふうに、そんな言葉でも言われますけれども、住んでよかった、そして。","voiceIndex":143,"id":"exchange-054"},{"speaker":"木村委員","kind":"質問","question":"今日は、２１３ページの中ごろ、支え愛・ほっとステーション事業からの質問です。今日は、高齢者を中心にお聞きをいたします。区内には、６５歳以上の高齢者は８万人を超えておりますけれども、数年後には人生１００歳時代と言われ、ますます長寿社会へと移行していくことが予想されます。そして、現在も増え続ける人口の中で、一人暮らしの見通しは今後どのようになっていくとお考えでしょうか。","respondent":"大串福祉計画課長","answer":"一人暮らし高齢者ですが、２０１７年時点の数字になりますけれども、この一人暮らし高齢者としては７,０１５人になります。今後、高齢者人口が増えていく中においては、一人暮らしの高齢者、こちらもやはり増えていく流れになっていくというふうには考えているところです。","voiceIndex":146,"id":"exchange-055"},{"speaker":"木村委員","kind":"質問・要望","question":"７,０１５人ということで、これからますます増えていくという形になりますから、本当にこの大変な事業になろうかと思いますけれども、どうぞこの点、よろしくお願いをしたいと思います。","respondent":"大串福祉計画課長","answer":"支え愛・ほっとステーションで登録をいただいております地域支援員というボランティアの方になります。こちらの方が、昨年１２月末の数字になりますけれども、全１３地区であわせて３３１名の方に地域支援員ということでご登録をいただいているところです。","voiceIndex":148,"id":"exchange-056"},{"speaker":"木村委員","kind":"質問・要望","question":"これは、その数で十分足りているのかどうかということもお聞かせいただきたいと思います。そして、これから少子高齢化社会ですから、老老介護という言葉がありますけれども、そういうことで、これから元気な高齢者が高齢者を見ていく時代が近い将来やってくるかと思います。このように、元気な高齢者の力を再活用すべきと思いますけれども、その点におきまして、区の考えを聞かせていただきたいと思います。","respondent":"大串福祉計画課長","answer":"地域支援員、今現在３３１の方が登録をいただいているです。現状では、こういった支援員、ボランティアのお力をお借りして、例えば、簡易なお手伝いですとか、あるいは、居場所づくりといったところで、フリースペースといったものを展開している地区もあります。","voiceIndex":150,"id":"exchange-057"},{"speaker":"木村委員","kind":"質問","question":"その高齢者の力を活用したいということでありますけれども、次回、募集人員といいますか、そういうものをするときに、高齢者の方々の力、こういう募集というのを先にやってみてはいかがかなと思いますけれども、そのような課題はあるかどうか、先に募集してみるというのもどうでしょうか。","respondent":"大串福祉計画課長","answer":"特に、年齢層を絞った形で募集ということではなくても、やはり自然とこういう年齢層の方がボランティアとしてお力を貸していただいているというのが現状ですし、これからもそういった方のお力はぜひお借りしていきたいというふうに考えているところです。","voiceIndex":152,"id":"exchange-058"},{"speaker":"木村委員","kind":"質問・要望","question":"多少の妥協がきくということですよね。次に、２１９ページの中ごろにありますけれども、高齢者社会参加促進事業からの質問です。これは、高齢者の作品、グラウンド・ゴルフ、高齢者輪投げ、シルバーダンス、いきいき健康マージャン、そして、いきいきカラオケ、この６事業のことですけれども、この事業は、人数的には今現在は増え続けているのかどうか、お聞かせをいただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者社会参加促進支援事業ということで、参加者数の推移についてお尋ねをいただきました。おおむね、もともとこの事業の対象となる高齢者の方の人口が増えているということもありまして、相対的に見ますと、微増傾向にあるというふうに捉えております。","voiceIndex":156,"id":"exchange-059"},{"speaker":"木村委員","kind":"質問","question":"いきいきカラオケなどで高齢者の中から、大変おもしろいキャラを持ったりしている方、そして、また、歌のすごく上手な人たちがいて、そういうグループができた場合、注目されてテレビに出たり、また、このＣＤデビューをするような、まるで夢のようなことが起きることだってあるとも思うのですけれども、そうなれば、今より夢が広がり、区内の高齢者に夢、希望が持てるかもしれませんけれども。","respondent":"宮尾高齢者地域支援課長","answer":"これからも引き続き、こういった事業の充実に努めてまいりたいというふうに思います。","voiceIndex":158,"id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"ますますこの少子高齢社会へと移行する日本ですけれども、高齢者の生きがいと健康づくり推進のために、地域を基盤とする高齢者の自主的な活動組織である老人クラブ等や、また、都道府県、及び、市町村が行う地域の高齢者の社会参加活動を支援すると紹介されておりますけれども、高齢社会に突入したこの日本、ますますこの先の事業が大変大事になってくると思いますけれども、家に閉じこもらずに。","respondent":"宮尾高齢者地域支援課長","answer":"１人ではなく、２人、３人、そして、もっと多くのグループで、そういった目的が大きなベースとしています。高齢者クラブの皆様方の活動を支援をさせていただいているというのも、そういった大きな考え方のもとにやらせていただいております。","voiceIndex":160,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に高齢化社会、ますますこれからもっともっと高齢者が増えていくわけでありますから、ぜひその点、またお願いをしたいと思います。そして、いきいき健康マージャンのこの予算が一番高くて、２００万余という高い予算ですけれども、大変この参加数が多いと解釈できると思うのですけれども、今のところ、健康マージャンに対する区民の関心度というもの、それをお聞かせいただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"これから、３１年度に向けても、こうしたことも踏まえまして、コースも１つ、１コースではありますが、増やさせていただこうというふうに考えてあります。今後も事業者と連携を図りながら、充実を図ってまいりたいというふうに考えております。","voiceIndex":162,"id":"exchange-062"},{"speaker":"木村委員","kind":"意見","question":"この健康マージャン、あくまでも健康マージャンでありますけれども、陰でお金をかけてやっているようなことというのは事例があるかどうか、お聞かせください。","respondent":"宮尾高齢者地域支援課長","answer":"こちらはあくまでも大前提としてかけない、飲まない、吸わないということをモットーにやらせていただいておりますので、そういったことはないというふうに認識しております。","voiceIndex":164,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問","question":"２４５ページの南ゆたか保育園の改築、２２１ページの高齢者住宅運営費について伺います。そういった中で、園庭がなくなるというお話を伺いました。建て直した後、園庭はあるのか、ある場合は、面積と現在の園庭の面積を伺います。あわせて、建替え後、プールがあるのかも伺います。建て直しに当たり、子どもや保護者、職員、周辺住民への説明はいつ行ってきたのか、図面が示されたのはいつなのか伺います。","respondent":"吉田保育施設調整担当課長","answer":"説明会につきましては、昨年の１２月１４日、旧杜松小学校で説明会のほうは実施しております。近隣の参加者は１８名参加しております。図面についても、その日に来た方に対してお示ししています。プールにつきましては、建替え後も、プールは園庭のほうにあります。","voiceIndex":167,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"説明会のほうなのですが、この保護者や職員、周辺住民、それぞれいつ行われたのかということでお聞きしましたので、そこをお答えいただければと思います。","respondent":"吉田保育施設調整担当課長","answer":"保護者につきましては、建替えの説明は２９年５月に行っております。それから、地元への説明につきましては、先ほど申し上げました３０年の１２月１４日に実施しております。職員への説明も、保護者の説明と同時期にやっております。","voiceIndex":169,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"図面が示されたのも同じ日だということでよろしいでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"実施設計の図面を地元に示したのは１２月１４日です。","voiceIndex":171,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"南ゆたか保育園には、親しまれている桜の木があります。この木が切られるというのは悲しいという声も挙がっておりますけれども、この桜の木はどうなるのか、残すべきではないかと思いますが、伺います。こういったことを含め、計画段階から、利用者の意見を聞いて反映させるように求めますが、いかがでしょうか。園庭で子どもたちは楽しく遊んでいます。園庭を狭めるべきではないと思いますが、伺います。","respondent":"吉田保育施設調整担当課長","answer":"ちょうど真ん中にあるので、工事をするにも、申しわけないですけれども、動かさないと工事もできない。それから、動かすにも、４ｍほどの根っこがあると、園内でほかの場所に動かすこともちょっとできないということで、今回は、残念ながら、桜の木については伐採をいたします。","voiceIndex":173,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は園庭が必要だと認識していると答弁を、この間、ありますので、それならば、園庭のある認可保育園を造設していくことこそ必要だと思いますが、いかがでしょうか。今後、南ゆたか保育園のように改築する区立園は園庭が削られてしまうのか、伺います。今後、改築が必要な区立園は何園あるのか、伺います。","respondent":"吉田保育施設調整担当課長","answer":"狭くなるという内容は、先ほどご説明した内容でありますけれども、大体今、建替えを始めている施設につきましては、５０年程度経っているものなのですけれども、５０年前のもの、今のその基準値、そちらを比較しますと、広げなければならないところが多くなりまして、その分。","voiceIndex":175,"id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"南大井とか、先ほどつる委員とかもあると言っていましたけど、北品川にもありますけど、そういうものがいいのかどうかも含めて、空き家というお話もありましたけれども、これはぜひ、所管課として研究を、というよりも、検討をぜひ進めていただきたいと思いますが、支援のあり方も含めて、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"ただ、午前中からの質疑もございましたように、時代が変わり、今は傾向も変わる中で、新しい居場所のあり方ということでご提案をいただいておりますので、これまでの児童センターのような、これも自由に出入りができるのですけれども。","voiceIndex":178,"id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それはわかっていて、課長もご答弁されていると思うのですが、新しい形のもの、先ほど２３区、ないとおっしゃっていました。多分ないのだと思います。ですから、どういうふうなことを構築していけばいいのかということにしっかり耳を傾けていただいて、構築していただきたい。認知症高齢者支援事業で、認知症のことで、先ほど午前中、芹澤委員から、私も聞こうと思っていたことの確認がありました。","respondent":"寺嶋高齢者福祉課長","answer":"品川区のほうで把握している数字としましては、アイテムによる通報、それから、ＧＰＳによる発見といった、こういった数字のみを把握しておりますので、数としては、毎年１桁台という数になっておりますが、実際には、近隣の方が見つけてすぐにご自宅まで届けていただいたとか。","voiceIndex":180,"id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問","question":"ほかの自治体で、例えば神奈川県の大和市とか、幾つかのところでも既にそういう加入をしているというところがあるのですけれども、都内ではこの２区が初だということなのですけれども、こういうことも公費を投入をして備えていくということも、認知症になっても、安心をして町の中を歩けるということから、やはり必要になってくるのではないかと思うのですが、その辺についての見解を伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"保険に関しましては、我々のほうも、情報収集、研究等を既に進めておりまして、大変興味のある内容だというふうに認識しております。","voiceIndex":182,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、歳入に引き続いて、しあわせ食卓事業について、ちょっとできなかった分をお伺いしたいと思います。まとめて質問してしまいますが、今回、私どももこの事業については、ぜひ実現をということで求めてまいったのですが、この３カ月で全て終了ということなのか、それとも、このクラウドファンディングについては、どういうふうな継続性を持たせていくのか、お伺いをしたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"今後の展開なのですけれども、子ども食堂の支援については軌道に乗ってきたところですが、食の支援の展開について、フードバンクとタイアップしてやる事業は本当に小さい事業ですので、今後、子どもの居場所であったり、食の支援をするための拠点であったりとか。","voiceIndex":184,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"最後に、高齢者お祝い事業、長寿祝い品のところで、今までは８０歳から祝い品というものが配られていましたけれども、今、ホームページを見ると、全部消えていて、今後の展開については平成３１年３月下旬に掲載予定ですとなっています。全国的にこのいわゆる祝い金を廃止とか、削減とかという方向で報道もあるのですが、品川区に関して、これがどういう方向性なのか、お聞きしたい。","respondent":"大串福祉計画課長","answer":"今般、８０歳の方に対して、これまで３,０００円の記念品を区のほうでお渡しをしていたのですけれども、これについては、平均寿命も８０歳を超えてもう数年経っているといったところで、このいわゆる傘寿といったところについては廃止をさせていただき、それ以降の米寿、卒寿。","voiceIndex":186,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"確認","question":"何でこんな質問を唐突にしたかというと、問い合わせがあって、区のほうに問い合わせをした８０歳になったばかりの方が、どうなるかわからないというご回答をいただいたので、私も確認させてもらったのですが、この方、８０歳になったばかりなのですよ。９月１６日になった方はまだもらってないです。この方の救済を何とかお願いできないかということで、お願いしたいと思うのですが、いかがですか。","respondent":"大串福祉計画課長","answer":"経過措置といったところですが、その辺、いつの時点をとっても、どうしてもやはり公平、不公平、この日までだったら、もらえたのにというお声がどうしても挙がってきてしまう。こういったところでは、今回、廃止という形をとらせていただきたいと思います。","voiceIndex":188,"id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、ページ２３５、子育て支援事業から、しながわネウボラネットワーク事業と、ページ２５１、各種児童保育委託から、病児保育について、お尋ねいたします。品川区の子育て支援事業についてお伺いいたします。昨年１２月８日に成育基本法が参議院本会議で可決成立しました。この成育基本法について区のご理解をお示しください。","respondent":"高山子ども育成課長","answer":"公布日から１年を超えない範囲内で政令で定める日で施行ということとなってまいりますと、今後なのですけれども、成育医療等基本方針でありますとか、あるいは、厚生労働省において、成育医療等協議会などを設置というふうに伺っておりますので、こうした中で。","voiceIndex":191,"id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"意見","question":"まさにネウボラの理念そのままの法律です。全員に定期的に、直接会わないで、どうやってハイリスクの家庭を見つけることができるのかと話されたといいます。成育基本法は、これから具体的な施策の検討が、今、課長がお話になったように、進められていくと思いますが、品川区で現在行われている切れ目のない子育て支援事業にどのように生かしていこうとしているのか、現在の区のお考えを一言お聞かせください。","respondent":"高山子ども育成課長","answer":"委員ご紹介のように、児童の虐待の早期発見、早期対応、そういうのがもちろん重要なことであるのですが、その予防の観点ということで、発生予防というのが大変重要となってまいると考えております。","voiceIndex":193,"id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"期待しております。次に、病児保育についてお尋ねいたします。２０１９年４月に、中延、上大崎に新しく病児保育所が２カ所開設し、品川区の病児保育所は計４カ所になります。現在の病児保育所の整備の状況、２０１８年度の利用の実績についてご説明をいただきたいと思います。","respondent":"佐藤保育課長","answer":"実績ですが、２月末までの状況で、武蔵小山のサンタハウスこどもクリニックが約１,０００件で、利用率が５０％ぐらいですね。南大井のおおしまこどもクリニックは、１１月からの４カ月間で約２００件ですので、利用率は大体３０％ぐらいです。","voiceIndex":195,"id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"まだ十分ではありませんが、各地区に病児保育所が点在し、利用希望者が病児保育を利用できる体制が整ってきたことを高く評価したいと思います。現在の病児保育に対する区の評価、もしもあるのならば、利用者の評価についても一言ご報告をお願いしたいと思います。今後の病児保育所の増設計画、その見通しについてご説明をいただきたい。","respondent":"佐藤保育課長","answer":"今後の増設計画ですが、一応、計画上の数値は達成したのですけれども、今後も増える見込みがあると考えていますので、また、地域バランスを考えて適切に、増設に向けて頑張っていきたいと考えています。","voiceIndex":197,"id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"感染症児の扱いです。しかし、インフルエンザ感染症は飛沫感染であり、麻しんや風しん、水痘と異なり、２ｍ以上離れれば、感染することはありません。都内全ての病児保育施設には、最低限の安全の担保として、全国病児保育協議会に加盟し、全国の病児保育事業総合保険に加入することを義務づけるべきだと考えますが、区のお考えはいかがでしょうか。","respondent":"佐藤保育課長","answer":"定期的に研修や講演会を行い、また、機関紙の発行などをしております。病児保育の児童を管理するシステムを提供するということも聞いておりますので、これに関しても、既にやっている事業者のほうに働きかけてまいりたいと思っています。","voiceIndex":199,"id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"東京都２３区では、練馬区、大田区に医師会が関与する病児保育所が存在しています。川崎市では、病児保育のニーズが高まり、２０１３年に市内７つの行政区の全てに病児・病後児保育所を整備することにしました。品川区も、荏原医師会の協力で病児保育室を立ち上げましたが、医師会との協力については、今後どのようにお考えなのでしょうか。","respondent":"佐藤保育課長","answer":"中延に今回整備いたしました保育所併設型の病児保育施設は、荏原医師会の多大な協力があったから実現できたと認識をしております。夏前から、月に１回以上、事務レベルでは週に１回以上、多いときは打合せをさせていただきましたので、非常に感謝をしております。","voiceIndex":201,"id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育は、１９６６年に、世田谷区に保育園内に共済会方式で、１９６９年に大阪枚方市に医療機関併設型の地域センター方式で開設されたのが嚆矢です。２０００年ごろから、乳幼児健康支援一時預かり医療として、保育園児を対象とした母親の就労支援のための市町村補助事業となりました。病児保育の位置づけに関しての現在の品川区のご見解を伺いします。","respondent":"佐藤保育課長","answer":"病児保育を子育て支援として考える件ですが、区としては、病気のときはご家庭で見ていただくことを基本と考えておりましたが、先ほどご紹介のありました成育基本法、また、子ども・子育て支援事業計画については、もう既に子育て支援事業に位置づけられておりますので。","voiceIndex":203,"id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区の病児保育の今後の事業展開に当たり、幾つか区にお考えを伺います。品川区の保育所には他区の区民も通園されています。このような他区の区民が、現在は病児保育の対象外にされておりますが、このような園児にも病児保育の利用に門戸を開くべきと考えますか。区のお考えはいかがでしょうか。","respondent":"佐藤保育課長","answer":"都の補助金上は、都民であれば補助金をもらえるという要綱になっておりますので、区民と区民ではない方と利用料はある程度差をつけて、受け入れのほうはやっていきたいかなというふうに考えているところであります。","voiceIndex":205,"id":"exchange-082"},{"speaker":"鈴木（博）委員","kind":"質問","question":"病児保育は、親の就労支援という保護者の視点からだけではなく、病気の子どもが、医師、看護師、保育士などの専門家集団によって、病気であるがゆえに、より十分に安静と療養ができる環境を保障するという動きです。もちろん保護者が子どもの病気のときに、看護休暇をとれるような社会的な整備も並行して推し進めなければなりません。さらに、病児保育が、品川区で発展することを希望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"確認","question":"先日の補正予算のときに、区内のグループホーム利用者を伺ったとき、９８人とおっしゃって、そうすると、グループホームを利用する区民は、それをあわせた数、２６２人でいいのかという確認、あと、就労Ｂも同様に、区外が８３人、区内が２８５人という答弁で、あわせて、就労Ｂを使用する、利用する区民は３６８人でいいのか、確認をお願いします。","respondent":"松山障害者福祉課長","answer":"区内、区外、両方とも重複してご利用いただいている方もいらっしゃるということなので、正確な人数というのはちょっと難しいところです。","voiceIndex":209,"id":"exchange-084"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、月最大で２３日利用できるということで支給基準が変わったと思うのです。放課後等デイサービスは、先ほどもこの計画から見ても、区内には足りていない状況なのではないかと思いますし、これを需要と供給のところで、その支給基準も変わったところで、どのようにこの需要を予測しているのか、そして、どうしていこうと考えているかということを伺います。","respondent":"松山障害者福祉課長","answer":"４月開設が１カ所、６月ごろの開設が２カ所ということで、こちらのほうはかなり明確な事業所かと考えています。未定だけれども、事業所をつくりたいですというご相談もいただいておりますので、民間が、区のほうで何か助成をしなくても、民間のほうが参入してくる状況です。","voiceIndex":211,"id":"exchange-085"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、まず、この近隣区というのがどこなのかを伺いたいのと、あと、この質の確保というところでは、大田区では、放課後等デイサービスが３４カ所、多くあるということで、質の確保や点検のために、第三者評価受審状況や、体制整備チェックリストの提出などが事業所に求められているということです。区としては、この質の確保をどのようにしていこうと考えているのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"放課後等デイサービスの連絡会ですけれども、今年度２回目を開催しております。国の情報を皆で共有し、また、福祉カレッジの子ども支援研修が３月２０日と２１日で予定をしておりますので、そちらのほうにぜひ参加していただくよう、事業者にも案内をしております。","voiceIndex":213,"id":"exchange-086"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２４５ページ、区立保育園費の中の特別支援保育、区立保育園の特別支援、巡回相談などに関してお尋ねします。その縮小した理由を伺いたいということ、それから、１年間行ったという、そういった期間でこういった政策的な経費がこうやって縮小していくということについてのお考えを伺います。","respondent":"佐藤保育課長","answer":"ただ、金額的に、４５８万２,０００円ほど減になっておりますのは、昨年度、医療的ケア児の受け入れに関して、保育施設の工事費が大分入っていたものと、あと、特別支援保育というところで、去年は保育園運営費に大分まとめて計上していたのですが、今回、幼稚園とか。","voiceIndex":216,"id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、区立保育園にお話を限定させていただいて、そこに学校心理士の方が３０年度は行かれていた。それと、臨床心理士の方が行かれていたのですが、３１年度は臨床心理士の方の訪問だけになった。そして、幼保一体施設の保育園部門に関しても、同様な形になったという認識を私はしたのですが、いかがですか。","respondent":"佐藤保育課長","answer":"予算の細かいところですが、そこは委員ご指摘のとおりで、適切に、役割分担に基づいて、各施設に応じて、４歳、５歳に伸びる場合もありますので、そういうふうに配置を変えたです。","voiceIndex":218,"id":"exchange-088"},{"speaker":"高橋（し）委員","kind":"提案","question":"そこから、保護者の方へのいろいろな相談も乗れたということがあるわけです。ということで、公立保育園の今言った学校心理士によるその巡回相談を、配置がえで、ほかのところに行かれているのは存じ上げております、公立の公設民営の保育園や区立幼稚園に、それは存じ上げているのですが、改めて、もう一度、区立保育園のほうの年長のそういった就学相談を行わなくしてしまった理由をお伺いします。","respondent":"佐藤保育課長","answer":"委員ご指摘のとおり、３１年度、再配置をしまして、公立保育園に対する学校心理士のほうは縮小したところですが、これまで、学校心理士による巡回相談と保育課本課において、保育教育担当という組織を新しくつくって、園長ＯＢ等も配置しておりますので、その辺、十分ノウハウが。","voiceIndex":220,"id":"exchange-089"},{"speaker":"高橋（し）委員","kind":"質問","question":"それについてはどのように考え、今後の保育士たちへのそういった支援、そして、ひいては、お子さんへの支援になるわけですけれども、先ほどもお話ししましたけれども、学校心理士は臨床心理士とは違った形での相談をしているわけですので、そこの部分がなくなってしまうことに関して、そのサポート体制をどのようにしていくのかということをお伺いします。","respondent":"佐藤保育課長","answer":"その辺のサポート体制に関しましては、答弁が重なる部分があって申しわけないですけれども、保育課本課のほうで保育教育担当というのを設置しておりまして、園長ＯＢ、また、幼稚園長ＯＢも配置するようなところで動いているところもありますし。","voiceIndex":222,"id":"exchange-090"},{"speaker":"高橋（し）委員","kind":"質問","question":"それをわずか１年の中で非常に貴重にそれを浸透していただいたのですが、それが来年全くなくなってしまうというところ、本課にあると言いましても、保育園を巡回して指導するのとは全く質が違うかと思います。このような流れについて、どのようにお考えになっているでしょうか。","respondent":"佐藤保育課長","answer":"今年度、保育所保育指針の改訂、教育要領等の改訂を踏まえまして、「のびのび育つしながわっこ」の改訂を行っております。今後、また、教育委員会と緊密に連携をとって進めていきたいと考えております。","voiceIndex":224,"id":"exchange-091"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これはもうテレビ、ラジオ、新聞などマスコミが８８％、次に多いのがインターネットによる検索、あと、友人、知人が３０％とあって、これ、ご本人ですから、ごく普通の健康な状態の方が多いかと思うのですが、情報を得るときに、行政だとか、あるいは、地域包括支援センターとかが認定後にはぐっと伸びるのですね、これが４０％、５０％。そして、３番目に多いのがどこに相談すればよいのか。","respondent":"宮尾高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"ただ、実際に、こちらの事業に参加いただいている方は圧倒的に女性の方が多くあります。裏を返せば、それは男性の方がまだまだこの事業を含めて、外出に向けて余地があるのかなというところは認識として持っているところです。あとは、イベント的なものということでは、認知症講演会というものを開いておりますけれども、本年度は、テレビにも出演されている著明な方にご講演をいただいたこともありまして。","voiceIndex":227,"id":"exchange-092"},{"speaker":"渡辺委員","kind":"意見","question":"それは今や、それぞれの分野ではキャンペーンなり実施されていますが、やはり区内一斉的なもの、これ、よく防災の関心がこれまで上がったのはいろいろな要素があると思いますが、一斉なキャンペーン、これは例えば町会高齢者クラブ、あるいは、商店街、関係する理解がされやすいところを同時に行うとか、連携したものを強めるという意味で、特に認知症サポーターの募集を含めて、今後、ホップ、ステップ。","respondent":"寺嶋高齢者福祉課長","answer":"今ご紹介いただきました認知症サポーター養成ということにつきましては、通算で１万５,０００名以上の方に既に講座を受講していただいておりまして、まさに地域の力で支えていくというところについては取り組んできたところで、これからも力を入れて取り組んでいく予定です。","voiceIndex":230,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補装具の中の白杖、盲人安全つえ、歳入の続きでちょっとお聞きしたいのですけど、本当に白杖が壊れてしまうということがよくあることだということで、歳入でもお聞きしたのですけど、社会福祉協議会から、白杖が公布されて５年経たないで破損した場合は、補装具として給付されるということを伺いました。２９年度で結構ですので、教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"１点目です。補装具で白杖の給付をしている方の２９年度の本数ですけれども、７本です。","voiceIndex":233,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこはちょっとそういうふうなところがきちんと支給されるような形での整備をお願いしたいなというふうに思います。５年も経過しなければ、交付しないというふうなことになっていないのか、公布されるのか、５年というふうなことでしおりにも書かれているのですけど、そこの理由もあわせて伺います。","respondent":"松山障害者福祉課長","answer":"最終的には、５年経たずに交付されるのかですけれども、原則は、その寄附も入っているということで、再支給ということはお渡しすることはできませんが、ただし、つえなしでやはり日常生活、お困りの方につきましては、直ちに支給しております。","voiceIndex":235,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なぜこういうふうに繰り返してお聞きするかというと、結構、５年経たないともらえませんというか、そういうふうに言われたという方がすごくいろいろ聞くのです。全額自己負担でなければ、補装具の場合も、それから、白杖の地域生活支援事業のその社会福祉協議会でやっているものも、５年経たなければもらえませんよということはありませんという、そういうことで確認をさせていただいていいでしょうか。","respondent":"松山障害者福祉課長","answer":"社会福祉協議会については、先ほど申し上げたとおり、無料で差し上げているです。いずれにしましても、お困りの方、状況に応じてということで、窓口では徹底してまいります。","voiceIndex":237,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２月が締め切りだったと思うのですけど、申請者が何人いたのか、伺います。それから、昨年２月に締め切った方がどれぐらい入れたのかということで伺いたいのですけれども、昨年２月、締め切りの方が、平成３０年、去年の４月１日から８月３１日までに特養ホームに入れた方の年齢別要介護度別の内訳、それから、在宅、施設別の人数、男女別の人数について教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長、大串福祉計画課長","answer":"３月に入所調整会議を予定しております特養の申請は２月末日、９月１日から２月末日の受付をしたところですが、現在、最終の集計作業をしておりまして、重複、それから、取り下げ等の作業がありますので。プラス、開設の整備費ということで、これは単価が６２万１,０００円掛ける定員数といったところです。今申し上げたものを足し込んでいきますと、約、補助金としては９億３,０００万ほどが東京都から来るです。","voiceIndex":239,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の数字を聞いて、本当に深刻な状況だなと。こういう状況に対して、今でもやはり老健施設と特養ホームの整備率は２３区で最下位という、そういう中で、私はこの改善させるための計画を持つべきだと思うのですけれども、その計画を、先日の厚生委員会の中でも、施設だけを取り出して計画することは考えていないということだったのですが、特養ホームの施設増設の計画は立てないということなのでしょうか。","respondent":"大串福祉計画課長","answer":"特養だけではなく、認知症のグループホーム、あるいは、小規模多機能型居宅介護、こういったさまざまな施設、こういったものも含めて、なおかつ、ソフトの支援、これも含めた形で、品川区の高齢者福祉の向上を図っていきたいと、このように考えているところです。","voiceIndex":242,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もちろん、グループホーム、小規模多機能、こういう施設もどんどん増やしていただきたいと思います。でも、深刻なのはやはり特養ホームがこれだけ、５００人も待っているという。そういう状況の中で、この計画を本当につくらないと、これから高齢者がどんどん増えるという中で、ぜひ計画を立てて増設をしていただきたいということを強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"こういった相談体制、大変に重要でいろいろ適宜適切な体制というのが敷かれていくべきというふうに私も思っておりますが、特にちょっとご相談というか、伺っているのは、身体障害と、精神障害を両方お持ちの方の相談なのですけれども、これは多分、昔からこの課題というのはずっとあって、長くいろいろ検討というか、考えてこられているところだと思うのですけれども、まず、この身体、精神。","respondent":"松山障害者福祉課長","answer":"障害者福祉課に来られた場合であっても、保健センターの医療保健的なノウハウが必要な場合は、チームで一緒にかかわってサポートして相談を受けております。","voiceIndex":247,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"障害者福祉課がとりあえずこの両方の障害を持っていらっしゃるのであれば、受けますよと。保健センターにかかわることであれば、それは障害者福祉課の中で連携していく。相談自体は、もう障害者福祉課の窓口一本で結構ですと、こういうような形というのは、ぜひ検討していただけないのかなというふうに思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"そういった面では、例えば地域の拠点相談支援センターもありますし、あるいは、そこに出張して、例えば保健センターに出向いて、こちらの職員がお伺いするという場合もありますので、そういったことは保健センターと相談しながら。","voiceIndex":249,"id":"exchange-101"},{"speaker":"塚本委員","kind":"質問・要望","question":"２２９ページの医療短期入所事業なのですけれども、最初にお伺いしたいのは、私も調べ切れなかったのですけど、この事業というのは、医療的ケアつきの短期入所、ショートステイ、このことというふうに捉えてよいのかということで最初に確認させてください。","respondent":"松山障害者福祉課長","answer":"委員のご指摘のとおりです。","voiceIndex":251,"id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"この質問がこのまま進められるわけなのですけれども、平成３０年度は１６２万の予算でございましたけれども、今年は８２万ということで、ほぼ半減になっておりますが、この減額の理由、また、実績等が、今年度、どうだったのかというところをお伺いいたします。","respondent":"松山障害者福祉課長","answer":"そのため、実績としてはございませんでしたが、区といたしましては、やはり在宅で生活する医療依存度が高い障害児者、通常のショートではやはり利用が難しい方にとって必要な事業だと考えています。","voiceIndex":253,"id":"exchange-103"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここのいわゆる医療ケアつきの短期入所というのは、私も長年、いろいろなところで実現に向けて、大変にこの要望が障害者の方から、特にご家族の方から多いので、区としてもいろいろこの間、検討されて、一つの回答の形として、この病院でベッドを使ってというところで始めていただいたというところで、大変に期待をしたというか、評価をしていたのですけれども。","respondent":"松山障害者福祉課長","answer":"今年度ですけれども、やはりどなたでも受け入れてくださいということですと、病院側はどうしてもお困りになると考えていますので、できる方、どういう方だったらまずは受け入れてくださるのかというところで、できるところからまずは始めていきたいと考えています。","voiceIndex":255,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"この三つの分野それぞれにおいて、現状の介護ロボット導入の実績で非常にうまくいっているというか、導入の結果、非常に業務改善ができたみたいな話とか、介護の受けている人がものすごく自立につながったと、こんな話とかがあれば、ご紹介いただきたいのと、全体を通して、この介護ロボット導入の評価、どのように今、されているか、お伺いしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"委員ご紹介の自立指導支援、それから、コミュニケーション等の機器についてはまだテストをした実績がないものですから、こういったあたりも引き続き検討はしていきたいのですけれども、今一番注目しているのは、やはり職員の負担軽減につながるような、例えば自走式の車椅子。","voiceIndex":257,"id":"exchange-105"},{"speaker":"塚本委員","kind":"意見","question":"価格の問題とかも結構あるみたいで、そういったところの費用対効果、最大限に発揮できるような形で、この導入というのはやはり、うまくいけば、効果あると思いますので、よろしくお願いをしたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-106"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問に入る前に、すみません、再開当初、空席が目立ちまして、理事者の皆様は４０分にきちんと来られたのにもかかわらず、こちらのほうは大分空席が目立っておりましたことをおわび申し上げたいと思います。質問をします。２０２５年、団塊の世代の方たちが７５歳以上になる。","respondent":"寺嶋高齢者福祉課長","answer":"今、委員からご指摘いただいたとおり、かつて団塊の世代が６０歳、６５歳とよく言っていた頃の一番の課題としてはまさに地域デビューということで、元気な高齢者の方にどういった形で活躍をしていただくか、こういったことが課題であったのだろうと考えております。","voiceIndex":261,"id":"exchange-107"},{"speaker":"大沢委員","kind":"質問","question":"地域包括ケアということでお話、単語が出たかと思いますけれども、これはやはり、経費を、高齢者の方のボリュームゾーンが７５歳以上になると、経費を抑えるがための地域包括ケアという施策、事業だというのはもう皆さん、十分ご存じかと思いますけれども、そこの中で、やはり地域で見守る、在宅ですので、そこらのところで、看護師や医師の数については、何か将来的には医者不足などという情報も私。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-108"},{"speaker":"大沢委員","kind":"質問","question":"なければいい、なければ。財政的に確かに品川区は豊かだという、行政当局の努力によって豊かだということなのですけれども、何せボリュームゾーンが多いと、人口が非常に多い団塊の世代ですから、そこのところはいろいろなものをはかり、てんびんにかけながら、財政を運んでいくのだと思うのですけれども、そこは本当に大丈夫なのですかね。","respondent":"寺嶋高齢者福祉課長","answer":"あとは、先ほど医療の件につきましては、例えば看護、小規模多機能といった地域密着型の施設の整備等も進めていくことで、在宅医療も含めた対応をできればというふうに考えております。","voiceIndex":265,"id":"exchange-109"},{"speaker":"大沢委員","kind":"質問","question":"先ほどのどなたかの質疑の中で、特養の整備をして、高齢者の施設の整備を今、着々と進めているのですけれども、今のペースで、団塊の世代の方が本当に必要とされるときに、数、どのような見通し、足りるのか、おそらく足りなくなってしまうのではないか、とにかく多いですから、そこらあたり、どういうふうにお考え、見積もっていらっしゃるのですか。","respondent":"大串福祉計画課長","answer":"施設の整備、これも大切なことだというふうに認識しております。そうした中で、特養であったり、先ほど来申し上げましたが、グループホームであったり、小規模多機能、看護小規模多機能、こういった施設の整備、これも進めているところです。","voiceIndex":267,"id":"exchange-110"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域包括ケア、先ほどちょっとお話で、医師と看護師が足りないというお話は、それは全然款が違うことで話はしませんけれども、この地域包括ケアの中で、要はその３師会がありますけれども、医師、歯科医師、あるいは、薬剤師、ここら辺の役割分担というのはどのような形になっているのでしょうか。","respondent":"大串福祉計画課長","answer":"今おっしゃっていただいたように、医師会、歯科医師会、あるいは、薬剤師会、こういった３師会の皆様方とも連携しながら、地域包括ケアという切り口の中でいけば、医療と介護の連携ですとか、そういったところが今後とも求められていきますし、より一層。","voiceIndex":269,"id":"exchange-111"},{"speaker":"大沢委員","kind":"質問","question":"高齢者クラブの中で、団塊の世代の方はどうしても皆さん、意識が強いというか、どちらかというと、ローンウルフのような一匹狼的な方が多いとは思うのですけど、高齢者クラブに関して、団塊の世代の方はどれぐらい加入、加入率というか、２０２５年ではなくて結構ですから、現状、どのような感じになっているか、教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者クラブの在籍しているといった年齢ですが、全会員の方を対象にというデータを持ち合わせていないのですが、参考までに、高齢者クラブの会長さん方の平均年齢というところでいきますと、平成３０年の４月時点というデータになりますが。","voiceIndex":271,"id":"exchange-112"},{"speaker":"いながわ委員","kind":"質問","question":"私、２１９ページ、高齢者クラブ支援事業で、それで、次は、２３７ページから始まるすまいるスクールについてお伺いしていきます。私は高齢者クラブの位置づけというのが、健康増進、介護予防、認知症予防などをしっかりと実践している団体であると私は考えております。所管として、どういうお考えで、高齢者クラブを支援しているのかという点、あとは、位置づけだとか理由を教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"これだけではやはり効果というのはなかなか出てきにくいのかなというところで、高齢者の方たちが、クラブというところでたくさんのお知り合いをつくっていただいて、交流を図っていただいて。","voiceIndex":274,"id":"exchange-113"},{"speaker":"いながわ委員","kind":"質問","question":"これ、増やすためには、どうあるべきか、品川区がどう考えているのか。やはり高齢者クラブというその名称をまず変えて、こういう事業的な名前には高齢者とかつけてもいいのかもしれないですけど、対外的に皆様が外で活躍できる場としての高齢者クラブは、やはりこの名前を変えて、新たな品川区における高齢者クラブをつくる、名称を変えたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"名称につきましては、これからは老人クラブから高齢者クラブに変わった経緯等々なども丁寧にお調べさせていただいて、また、連合会の役員の皆様はじめ、会長の皆様方と意見交換をさせていただきながら、丁寧に取り組んでまいりたいというふうに考えてあります。","voiceIndex":276,"id":"exchange-114"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、多分、高齢者クラブというのは、人数掛ける幾らでたしか算出されていると思うので、もちろん人数がどんどん減るということは、各クラブの会員が減っているわけですから、多分、補助金も少なくなってくるわけですから、その辺はしっかりと独自性のある活動ができるように、あり余る支援を、支援というのは、要するに、現金という言い方はおかしいですけど。","respondent":"宮尾高齢者地域支援課長","answer":"委員ご指摘のいろいろな団体に対する支援ですが、こちらも高齢者クラブ等の活動と同様に、大切な活動であることに間違いはございませんので、こういったところも引き続きしっかりと検討してまいりたいというふうに。","voiceIndex":278,"id":"exchange-115"},{"speaker":"いながわ委員","kind":"質問","question":"お願いします。すまいるスクール、本当にありがとうあります。感謝をするぐらい、すばらしい、私は事業だと考えています。これ、本当に自分が実体験でわかっていることであります。それで、学校、小学生が行くと、学校帰りにいろいろプリントをもらってきます。このシステム導入の具体的な内容を教えてください。","respondent":"高山子ども育成課長","answer":"こちらにつきましては、主にはすまいるスクールの参加と退出に関する保護者への連絡、それから、先ほど委員がご紹介になったようなペーパー、一部のペーパーレス化ということで、月の参加の状況のスマートフォン等を活用して保護者が紙を利用せずに、スマートフォンでの入力。","voiceIndex":280,"id":"exchange-116"},{"speaker":"いながわ委員","kind":"質問・要望","question":"時代の流れもありますので、ぜひ、そのシステムを導入したときに、汎用性のあるシステムにしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-117"},{"speaker":"吉田委員","kind":"質問・要望","question":"関連していければ、在宅高齢者支援事業、２２３ページ、同じく社会福祉費の障害福祉相談事業について伺います。先に、障害福祉相談事業を伺います。支援相談体制促進事業です。強化とそのための相談支援専門員を増やすことを求めていたので、方向性は賛成です。補正予算がついた後、どんな調査と検討が行われ、委託したコンサルタントから、区にはどのような報告があったのか伺います。","respondent":"松山障害者福祉課長","answer":"そのヒアリング、それから、相談支援センターなどの意見を踏まえまして、さらに、相談支援部会で検討した結果につきまして、３月１５日の地域自立支援協議会の全体会で、委員の皆様にお伝えし、また、そこで協議をしていただく予定になっております。","voiceIndex":284,"id":"exchange-118"},{"speaker":"吉田委員","kind":"確認","question":"それは１２月までは行われていました。今のご答弁だと、３月１５日に地域支援協議会に出されるということだと、予算作成のタイミングとあわせて考えると、この予算立てそのものにはそれが完全に反映されていないというふうに理解してよろしいのでしょうか。そうすると、事業を実施していく過程で、この今の予算立てが修正されていくということの可能性はあるのかどうか、その辺、伺います。","respondent":"松山障害者福祉課長","answer":"まだ一部、全部報告は受けておりませんけれども、意見交換を丁寧に行いながら、３月１５日を迎えるという形になっておりますが、ただ、具体的な方法、あるいは、当事者の意見をできるだけこの仕組みに反映させたいということは区としても考えておりますので。","voiceIndex":286,"id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"ということであれば、いろいろこれからまた当事者の方の声を聞きながら修正されていくというふうに理解をいたします。計画相談のほうだけを、この予算立てでいうと増やしているようになっているのですけど、その点、どうなのか、それから、民間の相談支援事業所の誘致のほうにぜひ力を入れてほしいのですけれども、具体的にはどのように誘致していくのか、お考えがあったら教えてください。","respondent":"松山障害者福祉課長","answer":"その一般的な本来の役割を果たすために、計画相談を増やしていかなければならないと考えています。２点目の民間相談支援事業所の誘致につきましては、今後という形をとらせていただきたいと考えています。","voiceIndex":288,"id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。それを覆すためには、きっちりこれからも当事者の方の意見を聞いて、この今示されている予算、修正すべき点はきっちり修正していただきたいと思います。時間がないので、要望しておきます。どこが簡易なのという、結構な重労働を、行ってみたら求められたと。コーディネーターとして、そういう仕事はきちんと別の制度につなぐべきではないかと思うのですが、その点について見解を伺います。","respondent":"大串福祉計画課長","answer":"このサービス、簡易なお手伝いといったところで、地域の皆様からご要望いただいた方で、地域支援員の方がそちらに入っていく。そういった、何といいますか、ちょっとしたことでの支え、こういったものを求めていたところです。","voiceIndex":290,"id":"exchange-121"},{"speaker":"吉田委員","kind":"質問・要望","question":"その２人という体制についても、ぜひ検討していただきたいのと、先ほどこれからの高齢社会を迎えてということで、支え愛・ほっとステーションをその機能としてということで、その機能の一つであることは認めます。ですので、この支え愛・ほっとステーションはどんどんまた進めていっていただきたいのですけど、そこをカバーをする制度を区には求めたいと思いますが、その点について、経過を教えてください。","respondent":"大串福祉計画課長","answer":"別に、支え愛・ほっとステーションは要支援１、２の受け皿というところで考えているものではございません。あくまでも地域全体、地域包括支援といった中でのシステムの機能ということで考えているものです。","voiceIndex":292,"id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"確認","question":"民生委員の件です。今年の、１１月がたしか改選の時期になると思うのですけど、民生委員、資料を見ていくと、地域住民の身近な相談相手、専門機関へのつなぎ役、高齢者や障害者の安否確認や、医療や介護の悩み、妊娠や子育ての不安、失業や生活困難などの相談に乗る。それから、心身障害者関係で、これは今年の中に、要医療的ケア者受入促進、１,２００万円余、出ています。","respondent":"大串福祉計画課長、松山障害者福祉課長","answer":"各町会長、自治会長のほうからご推薦いただいて、１２月１日に委嘱を行うということです。医ケア児支援連携協議会につきましては、どちらかというと、医療的なケアが必要なお子さんの成長過程の情報共有という協議会です。","voiceIndex":295,"id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"民生委員です。先日、高齢者クラブの会合に行ったときに、コーディネーターも来ていただいて、高齢者のその会合の中で、民生委員も一緒になってお話をしていて、簡単な仕事、ちょっと有料になるけれども、地域のお店に紹介するというようなこともあったので、その辺、よくつなぎをとっていただきたいなと思いますが、その点もお願いしたいと思います。それから、要医療ケア児のことです。","respondent":"大串福祉計画課長、松山障害者福祉課長","answer":"なおかつ、そこから専門機関につなぐというルートも新しくできたというところでは、それも負担軽減の道しるべになっているというふうに考えているところです。平成２８年に、やはり委員ご指摘の対象のお子さんがご相談に見えられて、保育課として、２９年９月に保育園のほうで受け入れていただきました。","voiceIndex":298,"id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"民生委員のほうはうまく連携を取っていただきたいなと思いますので、よろしくお願いします。それ、うまく運営してもらいたいと思うのですが、この区としての負担がなくなっているというところが非常に感じているのですけど、この地域との連携、この施設、愛知県の法人ですから、地域とのつながりがやはり薄いと思いますので、ぜひその辺を区としてつないでいってあげていただきたいなと。","respondent":"大串福祉計画課長、吉田保育施設調整担当課長","answer":"４月１日にできます、グランアークみづほという特別養護老人ホームです。委員まさにおっしゃっていただいているように、区との連携、そういったところ、非常に大きなポイントになってまいります。ＮＰＯの社会福祉法人化における指定管理の変更につきましては、関西の方面の自治体の事例もありまして、保護者、利用者、それから、職員等には丁寧に説明しながら、速やかな移行ができるよう、支援をしてまいります。","voiceIndex":301,"id":"exchange-125"},{"speaker":"鈴木（真）委員","kind":"質問","question":"グランアークみづほは、在宅支援センターともうまくつないでいただいて、先日介護福祉専門学校の卒業式でお会いしたときに、ちょっとお話を伺った中でも、そういう点もこれから必要だなということがありましたので、ぜひ連携のほう、よろしくお願いします。社会福祉法人化した指定管理者の後には、今通っている保護者の方にもうまくその辺の連携をとっていただくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-126"},{"speaker":"南委員","kind":"質問","question":"２４５ページの保育園運営について、園庭で伺います。保育園の園庭は、保育上欠かせない重要な設備です。区も、幼児期の保育、教育にとって、身近に自然に触れられる環境として大切という見解が明らかにされました。改めて、園庭は保育に必要、そういう認識に変わりはないのか、伺います。","respondent":"大澤保育支援課長","answer":"保育園における園庭は、もちろんお子様にとって、身近にあるにこしたことはないという認識ではあります。","voiceIndex":306,"id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"園庭の整備状況についても伺いたいと思います。例えば区立保育園は４７園ありますけれども、そこの中で園庭がある数、ない数、これは何％に当たるのか。私立保育園についても、あるところ、ないところ、何カ所ずつなのか、そして、区立幼稚園、私立の幼稚園についても、その園庭のある、なしについて、箇所数を教えてください。","respondent":"大澤保育支援課長","answer":"公立保育園ですけれども、規定の面積の屋内遊戯場がある園が３９％、必要面積には足りませんが、公園等とあわせて確保しているのが６１％です。","voiceIndex":308,"id":"exchange-128"},{"speaker":"南委員","kind":"質問・要望","question":"区立幼稚園についてはお知らせなかったけど、これも全部あるという確認でいいですよね。事実です。やはり園庭を含む質の確保を求める声が多くあるという、そういう状況は、私が申すまでもなく、区のほうも十分つかんでおられるというふうに思っているのですけれども、こういう区民の声に応える保育行政にするべきだというふうに思っておりますけれども、その点についての認識を改めて伺いたいと思います。","respondent":"吉田保育施設調整担当課長、大澤保育支援課長","answer":"私のほうから、幼稚園の園庭の確保状況についてご説明申し上げます。小学校と併設されている幼稚園に関しましては、小学校と兼用という形で確保されているものというふうに認識されています。なかなか区内で用地が見つからない中ではありますけれども、屋外、屋上、テラスなどに水遊びスペースを整備していただいたり、あと、近隣との関係で、外にはできないけれども、保育室と別に。","voiceIndex":310,"id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"５７６万円です。園庭の代替として、近くに広場や公園があればそこでいいのだという、そういう区の考え方、これを打破していかなければいけないというふうに思いますので、国に向けて撤回、あるいは、財政支援をしっかりつけろという、そういうことも含めて、求めるべきだというふうに思うのですけど、そのあたりも含めて、ご答弁をお願いします。","respondent":"大澤保育支援課長","answer":"財政的な支援というよりは、やはり品川区の中で用地を確保できないということが一番大きな問題でございまして、例えば一般的な８０名定員の保育園ですと、大体施設として５００平米、そこに屋外遊戯場をつくるとなると、２００平米必要になりますので、区内に７００平米。","voiceIndex":313,"id":"exchange-130"},{"speaker":"若林委員","kind":"確認","question":"３テーマ伺います。この不適切である１園についての内容と、その後の改善をお聞きをしたいと思います。続けて、２４５ページ等の特別支援保育についてです。もう一点、こういう方たちとの民生委員のかかわりについても確認をしておきたいと思いますが、こういう転入されてきた方、隣近所、地域、品川区に、当然、お知り合いがいないということで、いわゆる孤立をされやすい方なのかなというふうに思います。","respondent":"佐藤保育課長、大澤保育支援課長、大串福祉計画課長、松山障害者福祉課長","answer":"２点目の公立における食物アレルギーを持った園児への対応ですが、こちらに関しましては、厚生労働省が作成したアレルギー対応ガイドラインに沿って。続きまして、特別支援児の巡回指導の件ですけれども、私立保育園につきましては、３１年度、２０回増やしまして、１００回の枠をとって。転入されてきた高齢者への対応といったところかと思います。民生委員、そういったアプローチも可能かとは思います。私からは、療育支援ネットワークについて、お答えを申し上げます。","voiceIndex":317,"id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"２１２ページ、社会福祉費、福祉計画費に関して質問します。内閣府の主宰である人生１００年時代構想会議というのを勉強しました。ここでは、高齢者雇用についてお伺いします。ですから、当然、この高齢化への方向の一つとして、こういうことも品川区は考えていかないといけないと思うので、品川区の見解と計画をお聞かせをください。","respondent":"宮尾高齢者地域支援課長","answer":"こちらは、高齢者の方に、これからも社会参加の促進の基軸としていただくとともに、価値観、生活様式の多様化、こういったことにも対応していただくために、元気な高齢者の方向けの施策をこれからも推進をしていきたいというふうに考えているところです。","voiceIndex":326,"id":"exchange-132"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その方向性は理解するのですけど、内閣府が求めているのはさらに進んだものだと思うのですよ。１００年時代ということを支えていくためには、まず、元気な方には本当に元気でいただくことが最善だから、だから、高齢者の雇用促進と表現は簡単だけど難しいと思いますよ。どう言ったらいいかな、さらに前に進む思いを込めたことをいただければと思うのですが、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"今まで、ボランティアであるとか社会参加につきましては、これまでも進めてきたところですけれども、やはり介護現場におきましては、人材不足等もうたわれている中で、まだまだお元気な高齢者の方、意欲のある方につきましでは、そういった参入も含めて。","voiceIndex":328,"id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、これもこれからの品川区の福祉の一つの方向性として、介護現場で、ＩＣＴが導入されていくのだけれども、それをどう評価していくのか、また、それを区の施設はもとより、民間事業者に対する対応、それから、計画的にＩＣＴ機器の導入を促進し、また、費用対効果の測定、さまざまな観点があると思うのだけれども、そのことについての品川区の方向性をお聞かせをいただきたい。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど来のご答弁でもさせていただきましたとおり、介護者の負担軽減、それから、コミュニケーションといったこと以外に、やはり人材不足を解消するために、どういったところを機械化できるか、こういった形の取り組みが今、民間企業中心に進められているということで。","voiceIndex":330,"id":"exchange-134"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、機械というのは、私たちの目に届かないところでも一人一人のそのさまざまな状況をしっかり把握をした上で、データとして残していっているわけだから、それを、何というか、有効に活用すると、相対的に介護サービスの質の向上につながっていくし、それから、人的な削減につながっていくし、当然、介護保険のさまざまな削減につながっていくと思われるので。","respondent":"寺嶋高齢者福祉課長","answer":"繰り返しになりますけれども、そういった情報の収集と必要なものにつきましては積極的に、これは事業者の考え方もありますので、法人が区に対してどのような支援を望んでいるか、こういったことも聞き取りをしながら、ぜひ研究を進めていきたいと考えております。","voiceIndex":332,"id":"exchange-135"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろん民間の設備導入も必要なのですが、当然、品川区の施設もあるわけだから、まず、品川区の施設を先に考えていただきたいなと思うので、そのことをお願いしておきます。そう考えていくと、この人生１００年時代の構想については、全庁挙げてやっていくべき必要があると思うのだけれども、特に高齢者部門での大きな方向性が必要だと思うのだけれども、一つその方向性をお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"単なる負担軽減とか作業の効率化だけではなくて、介護の質の向上も十分視野に入れた機器の開発が進んでいるということは十分認識しておりますので、品川区も積極的にそういったものにつきましては、今後の取り入れも含めた研究検討を進めてまいりたいと思います。","voiceIndex":334,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"私は２３４ページ、児童福祉費の中で、子ども育成についてお聞きしたいと思います。東京都では、子どもに対する保護者による虐待事件が増えてきたことから、保護者の体罰禁止の条例を決めました。誰よりも我が子を愛し、我が子の将来を考え、責任を持って育てていますが、このように家庭内に自治体が介入するようなことは私は適切ではないと考えておりますが、区の見解としてはどのように思われますか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ただいまのご指摘ですが、今、国のほうでも、虐待などが起こっている関係で、児童福祉法の改正法が国会提出に向けて準備中と聞いておりまして、その中でも、報道によれば、体罰を禁止するというようなことが盛り込まれるということになっておりますので、委員がおっしゃるとおり。","voiceIndex":337,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"今、お話、課長から聞けましたけど、実際、では、そこまで自治体で言うならば、その我が子の将来というのは保障していただけるのでしょうか。だけど、結局できてないわけですね。ほんの一部の子かもしれないですけど、それを今度、家庭も放棄しろということになれば、一体誰が見るのですか。やはり親が見るしかないのではないですか。その資格を持たない専門家、児童福祉司が足りないからですか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"なかなかある種概念的なことになってしまうのですけれども、実際に起こっている事件につきましては、しつけのつもりだったということを述べている、いわゆるばか親というのもいっぱいいるわけですので、先ほどの繰り返しになってしまいますけれども、明確な基準というのは。","voiceIndex":339,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"大変な場所です。虐待もある。このようなことを思うと、実際、どうなのかなというのはすごく私は思うのですね。そして、もし行政でできないならできないということをはっきり保護者の方に連絡をして、もう自治体では対応できません、ですから、もう必ずこの親御さんが自分の子どもを見てくださいというような、私は宣言をすべきではないかと思うのですね。それについて、ご見解をお聞かせください。","respondent":"高山子ども育成課長","answer":"とりわけ、心理職につきましては、３０年ぶりに採用をしたということもありまして、現在、その育成に努めているところです。","voiceIndex":341,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"私は、今、課長がおっしゃいましたけど、さまざまこれから人員も増やしていく。でも、時間はどんどん経っていくのですよね。半年、１年、２年、３年、その間にさまざまな事件が起こる可能性があるということで、今、虐待件数も全国は１３万件以上が出ているのですね。これについて、後で見解をお聞かせください。ですから、私は、子どもたちの命や将来にもっと投資するべきだ。ご見解をお聞かせください。","respondent":"品川財政課長","answer":"今後、どういう展開になっていくかわからないところはありますが、そういう展開に合わせて、必要なところに対しては予算を投入していくという、こういう考えです。","voiceIndex":343,"id":"exchange-140"},{"speaker":"石田（し）委員","kind":"質問","question":"４１７ページからの品川区国民健康保健事業について、それと、２４３、２６５の中にあるいわゆる学習支援について、お伺いをします。時間があったら、２３９ページの児童相談所移管推進事業についてお伺いしていきます。その制度を理解をしてもらわなければいけないのかなと思うのですが、１つは、いわゆる外国人の悪用対策はどのようにやられているのか。もしわかれば、教えてください。","respondent":"三ッ橋国保医療年金課長、廣田子ども家庭支援課長、矢木生活福祉課長","answer":"レセプト点検ですけれども、こちら、レセプト点検につきましては、業務の適正化について対応しておりまして、一次審査、二次審査、また。未来を拓く学習支援事業につきましては、いわゆるドリームサポートと言っている事業でして、高校生を対象としまして、大学、専門学校の受験であるとか。２６５ページの学習支援事業等ですが、こちらは平成２７年４月から行ってございまして、対象者といたしましては、生活保護世帯を含む生活困窮世帯のお子様。","voiceIndex":346,"id":"exchange-141"},{"speaker":"石田（し）委員","kind":"質問","question":"なので、こういった部分も含めて、区として、第２期に向けて、その医療費の適正化というのは取り組むということなので、ここはぜひ、新宿の事例も含めて、区で取り入れられるものはしっかりそういった部分も見ていただければなというふうに思って、質問しましたので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-142"},{"speaker":"安藤委員","kind":"質問・要望","question":"保育士について伺います。私は、先の代表質問で待遇改善を求めましたが、区は保育士の賃金について、月平均で６万７,１９０円の改善をしているので、区が独自に賃金助成を行う考えはないと答弁しました。５３２人分は、区内私立保育園の総数に照らすと少ないと思うのですけれども、社会福祉法人の認可保育園ですとか、認証保育所、認可外保育施設等が含まれているのかどうか伺います。","respondent":"大澤保育支援課長","answer":"対象者ですけれども、こちらは全園ですので、４９園に調査をかけてありますが、前年や前々年度と比較をするために、１年間、常勤保育士として勤務された方を対象としていますので、年度途中に開設した２園を除いて、４７園分、また、対象が６８０人いますが、そのうち。","voiceIndex":352,"id":"exchange-143"},{"speaker":"安藤委員","kind":"確認","question":"私、保育士に直接記入してもう形式なのかどうかというのも伺ったので、後で確認させてください。それと、アンケートはしたけれども、その５３２人でまとめたのには、認証も認可外も入ってないということでしたね。社会福祉法人の認可保育園についてはどうだったのか、ちょっとお願いできますか。","respondent":"大澤保育支援課長","answer":"保育士が直接というよりは、園が支払った金額を園ごとに分けて提出していただいているものです。社会福祉法人の保育園も４９園の中に含まれてあります。","voiceIndex":354,"id":"exchange-144"},{"speaker":"安藤委員","kind":"質問","question":"アンケート回答者５３２人分の内訳についてなのですが、社会福祉法人と株式会社の割合、とれぐらいなのか、それぞれについて、２０代、３０代の年齢は何％ぐらいなのか、わかれば、伺います。","respondent":"大澤保育支援課長","answer":"社会福祉法人は１７園あります。２０代の保育士が５５％です。３０代の保育士は、２８％になります。","voiceIndex":356,"id":"exchange-145"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、平均、この６万７,０００円に改善されたと、認証や認可外は除くのですけれども、そちらの実態等も大変なのでつかんでほしいのですが、その、でも、６万７,０００円改善されたとは言います。このことをもって、品川区は保育士という仕事に見合うものになっていると思うのかどうか、伺います。今、課題となっている保育士不足を解消するのに十分だと思っているのかどうか、伺います。","respondent":"大澤保育支援課長","answer":"一時期、保育士の給与が１０万円低いのではないかというふうに報道されたりしていましたけれども、今、そこから、６万７,１９０円上がっておりますので、一定、差は縮まっているというふうに認識しています。","voiceIndex":358,"id":"exchange-146"},{"speaker":"安藤委員","kind":"質問","question":"やはりまだまだ、私、足りないと思うのですね。介護士の待遇改善もさらに待ったなしです。区も、介護士については、代表質問の答弁で、上昇が図られているという認識を示しましたが、そういうのであれば、保育士のように、区はどのように区内各法人の介護士の賃金を把握しているのか、していないのか、伺います。区自身の補助に乗り出さないとだめなのではないかと思いますが、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"そういった中で、研修等の受講、資格の取得等がその賃金の加算に加わってくるということもありますので、支援策としては、今後も続けていきたいと考えております。","voiceIndex":360,"id":"exchange-147"},{"speaker":"安藤委員","kind":"質問・要望","question":"報告が出ているというだけなので、区みずからがつかんでないということだと思います。しっかりと、保育でやっているような、まず、実態調査をしてください。その上で、やはりきちんと希望を持って働けるような、そういう待遇にしていただくよう努力するよう求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-148"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、２２３ページ、高齢者住宅生活支援サービス事業、２４５ページ、保育園運営費、２５９ページ、オアシスルーム、２６１ページ、生活保護者自立支援事業、この４点をお伺いしたいと思います。保育園運営費に関連して、大きく２つ質問させていただきたいと思います。延長料金体系の１時間単位になっている料金は、各自の保育料によって料金が設定されているとも伺っております。","respondent":"佐藤保育課長","answer":"一番安くて、１時間２００円、一番高くて３時間３０分で１,４００円というところでございまして、一応２３区、調べたのですけれども、１時間単位で料金を徴収しているのは２３区中４区で、それ以外のところは、月額とか日額で、例えば使いたい放題とか。","voiceIndex":364,"id":"exchange-149"},{"speaker":"こんの委員","kind":"質問","question":"しかし、１時間延長しなくても、例えば１５分や３０分の延長でお迎えに間に合うということもあると思いますし、そもそも、この延長料金は家計の負担にもつながっているという、こうした声も伺います。細分化をされたほうがよいのではないかと、このように考えるわけですけれども、いかがでしょうか。","respondent":"佐藤保育課長","answer":"委員ご提案の例えば１５分単位で刻むとか、その辺に関しましては、電算システムを改修すれば対応できるところでもありますし、園運営でも大きな変更になるのは聞いてはおりません。幼児教育の無償化もありますので、あわせて、総合的にいろいろ考えていきたいと思います。","voiceIndex":366,"id":"exchange-150"},{"speaker":"こんの委員","kind":"質問","question":"ぜひよろしくお願いいたします。次の大きな質問です。そこで、在宅に特化したこの一時預かり制度があるように、就労しながらの子育てに特化した一時預かり制度が必要と考えますけれども、そうしたおばちゃんちのほかに、何か一時預かりという制度、こうしたものを設けられる、こうしたことは考えられませんでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"就労にかかわらず、ファミリーサポート事業が使えますので、こちらも選択肢の一つとして考えていただければと思います。","voiceIndex":368,"id":"exchange-151"},{"speaker":"こんの委員","kind":"質問","question":"今おっしゃってくださったのは、緊急時も含めて、なかなか使えない状態ですね。マッチングの問題もあって、なかなか非常に難しいところであります。在園する園で、就労する保護者の子育て支援として、一時預かり事業が在園の保育園でもできるのではないかと考えますけれども、いかがでしょうか。","respondent":"佐藤保育課長","answer":"保育園は、保護者の方の自己負担で大体１３％ぐらいで、それ以外の全ては何らかの税で賄っている施設ですので、やはり児童福祉施設というような位置づけに沿って、厳格に運営していくのが今現在の考えです。","voiceIndex":370,"id":"exchange-152"},{"speaker":"こんの委員","kind":"質問・要望","question":"一時保育というのは１日預かることですが、一時預かりで一定の時間だけを預かっていただきたい。次に行きます。そうしたことへの対応で、特にご相談を受けたのは０歳児、１歳児、こうした年齢が低いお子さんの定員が、場所によって３名のところと６名のところと差がありますので、こうした０歳児の定員を拡大をする、あるいは、緊急時の対応、こうしたことを考えていただきたいのですが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"この制度を、委員おっしゃられるような緊急利用に拡大できるかどうかということは今後の検討になるかと思います。０歳の定員を拡大するかどうかということは、ちょっと４月からまた２施設、新しく増えますので、全体的な利用状況を見ながら、検討してまいりたいと思います。","voiceIndex":372,"id":"exchange-153"},{"speaker":"こんの委員","kind":"質問","question":"行政サービスという観点から、このことをご検討くださるということですので、ぜひよろしくお願いいたします。次に参ります。生活保護自立支援事業に関連しまして、受給者の問題行動への対応について、お聞きしたいと思います。近隣からの苦情、緊急通報、こうしたことについて、所管ではどのような対応をされていますでしょうか。","respondent":"矢木生活福祉課長","answer":"というのは、それによって、その方が生活保護受給者だということをこちらが言ってしまっているのと同じことになるからです。ですので、状況をお伺いして、もし仮にその方が生活保護の受給者であるならば、必要な対応をしますというような、そういう形でまずお話を伺います。","voiceIndex":374,"id":"exchange-154"},{"speaker":"こんの委員","kind":"質問","question":"さまざまに連携をとりながら対応してくださっているです。こうしたことへのさらなる連携をとるという意味で、私は他課との連携で、こうした問題行動に対する対応が、町の防犯的観点から、生活安全担当課と連携をして、こうしたことに取り組むということが１つ考えられるのですが、いかがでしょうか。","respondent":"矢木生活福祉課長","answer":"委員ご指摘のとおり、連携してまいります。","voiceIndex":376,"id":"exchange-155"},{"speaker":"渡部委員","kind":"質問・要望","question":"高齢者クラブ支援は、ちょっと大くくりな話としてお伺いするのですけど、町会や自治会があって、高齢者クラブはその町会の中にあったりするのだけど、高齢者クラブの数というのは町会の数に比べても少ないということで、これ、ないところもある。でもって、結構毎年、毎年、数というのが動いたりすることがあるのですね。","respondent":"宮尾高齢者地域支援課長","answer":"私どもも、できる限り、高齢者クラブのために、日々、お話をいつも乗らせていただいて、しかるべきサポートをさせていただいているところです。","voiceIndex":379,"id":"exchange-156"},{"speaker":"渡部委員","kind":"質問・要望","question":"ちょうど今日、民生費だったので、児童センターと言ったのは、例えばある技術者の方とかであれば、例えば工作教室を児童センターで開きたいのだけど、どなたか近隣でこういうことができる方、いらっしゃいますか、お手伝いいただけますかとか、例えば音楽をこうやりたい、もっと言うと、変な言い方かもしれないけど、児童センターの業務というか、夕方の時間で宿題見たりもするので。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘の社会福祉協議会ですけれども、ボランティアセンターのホームページ、ありまして、よくよく読めばということではあるのですけれども、確かに、希望した方が見ていったときに、わかりづらいというご指摘をいただいた、今現在もいただきましたので、その辺は。","voiceIndex":381,"id":"exchange-157"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、例えば、子ども関係だったら、こういうのもある、こういうところへ行ってください、高齢者関係だったらこういうのがある、こういうところへ行ってください、障害をお持ちの方に対してお手伝いいただけるのであれば、こういうところがありますから、ここに連絡してくださいみたいなのを少し細かくわかりやすく、もしくは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":385,"id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1096#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":131461,"voices":386}}]);
